export const MARKDOWN_BUNDLE: Record<string, string> = {
  "en/about/code-of-conduct": "# Code of Conduct\n\n## Contributor Covenant Code of Conduct - Version 2.1\n\nNucleify follows the [Contributor Covenant Code of Conduct 2.1](https://www.contributor-covenant.org/version/2/1/code_of_conduct/).\n\n---\n\n## Our pledge\n\nWe as members, contributors, and leaders pledge to make participation in our community a harassment-free experience for everyone, regardless of age, body size, visible or invisible disability, ethnicity, sex characteristics, gender identity and expression, level of experience, education, socio-economic status, nationality, personal appearance, race, caste, color, religion, or sexual identity and orientation.\n\nWe pledge to act and interact in ways that contribute to an open, welcoming, diverse, inclusive, and healthy community.\n\n---\n\n## Our standards\n\n### Positive behavior\n\nExamples of behavior that contributes to a positive environment:\n\n- Demonstrating empathy and kindness toward other people\n- Being respectful of differing opinions, viewpoints, and experiences\n- Giving and gracefully accepting constructive feedback\n- Accepting responsibility and apologizing to those affected by our mistakes, and learning from the experience\n- Focusing on what is best not just for us as individuals, but for the overall community\n\n### Unacceptable behavior\n\nExamples of unacceptable behavior:\n\n- The use of sexualized language or imagery, and sexual attention or advances of any kind\n- Trolling, insulting or derogatory comments, and personal or political attacks\n- Public or private harassment\n- Publishing others' private information, such as a physical or email address, without their explicit permission\n- Other conduct which could reasonably be considered inappropriate in a professional setting\n\n---\n\n## Enforcement responsibilities\n\nCommunity leaders are responsible for clarifying and enforcing our standards of acceptable behavior and will take appropriate and fair corrective action in response to any behavior that they deem inappropriate, threatening, offensive, or harmful.\n\nCommunity leaders have the right and responsibility to remove, edit, or reject comments, commits, code, wiki edits, issues, and other contributions that are not aligned to this Code of Conduct, and will communicate reasons for moderation decisions when appropriate.\n\n---\n\n## Scope\n\nThis Code of Conduct applies within all community spaces, and also applies when an individual is officially representing the community in public spaces. Examples of representing our community include using an official email address, posting via an official social media account, or acting as an appointed representative at an online or offline event.\n\n---\n\n## Enforcement\n\nInstances of abusive, harassing, or otherwise unacceptable behavior may be reported to the community leaders responsible for enforcement at **business@nucleify.io**.\n\nAll complaints will be reviewed and investigated promptly and fairly.\n\nAll community leaders are obligated to respect the privacy and security of the reporter of any incident.\n\n---\n\n## Enforcement guidelines\n\nCommunity leaders will follow these Community Impact Guidelines in determining the consequences for any action they deem in violation of this Code of Conduct:\n\n### 1. Correction\n\n**Community impact:** Use of inappropriate language or other behavior deemed unprofessional or unwelcome in the community.\n\n**Consequence:** A private, written warning from community leaders, providing clarity around the nature of the violation and an explanation of why the behavior was inappropriate. A public apology may be requested.\n\n### 2. Warning\n\n**Community impact:** A violation through a single incident or series of actions.\n\n**Consequence:** A warning with consequences for continued behavior. No interaction with the people involved, including unsolicited interaction with those enforcing the Code of Conduct, for a specified period of time. This includes avoiding interactions in community spaces as well as external channels like social media. Violating these terms may lead to a temporary or permanent ban.\n\n### 3. Temporary ban\n\n**Community impact:** A serious violation of community standards, including sustained inappropriate behavior.\n\n**Consequence:** A temporary ban from any sort of interaction or public communication with the community for a specified period of time. No public or private interaction with the people involved, including unsolicited interaction with those enforcing the Code of Conduct, is allowed during this period. Violating these terms may lead to a permanent ban.\n\n### 4. Permanent ban\n\n**Community impact:** Demonstrating a pattern of violation of community standards, including sustained inappropriate behavior, harassment of an individual, or aggression toward or disparagement of classes of individuals.\n\n**Consequence:** A permanent ban from any sort of public interaction within the community.\n\n---\n\n## Attribution\n\nThis Code of Conduct is adapted from the [Contributor Covenant](https://www.contributor-covenant.org), version 2.1, available at [https://www.contributor-covenant.org/version/2/1/code_of_conduct.html](https://www.contributor-covenant.org/version/2/1/code_of_conduct.html).\n\nCommunity Impact Guidelines were inspired by [Mozilla's code of conduct enforcement ladder](https://github.com/mozilla/diversity).\n\nFor answers to common questions about this code of conduct, see the [FAQ](https://www.contributor-covenant.org/faq). Translations are available at [https://www.contributor-covenant.org/translations](https://www.contributor-covenant.org/translations).\n\n---\n\n## Related\n\n- [Coding Standards](/en/docs/about/coding-standards) - technical contribution guidelines\n- [People & Credits](/en/docs/about/people-and-credits) - team and acknowledgments\n",
  "en/about/coding-standards": "# Coding Standards\n\nConventions for readable, consistent code across the Nucleify monorepo. When in doubt, match surrounding files in the package you are editing.\n\n---\n\n## Monorepo structure\n\n```txt\nnucleify/\n├── web/               # @nucleify/web - Nuxt landing\n├── admin/             # @nucleify/admin - Nuxt admin\n├── docs/              # @nucleify/docs - Astro docs\n├── compiler/          # @nucleify/compiler - portable UI compiler\n├── shared_modules/    # six exported nuc_* feature modules\n├── portable/nui/      # design tokens\n├── overrides/         # per-package file overrides\n├── supabase/          # merged DB config\n└── .config/           # shared tooling\n```\n\nCanonical product paths: `web/src/` (not root `modules/` or `nuxt/` as srcDir). UI primitives are `nui-*`, not an `ad-*` tree. Auth lives in `nuc_api`.\n\n---\n\n## Package commands\n\n| Package | Dev command |\n|---------|-------------|\n| `web/` | `make web` or `pnpm dev` |\n| `admin/` | `make admin` or `pnpm admin` |\n| `docs/` | `make docs` or `pnpm docs` |\n| `compiler/` | `make compiler` |\n\nBootstrap: `make run`. Product shell: `make web`. Portable emit demos: `make vue` / `react` / `nuxt` / `next` / `solid` / `svelte` (not the product app).\n\n---\n\n## Shared module structure\n\n```txt\nshared_modules/nuc_example/\n├── config.json\n├── nuc_example.ts           # registerNucExample (Vue plugin)\n├── index.ts                 # Vue barrel\n├── index.react.ts           # React barrel (when needed)\n├── _index.scss\n├── supabase/api/handle.ts\n├── constants/\n├── types/\n├── utils/\n├── components/              # optional\n└── vitests/\n```\n\n**Import rules:**\n\n- Inside modules: relative imports only\n- Never import from `web/`, `admin/`, or `docs/` inside modules\n- Never `import from 'nucleify'` inside modules (circular)\n- Apps import via `modules/…` alias or explicit `shared_modules/…` paths\n\n---\n\n## Web app structure\n\n```txt\nweb/src/\n├── pages/[lang]/            # thin i18n wrappers\n├── pages/home/              # landing composition\n├── plugins/modules.ts       # registerNuc*\n├── composables/             # app-specific only\n├── layouts/\n├── assets/                  # SCSS entry\n├── nucleify.ts              # re-exports\n└── server/api/[...slug].ts  # gateway\n```\n\n- Vue SFCs: `<script setup lang=\"ts\">`\n- UI: `nui-*` from `nucleify-ui`\n- Domain logic: `shared_modules/`, not `web/src/`\n\n---\n\n## File and folder naming\n\n| Kind | Convention | Example |\n|------|------------|---------|\n| Vue SFC | PascalCase | `NucHomeHero.vue` |\n| Composable | `use_` + snake_case | `use_dark_mode.ts` |\n| React hook sibling | `.react.ts` | `use_dark_mode.react.ts` |\n| Portable component | PascalCase + `.nuc.tsx` | `Counter.nuc.tsx` |\n| Utils | snake_case | `api_request.ts` |\n| Types | snake_case files | `interfaces.ts`, `variables.ts` |\n| Tests | `*.test.ts` in `vitests/` | `darken_color.test.ts` |\n| SCSS partials | `_name.scss` | `_mixins.scss` |\n\n---\n\n## TypeScript\n\n- Strict typing - avoid `any` unless Nuxt config forces it (document with biome-ignore)\n- Export types from `types/` - do not duplicate interfaces across files\n- Use `.react.ts` type siblings when React props diverge from Vue\n\n---\n\n## Vue components\n\n```vue\n<script setup lang=\"ts\">\nimport { ref } from 'vue'\nimport type { SomeType } from 'modules/nuc_example/types/interfaces'\n\nconst props = defineProps<{ id: string }>()\nconst open = ref(false)\n</script>\n\n<template>\n  <nui-button @click=\"open = !open\">{{ props.id }}</nui-button>\n</template>\n```\n\n- Prefer composition API with `<script setup>`\n- Use `nui-*` for primitives; module components for domain UI\n\n---\n\n## Portable components\n\nAuthor in `*.nuc.tsx` per `compiler/PORTABLE.md`:\n\n- No stores, routers, or Supabase inside portable files\n- Props + events only for external coupling\n- Run `pnpm compiler:build` after changes; commit authoring + emit\n- Import edits: `pnpm compiler -- import --from=vue|react|solid|svelte`\n- Do not re-export `*.nuc.tsx` from public barrels (`index.ts`, `modules.ts`, …)\n- Breaking IR changes bump `IR_VERSION` and migrate fixtures in the same PR\n\n---\n\n## API handlers\n\n- Entry: `handle.ts` exports `handle*Api`\n- Register in `shared_modules/nuc_api/supabase/api/gateway_dispatch.ts`\n- Return `apiNotHandled()` for non-matching prefixes\n- Use `withGatewayUser` for authenticated routes\n- Enable RLS on exposed tables\n\n---\n\n## SCSS\n\n- Module styles: `shared_modules/nuc_*/styles/`\n- App entry imports module `_index.scss` files\n- Lint: `pnpm slint`\n\n---\n\n## Testing\n\n- Module tests: `shared_modules/nuc_*/vitests/`\n- Nuxt tests: `web/vitests/`\n- Run `pnpm tests` before commit\n- Meaningful behavior tests - avoid asserting implementation details\n\n---\n\n## Lint & format\n\n```bash\npnpm check       # Biome (lint + format check)\npnpm write       # Biome auto-fix\npnpm typeslint   # tsc --noEmit -p web/tsconfig.json\npnpm slint       # Stylelint on SCSS\npnpm tests       # Vitest\n```\n\nHusky runs these on pre-commit via `.config/bash/hook-checks.sh` (pre-push is a no-op).\n\n---\n\n## Git & commits\n\n- Focused commits - one concern per change when possible\n- Do not commit `.env`, emit demos (`vue/demo`, etc.), or `*.ir.json`\n- Follow existing commit message style in the repo\n\n---\n\n## Cursor rules & agents\n\n- Monorepo rules: `.cursor/rules/`\n- Package rules: `{pkg}/.config/rules/`\n- Sync: `pnpm sync-rules`\n- Feature workflow agents: `web/.cursor/agents/`\n\n---\n\n## Related docs\n\n- [Modules](/en/docs/core-concepts/modules)\n- [Feature-Sliced Design](/en/docs/core-concepts/feature-sliced-design)\n- [Vitest](/en/docs/tests/vitest)\n- [Code of Conduct](/en/docs/about/code-of-conduct)\n\nRoot reference: `CODE_STANDARDS.md` in the repository (keep in sync with this page).\n",
  "en/about/people-and-credits": "# People & Credits\n\nThe people and projects that make Nucleify possible.\n\n---\n\n## Core team\n\n### Creator & lead\n\n| Name | Role | GitHub |\n|------|------|--------|\n| Szymon Wieczorek | Architecture, compiler, modules, full-stack development | [@szymcode](https://github.com/szymcode) |\n\n---\n\n## Contributors\n\nThank you to everyone who has contributed to Nucleify! (Human contributors only - automation bots are omitted.)\n\n| Name | GitHub |\n|------|--------|\n| Katarzyna Śmierzchalska | [@KatarzynaS97](https://github.com/KatarzynaS97) |\n| Kamil D. | [@K4mD4m](https://github.com/K4mD4m) |\n| Marcin Fuks | [@J0jeQ](https://github.com/J0jeQ) |\n| Jakub Malik | [@JakubMalik](https://github.com/JakubMalik) |\n| Kacper Bujak | [@kbujak09](https://github.com/kbujak09) |\n| – | [@karol199393](https://github.com/karol199393) |\n| – | [@domizalewska](https://github.com/domizalewska) |\n| Kamil Błoski | [@kbloski](https://github.com/kbloski) |\n| – | [@Kacper658](https://github.com/Kacper658) |\n| Mateusz Szymański | [@dezmerek](https://github.com/dezmerek) |\n| – | [@pysifoo](https://github.com/pysifoo) |\n\nAll contributors are listed on our [GitHub Contributors](https://github.com/Nucleify/Nucleify/graphs/contributors) page.\n\n---\n\n## Built with\n\nNucleify is built on top of open source projects:\n\n### Backend & data\n\n| Project | Description |\n|---------|-------------|\n| [Supabase](https://supabase.com) | PostgreSQL, Auth, Storage, Edge Functions |\n| [@supabase/supabase-js](https://github.com/supabase/supabase-js) | JavaScript client |\n\n### Frontend\n\n| Project | Description |\n|---------|-------------|\n| [Vue 3](https://vuejs.org) | Canonical UI framework (Nuxt/Vue source) |\n| [Nuxt 4](https://nuxt.com) | Vue full-stack framework |\n| [React 19](https://react.dev) | Compiler-generated UI target (convert / emit) |\n| [Next.js 15](https://nextjs.org) | React full-stack framework |\n| [Solid](https://www.solidjs.com) | Convert / emit target (signals) |\n| [Svelte](https://svelte.dev) | Convert / emit target (Svelte 5 runes) |\n| [nucleify-ui](https://www.npmjs.com/package/nucleify-ui) | Lit web component library (`nui-*`) |\n| [Lit](https://lit.dev) | Web components for design system primitives |\n\n### Compiler & tooling\n\n| Project | Description |\n|---------|-------------|\n| [TypeScript](https://www.typescriptlang.org) | Type safety across the stack |\n| [Vite](https://vitejs.dev) | Build tool (Nuxt / Vitest) |\n| [SCSS](https://sass-lang.com) | CSS preprocessor |\n| [Biome](https://biomejs.dev) | Formatting and linting |\n| [Vitest](https://vitest.dev) | Unit and integration tests |\n| [pnpm](https://pnpm.io) | Monorepo package manager |\n| [Astro](https://astro.build) | Documentation site (`@nucleify/docs`) |\n\n---\n\n## Architecture influences\n\n| Idea | Source |\n|------|--------|\n| Feature-Sliced Design | [feature-sliced.design](https://feature-sliced.design) - domain-first module layout |\n| Atomic Design | [Brad Frost](https://atomicdesign.bradfrost.com) - SCSS component hierarchy in `nuc_colors` |\n| Portable UI / IR compilers | Nucleify's own `@nucleify/compiler` - `*.nuc.tsx` → Vue + React + Solid + Svelte |\n\n---\n\n## Special thanks\n\n- The Supabase, Vue, React, Nuxt, Astro, Svelte, and Solid communities\n- Everyone who has reported bugs or suggested features\n- Open source maintainers everywhere\n\n---\n\n## Want to contribute?\n\nWe welcome contributions of all kinds:\n\n- Bug reports\n- Feature suggestions\n- Documentation improvements\n- Code contributions\n\nStart with [Coding Standards](/en/docs/about/coding-standards) and [Code of Conduct](/en/docs/about/code-of-conduct).\n\n---\n\n## License\n\nNucleify is open source software licensed under the [MIT License](https://opensource.org/licenses/MIT).\n",
  "en/about/philosophy": "# Philosophy\n\n> Build once. Move to any framework - without rewriting the product.\n\n**Migration is the product.** Shared modules are the nucleus. An IR-first compiler is how shells change. Seven modern web runtimes.\n\n---\n\n## The problem\n\nTeams lock into a stack early - Vue or React, Nuxt or Next - then pay a rewrite tax when the market, hiring, or a client demands another framework. Auth, i18n, theming, and API shape get copied into every project. Component-only toolchains leave the app, the routes, and the domain behind.\n\nNucleify treats **migration between technologies** as the durable layer of the monorepo - not a side experiment. Coverage is seven shells: **Vue · React · Nuxt · Next · Astro · Svelte · Solid**.\n\n---\n\n## The vision\n\nOne nucleus. Three product surfaces. Seven shells. One migration pipeline.\n\n1. **Shared modules** - API, SQL, UI, and domain logic in `shared_modules/`\n2. **Three surfaces** - `web/`, `admin/`, and `docs/` from the same nucleus\n3. **Migrate as a command** - portable emit for UI, product convert for whole apps, import back from dirty emit - without rewriting the business\n4. **One Supabase backend** - gateway-mediated, module-owned SQL\n\nDay-to-day editing stays on Nuxt (`web/`). Switching shells is a compiler pass, not a rewrite project.\n\n---\n\n## The nucleus metaphor\n\nLike a cell nucleus, Nucleify coordinates the product. Each exported `nuc_*` module is a self-contained unit - frontend utils, optional API handlers, migrations, tests - that can be understood and tested independently.\n\n- **Self-contained modules** - vertical slices, not scattered layers\n- **Clear boundaries** - apps compose; modules do not import apps\n- **Organic growth** - add or remove modules without rewiring the monorepo\n- **Collective strength** - one domain model across web, admin, docs, and every shell\n\n---\n\n## Core principles\n\n### 1. Any stack → any other\n\nThis is the core loop. Portable `*.nuc.tsx` components emit through a custom IR to Vue, React, Solid, Svelte, and Astro. Product shells (`web` / `admin`) convert with a single command - including an external Nuxt-like folder or git URL via `--path` / `--git` (see [Compiler](/en/docs/core-concepts/compiler)). Emit edits import back to source. The business does not fork per host.\n\n```bash\nmake web TARGET=next\nmake web TARGET=solid\nmake web TARGET=svelte\nmake web TARGET=astro\nmake admin TARGET=next\nmake admin TARGET=solid\nmake admin TARGET=svelte\n```\n\nFramework choice becomes a **build target**, not an architectural fork.\n\n### 2. Modules over monoliths\n\nDomain logic lives in `shared_modules/nuc_*`, not duplicated across apps. See [Feature-Sliced Design](/en/docs/core-concepts/feature-sliced-design).\n\n### 3. Gateway, not spaghetti\n\nPrivileged server access flows through `web/src/server/api/[...slug].ts`. Clients never hold service keys. Modules register handlers; the gateway dispatches.\n\n### 4. Convention over configuration\n\nSplit Nuxt config, consistent module layout, Makefile shortcuts, Husky-enforced checks - predictable paths reduce decision fatigue.\n\n### 5. Overrides for forks, modules for sharing\n\nWhite-label diffs use `overrides/`. Cross-product behavior belongs in `shared_modules/`.\n\n### 6. Compiler honesty\n\nPortable authoring has explicit allowed/forbidden lists (`compiler/PORTABLE.md`). The IR bridges frameworks - we do not pretend Vue and React are identical. Round-trip import and product convert are first-class; a one-way component dump is not the goal.\n\n---\n\n## Canonical vs generated shells\n\n| Day-to-day (Nuxt) | Migrate / emit (convert) |\n|---------------------|-------------------------|\n| Edit Nuxt + Vue in `web/` | Next, Solid, Svelte, Astro product shells + portable demos |\n| Source of truth | Generated mirrors when a client or team needs another shell |\n\nConverted shells are not a second hand-maintained codebase. Fix the nucleus, re-run convert. Product messaging always lists **all seven shells**, even when daily editing stays on Nuxt.\n\n---\n\n## Design system stance\n\nUI primitives are **framework-agnostic Lit components** (`nui-*` from `nucleify-ui`). Tokens live in `portable/nui/`. Every shell wraps the same custom elements - no duplicate button implementations per framework.\n\n---\n\n## Quality bar\n\nThe monorepo enforces quality on pre-commit (pre-push is a no-op):\n\n- Bash suite, Biome, TypeScript (web), Stylelint\n- Nuxt production build\n- Vitest (web + shared) and compiler tests / emit check\n\n---\n\n## What Nucleify is not\n\n- Not a meta-framework that hides hosts - the seven shells stay visible\n- Not a component-only emit layer - product convert moves whole apps with shared modules\n- Not a low-code builder - you write real TypeScript\n- Not a hosted SaaS - you own Supabase and deployment\n- Not “mystery modules” - six exported `nuc_*` packages power the product today\n\n---\n\n## Related docs\n\n- [Introduction](/en/docs/getting-started/introduction) - technical overview\n- [Modules](/en/docs/core-concepts/modules) - module architecture\n- [Compiler](/en/docs/core-concepts/compiler) - emit and convert\n- [Coding Standards](/en/docs/about/coding-standards) - day-to-day conventions\n",
  "en/configuration/environment": "# Environment\n\nNucleify reads environment variables from a single **repo root** `.env` file. `make run` creates it from `web/.config/.env.example`. Nuxt loads vars through `web/.config/nuxt/load-env.ts` before config evaluation.\n\n---\n\n## Setup\n\n```bash\nmake run\n# edits .env at repo root\n```\n\nNever commit `.env`. Example templates live in `web/.config/`:\n\n| File | Purpose |\n|------|---------|\n| `.env.example` | Local development (copied by `make run`) |\n| `.env.ci.example` | CI pipeline reference |\n| `.env.test.example` | Test environment reference |\n\n---\n\n## Application\n\n| Variable | Example | Description |\n|----------|---------|-------------|\n| `APP_NAME` | `Nucleify` | Application display name |\n| `APP_ENV` | `local` | `local` / `production` / `testing` |\n| `APP_DEBUG` | `true` | Debug flag |\n| `NUXT_PUBLIC_APP_URL` | `http://localhost:3000` | Public app URL (also exposed as runtime config) |\n\n---\n\n## Supabase\n\n| Variable | Required | Description |\n|----------|----------|-------------|\n| `SUPABASE_URL` | Yes (for API routes) | Project URL |\n| `SUPABASE_KEY` | Client | Anon/public key - safe for browser via runtime config |\n| `SUPABASE_SERVICE_ROLE_KEY` | Server | Service role - **never** expose to client |\n| `SUPABASE_EDGE_BASE` | Optional | Edge functions base URL (defaults from `SUPABASE_URL`) |\n\nThe Nitro gateway in `web/src/server/api/[...slug].ts` reads `SUPABASE_URL` and `SUPABASE_SERVICE_ROLE_KEY` from Nitro runtime config (sourced from these env vars). Missing values return HTTP 503 for module routes; smoke endpoints `/api` and `/api/test` still respond.\n\nRuntime mapping (`web/.config/nuxt/runtime.ts`):\n\n```typescript\nexport const runtimeConfig = {\n  supabaseServiceRoleKey: process.env.SUPABASE_SERVICE_ROLE_KEY || '',\n  public: {\n    supabaseUrl: process.env.SUPABASE_URL || '',\n    supabaseKey: process.env.SUPABASE_KEY || '',\n    supabaseEdgeBase: process.env.SUPABASE_EDGE_BASE || `${process.env.SUPABASE_URL || ''}/functions/v1`,\n    appUrl: process.env.NUXT_PUBLIC_APP_URL || 'https://nucleify.io',\n    apiUrl: process.env.NUXT_PUBLIC_API_URL || '/api',\n    appEnv: process.env.APP_ENV || 'production',\n  },\n}\n```\n\n---\n\n## Nuxt / Nitro\n\n| Variable | Example | Description |\n|----------|---------|-------------|\n| `SSR` | `true` | Server-side rendering |\n| `NITRO_PRESET` | `cloudflare` | Deployment preset for Nitro |\n| `PRERENDER_ROUTES` | `/home,/investor,/404` | Comma-separated static routes (docs live on docs.nucleify.io) |\n| `PRERENDER_CRAWL_LINKS` | `true` | Follow links during prerender |\n| `PRERENDER_IGNORE` | `/settings` | Routes to skip |\n| `PRERENDER_LOCALES` | `en,pl,vn` | Locales included in prerender |\n| `DEV_TOOLS` | | Nuxt DevTools toggle |\n\n---\n\n## Nucleify-specific\n\n| Variable | Example | Description |\n|----------|---------|-------------|\n| `NUC_SUBMODULES_BRANCH` | `main` | Branch for `prepare:submodules` script |\n| `NUC_SUBMODULES_CHECK` | `1` | Skip existing dirs when preparing submodules |\n| `NUC_ALLOWED_ORIGINS` | | CORS allowlist |\n| `NUC_ALLOWED_ORIGINS_PATTERNS` | | CORS pattern allowlist |\n| `NUC_CONVERT_DOCUMENTS_URL` | | External document conversion service |\n\n---\n\n## Integrations (optional)\n\nThe example `.env` includes placeholders for Calendly and Google Calendar OAuth. Fill these only if you enable those integrations in your deployment.\n\n| Group | Variables |\n|-------|-----------|\n| Calendly | `CALENDLY_CLIENT_ID`, `CALENDLY_CLIENT_SECRET`, `CALENDLY_WEBHOOK_SIGNING_KEY`, … |\n| Google Calendar | `GOOGLE_CALENDAR_CLIENT_ID`, `GOOGLE_CALENDAR_CLIENT_SECRET`, … |\n\n---\n\n## Product shells (Next / Solid / Svelte)\n\nGenerated Next shells read Supabase vars with both naming conventions where supported:\n\n- `NEXT_PUBLIC_SUPABASE_URL` or `SUPABASE_URL`\n- `SUPABASE_SERVICE_ROLE_KEY` (server only)\n\nSolid and Svelte product shells (`web-solid/`, `web-svelte/`, …) use the same root `SUPABASE_*` names via Vite `import.meta.env`. Keep one root `.env` - Nuxt and all product-convert codegen paths resolve from the monorepo root.\n\n---\n\n## Local Supabase workflow\n\nWith Supabase CLI linked to your project:\n\n```bash\npnpm supabase:migrations:apply:local\npnpm supabase:seeders:apply:local\n# or:\npnpm supabase:setup:local\n```\n\nSee [Supabase](/en/docs/configuration/supabase) for migration merge details.\n\n---\n\n## Security checklist\n\n1. **Never** commit `SUPABASE_SERVICE_ROLE_KEY`\n2. Expose only `SUPABASE_KEY` (anon) to the client via `runtimeConfig.public`\n3. Privileged DB operations go through `/api/*` gateway handlers\n4. Review `NUC_ALLOWED_ORIGINS*` before production deploy\n\n---\n\n## Related docs\n\n- [Installation](/en/docs/getting-started/installation) - first-time `.env` creation\n- [Web & Admin](/en/docs/configuration/web) - runtime config and Nuxt split config\n- [Supabase](/en/docs/configuration/supabase) - database and migrations\n",
  "en/configuration/supabase": "# Supabase\n\nNucleify uses [Supabase](https://supabase.com) for PostgreSQL, Auth, Storage, and Edge Functions. Database schema and seed data are **owned by feature modules** in `shared_modules/nuc_*/supabase/` and merged at the monorepo level under `supabase/`.\n\nServer access from Nuxt goes through the Nitro API gateway - not direct service-role calls from the browser. The same applies to generated shells (Next, Solid, Svelte): they share the same Supabase instance and module model.\n\n---\n\n## Architecture\n\n```txt\nBrowser\n  → /api/*  (web/src/server/api/[...slug].ts)\n  → dispatchSupabaseApiGateway()\n  → nuc_*/supabase/api/handle.ts\n  → Supabase (PostgreSQL, Auth, Edge Functions)\n```\n\nGateway registry:\n\n```typescript\n// shared_modules/nuc_api/supabase/api/gateway_dispatch.ts\nexport const supabaseApiGatewayHandlers = [\n  handleColorsApi,\n  handleLanguagesApi,\n] as const\n```\n\nAdd new domains by implementing `handle*Api` and appending to this array.\n\n---\n\n## Environment\n\nSet in repo root `.env` (see [Environment](/en/docs/configuration/environment)):\n\n```env\nSUPABASE_URL=https://your-project.supabase.co\nSUPABASE_KEY=your-anon-key\nSUPABASE_SERVICE_ROLE_KEY=your-service-role-key\nSUPABASE_EDGE_BASE=\n```\n\n- **`SUPABASE_KEY`** - exposed to client via `runtimeConfig.public`\n- **`SUPABASE_SERVICE_ROLE_KEY`** - server only, used by Nitro gateway\n\n---\n\n## Module SQL layout\n\nEach module can ship SQL artifacts:\n\n```txt\nshared_modules/nuc_example/supabase/\n├── api/\n│   ├── handle.ts\n│   └── example_handlers.ts\n├── migrations/       # schema changes (*.sql)\n├── factories/        # factory SQL for dev/test\n└── seeders/          # seed data (*.sql)\n```\n\nExamples in the monorepo:\n\n- `nuc_colors/supabase/migrations/`, `seeders/`, `factories/`\n- `nuc_languages/supabase/migrations/`\n\n---\n\n## Merge & apply scripts\n\nModule SQL is merged into the monorepo Supabase project by bash scripts in `.config/bash/`:\n\n| Script | Command |\n|--------|---------|\n| Merge all module SQL | `pnpm supabase:merge-sql` |\n| Apply migrations (local) | `pnpm supabase:migrations:apply:local` |\n| Apply migrations (linked remote) | `pnpm supabase:migrations:apply:linked` |\n| Apply factories (local) | `pnpm supabase:factories:apply:local` |\n| Apply seeders (local) | `pnpm supabase:seeders:apply:local` |\n| Full local setup | `pnpm supabase:setup:local` |\n| Full linked setup | `pnpm supabase:setup:linked` |\n\nImplementation:\n\n- `.config/bash/merge-module-supabase-sql.sh` - collects module SQL\n- `.config/bash/apply-module-migrations.sh` - runs migrations\n- `.config/bash/apply-module-sql.sh` - runs factories/seeders\n\n---\n\n## Writing API handlers\n\n### Gateway entry (`handle.ts`)\n\n```typescript\nimport { apiNotHandled, apiMethodNotAllowed } from 'nuc_api'\nimport type { ApiContext, ApiHandlerResult } from 'nuc_server'\n\nexport async function handleExampleApi(ctx: ApiContext): Promise<ApiHandlerResult> {\n  if (ctx.segments[0] !== 'example') return apiNotHandled()\n  // dispatch to route table …\n  return apiMethodNotAllowed()\n}\n```\n\nReturn `apiNotHandled()` when the path prefix does not match - the gateway tries the next handler.\n\n### Auth-aware routes\n\nUse helpers from `nuc_api`:\n\n```typescript\nimport { withGatewayUser } from 'nuc_api'\n\nreturn withGatewayUser(ctx, async (gatewayCtx, userId) => {\n  // userId available for RLS-scoped queries\n})\n```\n\n### Client requests\n\nUse `nuc_api` request utilities from the frontend:\n\n```typescript\nimport { apiRequest } from 'modules/nuc_api/utils/api_request'\n```\n\nNever embed the service role key in client code.\n\n---\n\n## Row Level Security\n\nEnable RLS on tables exposed to PostgREST. Add policies for the `authenticated` role. Module migrations should include policies alongside table definitions.\n\nTest policies against both anon and authenticated clients before shipping.\n\n---\n\n## Edge Functions\n\nModule edge functions live under `shared_modules/nuc_*/supabase/functions/`. Example:\n\n```txt\nshared_modules/nuc_colors/supabase/functions/user-colors/index.ts\n```\n\n`SUPABASE_EDGE_BASE` in `.env` points to `{SUPABASE_URL}/functions/v1` by default.\n\n---\n\n## Local development workflow\n\n1. Install Supabase CLI and start local stack (or link a remote project)\n2. Configure root `.env` with project URL and keys\n3. Apply merged SQL:\n\n```bash\npnpm supabase:setup:local\n```\n\n4. Start Nuxt:\n\n```bash\nmake web\n```\n\n5. Verify gateway:\n\n```bash\ncurl http://localhost:3000/api\ncurl http://localhost:3000/api/colors/…   # module-specific routes\n```\n\n---\n\n## Monorepo `supabase/` directory\n\nTop-level `supabase/` holds project config, merged migration output, and shared edge function config - populated by merge scripts from module sources.\n\n---\n\n## Related docs\n\n- [Modules](/en/docs/core-concepts/modules) - module structure and gateway registration\n- [Environment](/en/docs/configuration/environment) - Supabase env vars\n- [Web & Admin](/en/docs/configuration/web) - Nitro gateway entry point\n",
  "en/configuration/web": "# Web & Admin\n\n`web/` and `admin/` are Nuxt 4 applications (canonical source). Configuration is split across `web/.config/nuxt/` (and the equivalent in `admin/`) and composed by a thin `nuxt.config.ts` at each package root.\n\n---\n\n## Config composition\n\n```txt\nweb/\n├── nuxt.config.ts          # imports and spreads split config modules\n└── .config/nuxt/\n    ├── load-env.ts         # loads monorepo root .env before config eval\n    ├── app.ts              # head, meta, base URL\n    ├── structure.ts        # aliases, srcDir, plugins, imports\n    ├── runtime.ts          # runtimeConfig (public + private keys)\n    ├── modules.ts          # Nuxt modules (@nuxtjs/i18n, etc.)\n    ├── locales.ts          # i18n locale list and config\n    ├── nitro.ts            # server preset, handlers\n    ├── vite.ts             # Vite plugins, SCSS, build options\n    ├── route-rules.ts      # SWR, prerender, caching per route\n    ├── performance.ts      # fonts, image optimization\n    ├── dev.ts              # dev-only settings\n    └── hooks.ts            # Nuxt lifecycle hooks\n```\n\n`admin/` follows the same pattern with its own `.config/nuxt/` directory.\n\n---\n\n## Source layout\n\nBoth apps use `srcDir: 'src'` (not a `nuxt/` folder):\n\n```txt\nweb/src/\n├── pages/\n│   ├── [lang]/             # thin i18n route wrappers\n│   └── home/               # landing sections\n├── plugins/\n│   ├── modules.ts          # registerNuc* for shared modules\n│   └── nucleify-ui.client.ts\n├── composables/            # auto-imported\n├── layouts/\n├── assets/styles/          # SCSS entry (imports shared_modules styles)\n├── nucleify.ts             # re-exports shared surface + app helpers\n└── server/\n    └── api/\n        └── [...slug].ts    # Nitro catch-all → gateway_dispatch\n```\n\nUI primitives are Lit custom elements (`nui-*`) from `nucleify-ui` / `portable/nui/`. Landing composition lives under `web/src/pages/` - there is no `ad-*` component tree.\n\n---\n\n## Aliases\n\nDefined in `web/.config/nuxt/structure.ts`:\n\n| Alias | Resolves to |\n|-------|-------------|\n| `nucleify` | `~/nucleify` (app barrel) |\n| `modules` | `../shared_modules` |\n| `portable/nui` | `../portable/nui` |\n| `nuc_client` | `~/nuc_client` |\n| `nuc_server` | `~/server/nuc_server` |\n| `#nuc-compiler/runtime` | `../compiler/runtime/index.ts` |\n\nImport shared modules by package name (e.g. `import { apiRequest } from 'nuc_api'`) - the `modules` alias makes this work.\n\n---\n\n## Module registration\n\nShared modules register as Vue plugins in `web/src/plugins/modules.ts`:\n\n```typescript\nimport { defineNuxtPlugin } from 'nuxt/app'\nimport { registerNucColors } from '../../../shared_modules/nuc_colors/nuc_colors'\nimport { registerNucDarkMode } from '../../../shared_modules/nuc_dark_mode/nuc_dark_mode'\nimport { registerNucGlobals } from '../../../shared_modules/nuc_globals/nuc_globals'\nimport { registerNucLanguages } from '../../../shared_modules/nuc_languages/nuc_languages'\n\nexport default defineNuxtPlugin({\n  name: 'modules-registration',\n  enforce: 'pre',\n  setup(nuxtApp) {\n    registerNucGlobals(nuxtApp.vueApp)\n    registerNucColors(nuxtApp.vueApp)\n    registerNucDarkMode(nuxtApp.vueApp)\n    registerNucLanguages(nuxtApp)\n  },\n})\n```\n\n`registerNucLanguages` receives the full `nuxtApp` because it hooks into Nuxt i18n events.\n\n---\n\n## Runtime config\n\n`web/.config/nuxt/runtime.ts` exposes environment variables to the app:\n\n**Private** (server-only):\n\n- `supabaseServiceRoleKey`\n- `authEmailResendKey`\n- `authEmailFrom`\n- `contactFormRecipient`\n\n**Public** (client + server):\n\n- `appUrl`, `apiUrl`, `supabaseUrl`, `supabaseKey`, `supabaseEdgeBase`, `appEnv`\n\n```typescript\nconst config = useRuntimeConfig()\nconst apiUrl = config.public.apiUrl  // '/api'\n```\n\nSee [Environment](/en/docs/configuration/environment) for the full variable reference.\n\n---\n\n## API gateway\n\nAll server API traffic flows through one Nitro catch-all:\n\n```\nweb/src/server/api/[...slug].ts\n  → dispatchSupabaseApiGateway()\n  → shared_modules/nuc_*/supabase/api/handle.ts\n```\n\nClient code calls `/api/...` - never Supabase directly from the browser for privileged operations.\n\n---\n\n## i18n\n\nLocales are configured in `web/.config/nuxt/locales.ts`. Route wrappers under `src/pages/[lang]/` delegate to feature pages. Default locale redirect sends `/` → `/en/home`.\n\nPrerender locale prefixes are controlled by `PRERENDER_LOCALES` in `.env`.\n\n---\n\n## UI system\n\n- **Lit web components** from `nucleify-ui` (`nui-button`, `nui-icon`, …)\n- **Design tokens** and registration in `portable/nui/`\n- Registered via `nucleify-ui.client.ts` plugin\n- Portable authoring (`*.nuc.tsx`) maps `nui-*` across emit targets\n\n---\n\n## Migrate product shells\n\nGenerated apps live at `web-next/`, `admin-next/`, `web-solid/`, `admin-solid/`, `web-svelte/`, `admin-svelte/` (or a custom `--out` name):\n\n```bash\nmake web TARGET=next      # convert + start Next dev\nmake web TARGET=solid     # convert + start Solid dev\nmake web TARGET=svelte    # convert + start Svelte dev\nmake admin TARGET=next    # admin → next|solid|svelte likewise\nmake admin TARGET=solid\nmake admin TARGET=svelte\n\n# External Nuxt-like tree (from monorepo root):\npnpm compiler -- convert web --target=next --path=/path/to/app --out=my-next --force\npnpm compiler -- convert web --target=solid --path=/path/to/app --out=my-solid --force\npnpm compiler -- convert web --target=svelte --path=/path/to/app --out=my-svelte --force\n```\n\nDevelop in Nuxt (`web/`, `admin/`), convert when you need another framework deployment. Astro `docs/` convert is not available yet. See [Compiler](/en/docs/core-concepts/compiler).\n\n---\n\n## Overrides\n\nPer-deployment customizations go in `overrides/web/` or `overrides/admin/`, mirroring the original file path. See [Overriding](/en/docs/core-concepts/overriding).\n\n---\n\n## Dev commands\n\n| Command | Action |\n|---------|--------|\n| `make web` | Start Nuxt dev server (`web/`) |\n| `make admin` | Start admin Nuxt dev |\n| `pnpm --filter @nucleify/web dev` | Direct pnpm filter |\n| `pnpm --filter @nucleify/admin dev` | Admin direct filter |\n\nDefault port: `3000`. Environment loaded from monorepo root `.env` via `load-env.ts`.\n\n---\n\n## Related docs\n\n- [Environment](/en/docs/configuration/environment) - `.env` variables\n- [Supabase](/en/docs/configuration/supabase) - backend and API handlers\n- [Modules](/en/docs/core-concepts/modules) - shared module structure\n",
  "en/core-concepts/compiler": "# Compiler\n\nFramework migration is a **core capability** of Nucleify - not a bolt-on. The `@nucleify/compiler` package owns that path: an **IR-first** portable compiler that turns `*.nuc.tsx` into Vue SFCs, React, Solid, Svelte, and Astro output (plus shared CSS), **imports emit edits back** into source, and **converts whole Nuxt product shells** (`web/`, `admin/`) - or an external Nuxt-like tree - to Next.js, Solid, Svelte, or Astro.\n\nThat scope goes beyond a component-only transpile: domains, routes, and shared modules move with the shell. The framework becomes a build target; the product stays in `shared_modules/`.\n\n**Coverage:** Vue · React · Nuxt · Next · Astro · Svelte · Solid. React/Next or Vue/Nuxt are starting points, not the limit.\n\n---\n\n## Two operating modes\n\n| Mode | What it does | Example |\n|------|--------------|---------|\n| **Portable emit** | `*.nuc.tsx` → IR → `.vue` + React `.tsx` + Solid `.tsx` + Svelte `.svelte` + `.astro` + `.css` | `pnpm compiler:build` / `make solid` / `make svelte` / `make astro` |\n| **Product convert** | Nuxt app (or external folder/git) → Next.js, Solid, Svelte, or Astro app | `pnpm compiler -- convert web --target=next` |\n\n**Portable emit** is for presentational components with a round-trip import path (`import --from=…`). **Product convert** scaffolds `web-next/`, `admin-next/`, `web-solid/`, `admin-solid/`, `web-svelte/`, `admin-svelte/`, `web-astro/`, or `admin-astro/` from the Vue source tree - same routes, shared modules, different framework shell. Converting the Astro `docs/` product is **not** implemented yet.\n\nDo **not** re-export `*.nuc.tsx` from public barrels (`index.ts`, `modules.ts`, …) - authoring stays out of app entrypoints.\n\n---\n\n## IR version\n\nPortable IR is versioned as `IR_VERSION` (currently **0.1.0**) in `compiler/src/ir/types.ts`.\n\n- Schema, parsers, and `compiler/tests/fixtures/ir/*.json` must stay in sync.\n- **Breaking** IR shape changes → bump the version and migrate fixtures/tests in the **same PR**.\n- Policy: `compiler/PORTABLE.md` § IR versioning.\n\n---\n\n## Portable authoring (`*.nuc.tsx`)\n\nAuthor framework-agnostic UI with `#nuc-compiler/runtime`:\n\n```tsx\nimport { component, state, handler } from '#nuc-compiler/runtime'\n\nexport default component({\n  name: 'Counter',\n  props: { label: { type: 'string', default: 'Count' } },\n  setup(props) {\n    const count = state(0)\n    const onInc = handler(() => count.set(count.value + 1))\n    return () => (\n      <button type=\"button\" onClick={onInc}>\n        {props.label}: {count.value}\n      </button>\n    )\n  },\n})\n```\n\nRunning `pnpm compiler:build` emits siblings next to the source:\n\n```txt\nportable/components/\n├── Counter.nuc.tsx     # source (committed)\n├── Counter.vue         # generated Vue SFC\n├── Counter.tsx         # generated React component\n├── Counter.svelte      # generated Svelte 5 SFC (when siblings enabled)\n└── Counter.css         # extracted styles\n```\n\n### Allowed in portable components\n\n- Serializable props (`string`, `number`, `boolean`, `unknown`)\n- HTML elements and `nui-*` Lit custom elements\n- Local state via `state`, `derived`, `handler`\n- Plain CSS string or `style={{ … }}` object binds\n- Default slot / `children` only\n\n### Forbidden\n\n- Vue/React framework APIs (`defineComponent`, hooks as host coupling)\n- Stores, routers, i18n, Supabase, Pinia/Zustand inside portable files\n- Named slots, portals, dynamic components, async setup\n\nFull rules: `compiler/PORTABLE.md`.\n\n---\n\n## CLI reference\n\n```bash\npnpm compiler:build                              # emit all *.nuc.tsx\npnpm compiler:check                              # verify fingerprints (exit 1 if dirty)\npnpm compiler:test                               # golden-file test suite\n\npnpm compiler -- import --from=vue path/Foo.vue  # import emit edits back to source\npnpm compiler -- import --from=react path/Foo.tsx\npnpm compiler -- build --force                   # discard emit edits; regenerate\n\npnpm compiler -- convert web --target=next       # product convert → web-next/\npnpm compiler -- convert admin --target=next     # product convert → admin-next/\npnpm compiler -- convert web --target=solid      # product convert → web-solid/\npnpm compiler -- convert web --target=svelte     # product convert → web-svelte/\npnpm compiler -- convert web --target=astro      # product convert → web-astro/\npnpm compiler -- convert web --target=next --path=/path/to/nuxt-app --out=my-next --force\npnpm compiler -- convert web --target=svelte --git=https://github.com/org/app.git --out=fork-svelte --force\npnpm compiler -- scaffold solid                  # temporary demo → solid/demo/\npnpm compiler -- scaffold svelte                 # temporary demo → svelte/demo/\npnpm compiler -- scaffold next                   # temporary demo → next/demo/\npnpm compiler -- build --app=solid               # emit into solid/demo\npnpm compiler -- build --app=svelte              # emit into svelte/demo\n```\n\nSkip compiler during bootstrap / skip hooks when needed:\n\n```bash\nSKIP_COMPILER=1 make run\nHUSKY=0 git commit -m \"…\"   # skip pre-commit suite\n```\n\nPre-commit already runs `compiler:check` (and related compiler checks) via Husky.\n\n---\n\n## Authoring-first cycle\n\n1. Create or edit `Foo.nuc.tsx`\n2. Run `pnpm compiler:build`\n3. Commit source + generated siblings\n4. CI runs `pnpm compiler:check` to ensure emit is up to date\n\n## Emit-first cycle\n\n1. Tweak generated `Foo.vue`, `Foo.tsx`, or `Foo.svelte` directly\n2. Import changes back: `pnpm compiler -- import --from=vue|react|solid|svelte path/Foo.…`\n3. Source of truth returns to `Foo.nuc.tsx`\n\nIf more than one emit sibling is dirty, you must pass `--from=`. Use `pnpm compiler -- build --force` to discard emit edits.\n\n---\n\n## Package layout\n\n```txt\ncompiler/\n├── src/\n│   ├── parse/              # *.nuc.tsx → AST\n│   ├── ir/                 # intermediate representation (IR_VERSION)\n│   ├── emit/               # IR → .vue / React .tsx / Solid .tsx / Svelte .svelte / .css\n│   └── sync/               # import back, convert product shells\n├── runtime/                # #nuc-compiler/runtime\n├── templates/              # scaffold sources for gitignored demos\n├── tests/                  # golden-file tests\n├── fixtures/\n└── PORTABLE.md             # authoring rules\n```\n\nGitignored emit demos: `{vue,react,nuxt,next,solid,svelte}/demo/` (via `make vue`, `make next`, `make solid`, `make svelte`, etc.).\n\n---\n\n## Product convert\n\n```bash\nmake web TARGET=next\n# equivalent:\npnpm compiler -- convert web --target=next\ncd web-next && pnpm dev\n\nmake web TARGET=solid\npnpm compiler -- convert web --target=solid\n\nmake web TARGET=svelte\npnpm compiler -- convert web --target=svelte\n\nmake web TARGET=astro\npnpm compiler -- convert web --target=astro\n```\n\nSvelte product apps are Vite SPAs with Svelte 5 runes (not SvelteKit SSR yet). Portable Svelte emit uses `$state` / `$derived` / `$props` and DOM events like `onclick`. Astro product convert hosts the same React islands under Astro pages (`client:load`).\n\nConverted hosts load **Instrument Sans** and **JetBrains Mono** with `<link>` tags in the document head (`portable/nui/fonts.ts`). Do not load those families via CSS `@import` inside a bundled stylesheet - bundlers concatenate CSS and mid-file `@import` is ignored, so typography falls back to system mono.\n\n### External folder or git URL\n\nUse the same `web|admin` convert profile with an external Nuxt-like tree (`src/` required). Run from the **Nucleify monorepo root** so `modules` / `portable` aliases resolve:\n\n```bash\npnpm compiler -- convert web --target=next --path=/path/to/nuxt-app --out=my-next --force\npnpm compiler -- convert admin --target=solid --git=https://github.com/org/app.git --out=fork-admin-solid --force\npnpm compiler -- convert web --target=svelte --path=/path/to/nuxt-app --out=my-svelte --force\n```\n\nConverted apps install with `pnpm install --ignore-workspace` - template dependency versions stay pinned; they do not join the monorepo workspace graph.\n\nThe converter reads Vue SFCs under `src/`, maps pages and composables to React, Solid, Svelte, or Astro hosts, and writes output with **no** source `.vue` files. Shared modules are consumed via framework barrels.\n\nTreat `web-next/`, `admin-next/`, `web-solid/`, `admin-solid/`, `web-svelte/`, `admin-svelte/`, `web-astro/`, and `admin-astro/` (and custom `--out` dirs) as **generated output**. Edit `web/` or `admin/`, then reconvert - do not hand-patch the emit tree.\n\n---\n\n## Runtime alias\n\nNuxt resolves the runtime through `web/.config/nuxt/structure.ts`:\n\n```typescript\n'#nuc-compiler/runtime': resolve(process.cwd(), '../compiler/runtime/index.ts')\n```\n\nRuntime helpers (`component`, `state`, `derived`, `handler`) are compile-time markers - they must not appear in emitted bundles.\n\n---\n\n## Testing\n\nCompiler tests live in `compiler/tests/` with a dedicated Vitest config (`.config/vitest.compiler.config.ts`). Golden tests compare emit output against fixtures in `compiler/tests/fixtures/`. Guards include IR version sync and barrel scans (no `*.nuc.tsx` in public entrypoints).\n\n```bash\npnpm compiler:test\npnpm compiler:check\n```\n\nProduct smoke (manual): `make web`, `make vue` / `make solid` / `make svelte` for emit demos.\n\nSee [Vitest](/en/docs/tests/vitest) for the full testing setup.\n\n---\n\n## Related docs\n\n- [Monorepo Layout](/en/docs/core-concepts/monorepo) - where compiler fits in the workspace\n- [Quick Start](/en/docs/getting-started/quick-start) - build your first portable component\n- [Web & Admin](/en/docs/configuration/web) - Nuxt config that wires the runtime alias\n",
  "en/core-concepts/feature-sliced-design": "# Feature-Sliced Design\n\nFeature-Sliced Design (FSD) organizes code **by business domain** instead of by technical layer. In Nucleify, each `shared_modules/nuc_*` package is one slice - frontend utilities, API handlers, database migrations, types, and tests co-located in a single directory.\n\n---\n\n## Why feature slices?\n\nLayer-first projects scatter one feature across many folders:\n\n```txt\n# ❌ Layer-first                         # ✅ Feature-sliced (Nucleify)\n\nsrc/                                    shared_modules/\n├── api/                                ├── nuc_api/\n│   ├── colors.ts                       │   ├── supabase/api/gateway_dispatch.ts\n│   └── languages.ts                    │   ├── utils/api_request.ts\n├── types/                              │   └── vitests/\n│   ├── colors.ts                       ├── nuc_colors/\n│   └── languages.ts                    │   ├── supabase/api/handle.ts\n├── styles/                             │   ├── styles/\n│   └── colors.scss                     │   └── vitests/\n└── tests/                              └── nuc_languages/\n    └── colors.test.ts                      └── …\n```\n\nProblems with layers at monorepo scale:\n\n- Adding a feature touches 5+ directories\n- Removing a feature means hunting files across the tree\n- Parallel work on different features causes merge conflicts\n- Ownership is unclear\n\nFSD fixes this by making **the module the unit of change**.\n\n---\n\n## How Nucleify applies FSD\n\n### Shared modules = domain slices\n\nThe six exported modules map to cross-cutting product domains:\n\n| Module | Slice |\n|--------|-------|\n| `nuc_api` | HTTP client, gateway, auth forms, entity state |\n| `nuc_colors` | Theming, SCSS tokens, color API |\n| `nuc_dark_mode` | Appearance preference |\n| `nuc_globals` | Breakpoints, shared types, global SCSS |\n| `nuc_languages` | Locales, translation fetch, i18n plugin |\n| `nuc_stores` | Client persistence abstractions |\n\nEach slice is imported by `web/` and `admin/` without duplication.\n\n### Apps = composition layers\n\nProduct apps are thin composition shells:\n\n```txt\nweb/src/\n├── pages/[lang]/           # routing + i18n wrappers\n├── pages/home/             # landing composition (sections)\n├── composables/            # app-specific only\n├── plugins/                # wire modules into Nuxt\n└── server/api/             # single gateway entry\n```\n\n**Rule:** if logic belongs to a domain, it lives in `shared_modules/nuc_*`. If it belongs to one app shell (routing, layout, marketing copy structure), it stays in `web/` or `admin/`.\n\n---\n\n## Module internal layers\n\nWithin a module, folders follow a lightweight FSD-inspired layout:\n\n| Folder | FSD analogue | Contents |\n|--------|--------------|----------|\n| `supabase/api/` | Backend / API | Gateway handlers, route tables |\n| `utils/` | Shared lib | Composables, hooks, pure functions |\n| `types/` | Shared types | Interfaces, type literals |\n| `constants/` | Shared config | Static values, field defs |\n| `components/` | UI (optional) | Reusable widgets for the domain |\n| `styles/` | UI tokens | SCSS partials |\n| `vitests/` | Tests | Unit tests co-located with domain |\n\nThere is no strict `entities/features/widgets` folder naming - Nucleify favors **flat domain modules** over deep FSD ceremony. The principle (co-location by feature) matters more than the folder labels.\n\n---\n\n## Cross-slice communication\n\nModules communicate through **defined public exports**, not deep imports into another module's internals:\n\n```typescript\n// ✅ Public barrel\nimport { apiRequest } from 'modules/nuc_api/utils/api_request'\n\n// ❌ Reach into another module's private handler\nimport { internalHelper } from 'modules/nuc_colors/supabase/api/colors_helpers'\n```\n\nGateway dispatch in `nuc_api` is the orchestration point for HTTP - individual modules register handlers, but routing between domains happens at the gateway, not via cross-imports in `utils/`.\n\n---\n\n## Portable UI vs domain logic\n\nThe compiler adds a second axis:\n\n| Layer | Location | Framework coupling |\n|-------|----------|-------------------|\n| Portable UI | `*.nuc.tsx` | None - emits Vue + React + Solid + Svelte |\n| Domain logic | `shared_modules/nuc_*/utils/` | Vue composables + `.react.ts` hooks |\n| App shell | `web/src/pages/` | Nuxt (canonical) or Next / Solid / Svelte (converted) |\n\nKeep stores, routers, i18n containers, and API calls **out of** `*.nuc.tsx`. Portable components receive data via props and emit events - domain slices own the wiring in app or module utils.\n\n---\n\n## Comparison with Atomic Design\n\nNucleify uses **Atomic Design** inside SCSS (`atoms/`, `molecules/`, `organisms/` under `nuc_colors/styles/components/`) for visual hierarchy. FSD and Atomic Design solve different problems:\n\n- **FSD** - where feature code lives in the repo\n- **Atomic Design** - how UI components nest visually\n\nThey coexist: a `nuc_colors` organism partial is still part of the `nuc_colors` slice.\n\n---\n\n## Adding a feature the FSD way\n\n1. **Identify the domain** - new slice or extend an existing `nuc_*`?\n2. **Co-locate** - API handler, types, utils, migrations, tests in one module folder\n3. **Export publicly** - `index.ts` / `index.react.ts`\n4. **Wire the app** - plugin registration, gateway handler, page composition\n5. **Avoid app-local copies** - if two apps need it, it belongs in `shared_modules/`\n\n---\n\n## Related docs\n\n- [Modules](/en/docs/core-concepts/modules) - module reference\n- [Monorepo Layout](/en/docs/core-concepts/monorepo) - app vs shared boundaries\n- [Compiler](/en/docs/core-concepts/compiler) - portable UI layer\n",
  "en/core-concepts/modules": "# Modules\n\nNucleify ships **six exported** feature modules from `@nucleify/shared-modules`. Each is a self-contained domain package with frontend utilities, optional Supabase API handlers, migrations, types, and tests - consumed by `web/`, `admin/`, `docs/`, and generated shells (Next, Solid, Svelte, …) so you can migrate frameworks without rewriting the business.\n\nThere is no root-level `modules/` folder. Apps import via relative paths or the Nuxt alias `modules` → `shared_modules/`. Auth flows live inside `nuc_api` (there is no separate `nuc_users` / `nuc_auth` package).\n\n---\n\n## The modules\n\n| Module | Domain | Key paths |\n|--------|--------|-----------|\n| `nuc_api` | API client, gateway dispatch, auth forms, entity requests, toasts | `supabase/api/gateway_dispatch.ts`, `utils/api_request.ts` |\n| `nuc_colors` | Theme/color system, SCSS variables, color utilities | `styles/`, `supabase/api/handle.ts` |\n| `nuc_dark_mode` | Dark mode preference (load, persist, apply) | `utils/use_dark_mode.ts`, `nuc_dark_mode.ts` |\n| `nuc_globals` | Media queries, image helpers, global styles, shared types | `media/`, `styles/`, `nuc_globals.ts` |\n| `nuc_languages` | i18n, locale messages, translations API | `plugins/nuc_translations.ts`, `supabase/api/handle.ts` |\n| `nuc_stores` | Pinia/Zustand helpers, cookie/localStorage/session utils | `pinia/`, `zustand/`, `cookie/` |\n\nThese six are listed in `shared_modules/index.ts` and `package.json` `exports`. Other folders under `shared_modules/` without a public barrel are not part of the supported API yet.\n\n---\n\n## Module anatomy\n\nEvery `nuc_*` directory follows a consistent layout:\n\n```txt\nshared_modules/nuc_example/\n├── config.json              # name, version, category, enabled\n├── nuc_example.ts           # Vue plugin (registerNucExample)\n├── index.ts                 # Vue barrel export\n├── index.react.ts           # React barrel export (when needed)\n├── _index.scss              # optional global module styles\n├── README.md\n├── constants/\n├── types/\n│   ├── interfaces.ts\n│   ├── interfaces.react.ts  # when React types diverge\n│   └── variables.ts\n├── utils/                   # composables, hooks, pure functions\n├── components/              # optional reusable UI\n├── supabase/\n│   ├── api/\n│   │   ├── handle.ts        # gateway entry (handleExampleApi)\n│   │   └── *_handlers.ts    # route tables\n│   ├── migrations/\n│   ├── factories/\n│   └── seeders/\n└── vitests/\n```\n\n---\n\n## Registration in Nuxt\n\n`web/src/plugins/modules.ts` registers four modules at app startup:\n\n```typescript\nimport { registerNucColors } from '../../../shared_modules/nuc_colors/nuc_colors'\nimport { registerNucDarkMode } from '../../../shared_modules/nuc_dark_mode/nuc_dark_mode'\nimport { registerNucGlobals } from '../../../shared_modules/nuc_globals/nuc_globals'\nimport { registerNucLanguages } from '../../../shared_modules/nuc_languages/nuc_languages'\n\nexport default defineNuxtPlugin({\n  name: 'modules-registration',\n  enforce: 'pre',\n  setup(nuxtApp) {\n    registerNucGlobals(nuxtApp.vueApp)\n    registerNucColors(nuxtApp.vueApp)\n    registerNucDarkMode(nuxtApp.vueApp)\n    registerNucLanguages(nuxtApp)\n  },\n})\n```\n\n`nuc_api` and `nuc_stores` are imported on demand - no global plugin.\n\nTranslations also load via a Nuxt plugin path in config:\n\n```typescript\n// web/.config/nuxt/structure.ts\nplugins: [\n  resolve(process.cwd(), '../shared_modules/nuc_languages/plugins/nuc_translations.ts'),\n],\n```\n\n---\n\n## Import rules\n\n**Inside a module** - relative imports only. Never import from `web/`, `admin/`, or `docs/`.\n\n**From an app** - use the alias or relative path:\n\n```typescript\n// via alias (Nuxt)\nimport { useDarkMode } from 'modules/nuc_dark_mode/utils/use_dark_mode'\n\n// explicit relative (also valid)\nimport { apiRequest } from '../../../shared_modules/nuc_api/utils/api_request'\n```\n\n**Public surface** - export through `index.ts` and the root barrel `shared_modules/index.ts`. Do not import `from 'nucleify'` inside modules (circular dependency).\n\n---\n\n## API gateway integration\n\nModule handlers export an async `handle*Api(ctx)` function. Register it in the gateway registry:\n\n```typescript\n// shared_modules/nuc_api/supabase/api/gateway_dispatch.ts\nexport const supabaseApiGatewayHandlers = [\n  handleColorsApi,\n  handleLanguagesApi,\n] as const\n```\n\nNitro entry point:\n\n```txt\nweb/src/server/api/[...slug].ts\n  → parseApiSlug()\n  → dispatchSupabaseApiGateway(ctx)\n  → first handler where result.handled === true\n```\n\n### Handler pattern\n\n```typescript\nimport { apiMethodNotAllowed, apiNotHandled, withGatewayUser } from 'nuc_api'\nimport type { ApiContext, ApiHandlerResult } from 'nuc_server'\n\nexport async function handleExampleApi(ctx: ApiContext): Promise<ApiHandlerResult> {\n  if (ctx.segments[0] !== 'example') return apiNotHandled()\n  return withGatewayUser(ctx, async (gatewayCtx, userId) => {\n    // route table dispatch …\n    return apiMethodNotAllowed()\n  })\n}\n```\n\nClient code calls `/api/example/...` through `nuc_api` request helpers - not Supabase service keys in the browser.\n\n---\n\n## Supabase per module\n\nEach module can own SQL artifacts:\n\n| Directory | Purpose |\n|-----------|---------|\n| `supabase/migrations/` | Schema changes |\n| `supabase/factories/` | Test/dev factory SQL |\n| `supabase/seeders/` | Seed data |\n\nApply locally:\n\n```bash\npnpm supabase:migrations:apply:local\npnpm supabase:seeders:apply:local\n# or combined:\npnpm supabase:setup:local\n```\n\nScripts merge all module SQL via `.config/bash/merge-module-supabase-sql.sh`.\n\n---\n\n## React variants\n\nModules that support product convert expose `.react.ts` siblings:\n\n- `index.react.ts` - React barrel\n- `utils/use_*.react.ts` - React hooks mirroring Vue composables\n- `types/interfaces.react.ts` - React-specific types when needed\n\nThe compiler and product convert use these when emitting Next, Solid, and Svelte product shells.\n\n---\n\n## Creating a new module\n\n1. Copy the structure from an existing `nuc_*` module\n2. Add `config.json` metadata\n3. Implement `nuc_example.ts` with `registerNucExample`\n4. Export public API from `index.ts`\n5. Add to `shared_modules/index.ts` if needed globally\n6. Register plugin in `web/src/plugins/modules.ts` if it needs app-wide setup\n7. Add gateway handler to `gateway_dispatch.ts` if it exposes API routes\n8. Add `vitests/` and run `pnpm test:shared`\n\nSee [Feature-Sliced Design](/en/docs/core-concepts/feature-sliced-design) for architectural rationale.\n\n---\n\n## Related docs\n\n- [Feature-Sliced Design](/en/docs/core-concepts/feature-sliced-design)\n- [Supabase](/en/docs/configuration/supabase)\n- [Overriding](/en/docs/core-concepts/overriding) - patch module files without editing upstream\n",
  "en/core-concepts/monorepo": "# Monorepo Layout\n\nNucleify is a pnpm workspace built for **migration across frameworks** as a first-class product capability. Every package has a clear boundary, shared tooling lives in `.config/`, and product apps (`web/`, `admin/`, `docs/`) consume feature logic from `shared_modules/` - never the other way around. The compiler owns emit, import, and product convert; generated shells (Next, Solid, Svelte, Astro, …) are output, not a second source of truth.\n\n---\n\n## Top-level map\n\n```txt\nnucleify/\n├── web/                    # @nucleify/web - Nuxt 4 landing (canonical)\n├── admin/                  # @nucleify/admin - Nuxt 4 admin panel\n├── docs/                   # @nucleify/docs - Astro 5 documentation\n├── compiler/               # @nucleify/compiler - IR portable UI compiler\n├── shared_modules/         # @nucleify/shared-modules - six exported nuc_* modules\n├── portable/nui/           # design tokens, Lit nui-* registration\n├── overrides/              # overrides/{web,admin,docs,shared_modules}/\n├── supabase/               # DB config, migrations, edge functions\n├── .config/                # Biome, Vitest, bash scripts, CI helpers\n├── .cursor/                # Cursor agents and monorepo rules\n├── Makefile                # make run, make web, make admin, …\n└── package.json            # workspace root scripts\n```\n\n---\n\n## Product apps\n\n### `web/` - `@nucleify/web`\n\nThe canonical Nuxt 4 landing application.\n\n```txt\nweb/\n├── nuxt.config.ts          # composes split config from .config/nuxt/\n├── .config/\n│   ├── .env.example        # template copied to repo root .env by make run\n│   └── nuxt/               # app, dev, i18n, nitro, runtime, structure, vite, …\n└── src/\n    ├── pages/\n    │   ├── [lang]/         # thin route wrappers (i18n)\n    │   └── home/           # landing sections\n    ├── plugins/\n    │   ├── modules.ts      # registerNuc* for shared modules\n    │   └── nucleify-ui.client.ts\n    ├── composables/\n    ├── layouts/\n    ├── assets/             # SCSS entry (imports shared_modules styles)\n    ├── nucleify.ts         # re-exports shared surface + app helpers\n    └── server/\n        └── api/\n            └── [...slug].ts  # Nitro catch-all → gateway_dispatch\n```\n\nKey facts:\n\n- `srcDir` is `src` (not `nuxt/`)\n- Alias `modules` → `../shared_modules`\n- Alias `#nuc-compiler/runtime` → `../compiler/runtime/index.ts`\n\n### `admin/` - `@nucleify/admin`\n\nSame Nuxt conventions as `web/`, focused on dashboard pages under `admin/src/pages/`.\n\n---\n\n## `docs/` - `@nucleify/docs`\n\nAstro 5 static documentation site.\n\n```txt\ndocs/\n├── content/\n│   ├── en/{category}/{slug}.md\n│   └── pl/{category}/{slug}.md\n├── public/                 # favicon, logo\n└── src/\n    ├── pages/\n    │   └── [lang]/docs/[category]/[slug].astro\n    ├── layouts/DocsLayout.astro\n    ├── components/         # DocsSidebar, DocsToc, LangSwitcher\n    └── lib/                # doc paths, markdown renderer, nav\n```\n\nCategories are defined in `docs/src/lib/constants/docs.ts`. Production host: [docs.nucleify.io](https://docs.nucleify.io). Routes follow `/en/docs/{category}/{slug}`.\n\n---\n\n## `compiler/` - `@nucleify/compiler`\n\nIR-first portable UI compiler. Self-contained - does not import from `web/`, `admin/`, or `docs/`.\n\n```txt\ncompiler/\n├── src/\n│   ├── parse/              # *.nuc.tsx → AST\n│   ├── ir/                 # intermediate representation\n│   ├── emit/               # IR → .vue / React .tsx / Solid .tsx / Svelte .svelte / .css\n│   └── sync/               # import back from emit, convert product shells\n├── runtime/                # #nuc-compiler/runtime (component, state, handler, …)\n├── templates/              # scaffold sources for gitignored demos\n├── tests/\n├── fixtures/\n└── PORTABLE.md             # authoring rules for *.nuc.tsx\n```\n\nGitignored emit demos: `{vue,react,nuxt,next,solid,svelte}/demo/` (via `make vue`, `make next`, `make solid`, `make svelte`, etc.).\n\n---\n\n## `shared_modules/` - `@nucleify/shared-modules`\n\nSix exported feature modules (not git submodules):\n\n| Module | Path |\n|--------|------|\n| API client & gateway | `shared_modules/nuc_api/` |\n| Colors & theme | `shared_modules/nuc_colors/` |\n| Dark mode | `shared_modules/nuc_dark_mode/` |\n| Globals & media | `shared_modules/nuc_globals/` |\n| i18n & translations | `shared_modules/nuc_languages/` |\n| Storage & state helpers | `shared_modules/nuc_stores/` |\n\nBarrel export: `shared_modules/index.ts` + package `exports`. Each module is self-contained with optional `supabase/`, `utils/`, `types/`, and `vitests/`. Auth lives in `nuc_api`.\n\n---\n\n## `portable/nui/`\n\nDesign tokens and Lit custom element registration for `nucleify-ui` (`nui-*` tags). Referenced by Nuxt via alias `portable/nui` in `web/.config/nuxt/structure.ts`.\n\n---\n\n## `overrides/`\n\nPer-package override layers. Mirror any file path:\n\n```txt\noverrides/\n├── web/src/…\n├── admin/src/…\n├── docs/src/…\n└── shared_modules/nuc_*/…\n```\n\nOverrides replace the original file entirely - no merge. Nuxt-only; not part of compiler import. See [Overriding](/en/docs/core-concepts/overriding).\n\n---\n\n## `supabase/`\n\nMonorepo-level Supabase project config. Module SQL lives inside each `shared_modules/nuc_*/supabase/` and is merged by `.config/bash/merge-module-supabase-sql.sh`.\n\n---\n\n## `.config/`\n\nShared monorepo tooling:\n\n- Biome (`pnpm check`, `pnpm write`)\n- Vitest root config (`vitest.config.ts`) - `web` and `shared` projects\n- Compiler Vitest (`.config/vitest.compiler.config.ts`)\n- Bash scripts: Supabase merge/apply, hook checks, submodule prepare\n- Husky hooks delegate to `.config/bash/hook-checks.sh`\n\n---\n\n## Dependency direction\n\n```txt\nweb / admin / docs\n         ↓ imports\n    shared_modules / portable / compiler/runtime\n         ↓\n    supabase (via API handlers)\n```\n\n**Rules:**\n\n- Apps import from `shared_modules/`; modules never import from apps\n- Compiler logic stays inside `compiler/src/`\n- Overrides shadow app or module files at build time (Nuxt only)\n\n---\n\n## Makefile reference\n\n| Command | Action |\n|---------|--------|\n| `make run` | `.env` + setup + compiler |\n| `make setup` | install, husky, prepare, sync-rules, compiler |\n| `make web` | Nuxt product dev (`TARGET=nuxt` default) |\n| `make web TARGET=next` | convert + Next product app (`web-next/`) |\n| `make web TARGET=solid` | convert + Solid product app (`web-solid/`) |\n| `make web TARGET=svelte` | convert + Svelte product app (`web-svelte/`) |\n| `make web TARGET=astro` | convert + Astro host + React islands (`web-astro/`) |\n| `make admin` / `make admin TARGET=next\\|solid\\|svelte\\|astro` | admin equivalents |\n| `make docs` | Astro docs site (`docs/`) |\n| `make compiler` | check + build |\n| `make vue` / `make react` / `make nuxt` / `make next` / `make solid` / `make svelte` / `make astro` | gitignored portable demos (`{framework}/demo`) |\n\n---\n\n## Related docs\n\n- [Modules](/en/docs/core-concepts/modules) - module internal structure\n- [Compiler](/en/docs/core-concepts/compiler) - canonical Nuxt vs converted product apps\n- [Web & Admin](/en/docs/configuration/web) - Nuxt config details\n",
  "en/core-concepts/overriding": "# Overriding\n\nOverrides let you replace any file in `web/`, `admin/`, `docs/`, or `shared_modules/` without editing the original. At build time, Nuxt resolves the override path instead of the source path.\n\nOverrides are **Nuxt-only**. They do not apply to the compiler import cycle, Astro in production builds outside Nuxt, or generated shells (`web-next/`, `web-solid/`, `web-svelte/`, …) unless separately configured.\n\n---\n\n## How it works\n\n1. Mirror the original file path under `overrides/{package}/`\n2. Nuxt dev/build scans `overrides/` at startup\n3. When a match exists, the override **fully replaces** the original - no merge, no partial patch\n\n```txt\nOriginal:  web/src/composables/useAuth.ts\nOverride:  overrides/web/src/composables/useAuth.ts\n```\n\n---\n\n## Directory layout\n\n```txt\noverrides/\n├── web/\n│   └── src/…               # mirrors web/src/…\n├── admin/\n│   └── src/…\n├── docs/\n│   └── src/…\n└── shared_modules/\n    └── nuc_colors/…\n```\n\nEach subdirectory has a `README.md` with examples for that package.\n\n---\n\n## Examples\n\n### Override a landing page section\n\n```txt\nOriginal:  web/src/pages/home/index.vue\nOverride:  overrides/web/src/pages/home/index.vue\n```\n\nUse when you fork branding or layout for a white-label deployment while keeping the upstream `web/` tree intact.\n\n### Override a composable\n\n```txt\nOriginal:  web/src/composables/useAuth.ts\nOverride:  overrides/web/src/composables/useAuth.ts\n```\n\nUse when auth flow differs per deployment but the rest of the app stays the same.\n\n### Override a module API handler\n\n```txt\nOriginal:  shared_modules/nuc_colors/supabase/api/handle.ts\nOverride:  overrides/shared_modules/nuc_colors/supabase/api/handle.ts\n```\n\nUse when backend behavior must diverge without forking the entire `nuc_colors` module.\n\n### Override docs layout\n\n```txt\nOriginal:  docs/src/layouts/DocsLayout.astro\nOverride:  overrides/docs/src/layouts/DocsLayout.astro\n```\n\nNote: Astro override resolution depends on your docs build setup - verify in dev after adding the file.\n\n---\n\n## Debugging overrides\n\nWhen behavior differs from what you expect in source:\n\n1. Check `overrides/{package}/` for a path matching the file you are reading\n2. Temporarily rename or remove the override to confirm it is the active version\n3. Remember: overrides shadow **entire files** - a one-line change still requires copying the full file\n\n---\n\n## What overrides are not\n\n| Concern | Override? | Alternative |\n|---------|-----------|-------------|\n| Portable component emit | No | Edit `*.nuc.tsx`, run `pnpm compiler:build` |\n| Import emit back to authoring | No | `pnpm compiler -- import --from=vue\\|react\\|solid\\|svelte` |\n| Generated product shell (Next / Solid / Svelte) | No* | Edit `web/`, convert with `make web TARGET=next\\|solid\\|svelte` |\n| Environment-specific config | No | Root `.env`, `web/.config/nuxt/runtime.ts` |\n| Database schema | No | Module migrations in `shared_modules/nuc_*/supabase/` |\n\n\\*Unless you add separate override tooling for converted shells - not part of the default Nuxt override scanner.\n\n---\n\n## Best practices\n\n1. **Keep overrides small in count** - many overrides make upgrades hard\n2. **Document why** - add a comment at the top of override files explaining the fork reason\n3. **Prefer modules** - if multiple apps need the change, extend `shared_modules/` instead\n4. **Sync upstream** - when merging upstream Nucleify changes, diff override files against originals\n5. **Do not commit secrets** - overrides are source files; use `.env` for keys\n\n---\n\n## Related docs\n\n- [Monorepo Layout](/en/docs/core-concepts/monorepo) - `overrides/` in context\n- [Modules](/en/docs/core-concepts/modules) - when to extend a module vs override\n- [Compiler](/en/docs/core-concepts/compiler) - overrides excluded from import cycle\n",
  "en/getting-started/installation": "# Installation\n\nGet the Nucleify monorepo running on your machine.\n\n---\n\n## Prerequisites\n\n| Tool | Version | Notes |\n|------|---------|-------|\n| **Node.js** | ≥ 20 | Required by root `package.json` |\n| **pnpm** | 10.x | Workspace manager (`packageManager: pnpm@10.33.0`) |\n| **Git** | any recent | Clone the repository |\n| **Make** | any | Runs workspace shortcuts from the root `Makefile` |\n| **Supabase CLI** | optional | Only if you run a local Supabase stack |\n\n---\n\n## Clone the repository\n\n```bash\ngit clone https://github.com/Nucleify/Nucleify.git\ncd Nucleify\n```\n\n---\n\n## First-time setup\n\nFrom the repo root, run:\n\n```bash\nmake run\n```\n\nThis command:\n\n1. **Creates `.env`** - copies `web/.config/.env.example` to the repo root if `.env` is missing\n2. **Installs dependencies** - `pnpm install` across all workspace packages\n3. **Prepares Husky** - git hooks for lint and test checks\n4. **Prepares web** - `pnpm --filter @nucleify/web prepare`\n5. **Syncs Cursor rules** - `pnpm sync-rules`\n6. **Builds the compiler** - `pnpm compiler:check` + `pnpm compiler:build` (emits Vue / React / Solid / Svelte siblings; skip with `SKIP_COMPILER=1 make run`)\n\nIf you already have a `.env` file, use `make setup` instead - same steps without overwriting environment config.\n\n---\n\n## Environment variables\n\nAfter `make run`, edit the root `.env` and fill in at minimum:\n\n```env\nSUPABASE_URL=https://your-project.supabase.co\nSUPABASE_KEY=your-anon-key\nSUPABASE_SERVICE_ROLE_KEY=your-service-role-key\n```\n\nThe API gateway in `web/src/server/api/[...slug].ts` requires `SUPABASE_URL` and `SUPABASE_SERVICE_ROLE_KEY` for module routes. Without them, smoke endpoints (`/api`, `/api/test`) still work, but domain handlers return 503.\n\nSee [Environment](/en/docs/configuration/environment) for the full variable reference.\n\n---\n\n## Verify the installation\n\nStart the landing app:\n\n```bash\nmake web\n```\n\nOpen [http://localhost:3000](http://localhost:3000). The default locale redirect sends you to `/en/home`.\n\nOther packages:\n\n```bash\nmake admin    # admin panel (Nuxt)\nmake docs     # documentation site (Astro)\nmake compiler # compiler check + build only\n```\n\n---\n\n## Workspace packages\n\nThe monorepo uses pnpm workspaces. Filter commands when you need a specific package:\n\n```bash\npnpm --filter @nucleify/web dev\npnpm --filter @nucleify/admin dev\npnpm --filter @nucleify/docs dev\n```\n\nRoot shortcuts mirror the Makefile:\n\n| Script | Package |\n|--------|---------|\n| `pnpm dev` | `@nucleify/web` |\n| `pnpm admin` | `@nucleify/admin` |\n| `pnpm docs` | `@nucleify/docs` |\n| `pnpm compiler` | `@nucleify/compiler` CLI |\n\n---\n\n## Optional: local Supabase\n\nIf you develop against a local Supabase instance:\n\n```bash\n# Apply merged module migrations, factories, and seeders\npnpm supabase:setup:local\n```\n\nSQL from all modules is merged by `.config/bash/merge-module-supabase-sql.sh`. Details: [Supabase](/en/docs/configuration/supabase).\n\n---\n\n## Troubleshooting\n\n### Compiler fails on setup\n\nSkip compiler codegen during bootstrap:\n\n```bash\nSKIP_COMPILER=1 make run\nmake compiler   # run manually once deps are stable\n```\n\n### Port already in use\n\nNuxt defaults to port 3000. Set a different port in your shell or stop the conflicting process.\n\n### Missing Supabase errors in API routes\n\nEnsure `.env` is at the **repo root** (not inside `web/`). Nuxt loads it via `web/.config/nuxt/load-env.ts`, which reads the monorepo root `.env`.\n\n### pnpm version mismatch\n\nInstall the version pinned in `package.json`:\n\n```bash\ncorepack enable\ncorepack prepare pnpm@10.33.0 --activate\n```\n\n---\n\n## Next steps\n\n- [Quick Start](/en/docs/getting-started/quick-start) - tour the repo and common workflows\n- [Web & Admin Configuration](/en/docs/configuration/web) - Nuxt config split and aliases\n- [Monorepo Layout](/en/docs/core-concepts/monorepo) - directory reference\n",
  "en/getting-started/introduction": "# Introduction\n\n## Build once. Move to any framework.\n\n**Nucleify** is a modular full-stack monorepo built around **framework migration**. Keep your product in shared modules, develop day-to-day in Nuxt (`web/`), and move web or admin to another shell when hiring, buyers, or clients demand it - without rewriting the business. The IR-first compiler is how that move happens: portable emit, product convert, and import back from emit.\n\n**Shells:** Vue · React · Nuxt · Next · Astro · Svelte · Solid - not a React/Next-only or Vue/Nuxt-only product.\n\n> Keep the product. Migrate the shell.\n\n---\n\n## What is Nucleify?\n\nNucleify is a **pnpm workspace** that bundles everything for a modern product:\n\n| Package | Path | Role |\n|---------|------|------|\n| `@nucleify/web` | `web/` | Nuxt 4 landing app (canonical) |\n| `@nucleify/admin` | `admin/` | Nuxt 4 admin panel |\n| `@nucleify/docs` | `docs/` | Astro 5 documentation site |\n| `@nucleify/compiler` | `compiler/` | IR portable UI compiler |\n| `@nucleify/shared-modules` | `shared_modules/` | Six exported feature modules |\n\nSupporting directories:\n\n- `portable/nui/` - design tokens and Lit `nui-*` registration\n- `overrides/` - per-package file overrides (`overrides/{web,admin,docs,shared_modules}/`)\n- `supabase/` - DB config, migrations, edge functions\n- `.config/` - Biome, Vitest, bash scripts\n\n---\n\n## Canonical Nuxt and generated shells\n\n| Mode | Stack | Command | Output |\n|------|-------|---------|--------|\n| **Canonical** (default) | Nuxt 4 + Vue 3.5 | `make web` | `web/` |\n| **Converted** (generated) | Next / Solid / Svelte / Astro product apps | `make web TARGET=next` · `solid` · `svelte` · `astro` | gitignored emit tree (see [Compiler](/en/docs/core-concepts/compiler)) |\n| **Emit demos** | Vue · React · Nuxt · Next · Solid · Svelte · Astro | `make vue` · `react` · `nuxt` · `next` · `solid` · `svelte` · `astro` | `{framework}/demo` |\n\n**Canonical Nuxt** is where you develop daily - pages, composables, and shared modules live in Vue. **Product convert** and portable emit demos fan the same nucleus into other frameworks (Next, Solid, Svelte, Astro hosts, and demos including React/Vue/Nuxt). The docs site itself stays in tracked `docs/`; `web-astro/` is a converted product emit, not that site.\n\nAll paths share `shared_modules/`, Supabase, and design tokens. You do not maintain seven unrelated codebases.\n\n---\n\n## The compiler\n\nThe compiler (`@nucleify/compiler`) is the migration core. It is not limited to presentational snippets - it works at two levels:\n\n### 1. Portable components (`*.nuc.tsx`)\n\nAuthor framework-agnostic UI with `#nuc-compiler/runtime`. The compiler emits sibling `.vue`, React `.tsx`, Solid `.tsx`, Svelte `.svelte`, and `.css` files:\n\n```tsx\nimport { component, state, handler } from '#nuc-compiler/runtime'\n\nexport default component({\n  name: 'Counter',\n  props: { label: { type: 'string', default: 'Count' } },\n  setup(props) {\n    const count = state(0)\n    const onInc = handler(() => count.set(count.value + 1))\n    return () => (\n      <button type=\"button\" onClick={onInc}>\n        {props.label}: {count.value}\n      </button>\n    )\n  },\n})\n```\n\nSee [Compiler](/en/docs/core-concepts/compiler) and `compiler/PORTABLE.md` for the full authoring rules.\n\n### 2. Product convert\n\nConvert an entire Nuxt app to Next, Solid, Svelte, or Astro:\n\n```bash\nmake web TARGET=next    # → web-next/\nmake web TARGET=solid   # → web-solid/\nmake web TARGET=svelte  # → web-svelte/\nmake web TARGET=astro   # → web-astro/\n```\n\nSame routes, shared modules, different framework host. Output is generated by the compiler - not part of the canonical monorepo layout.\n\n---\n\n## Shared modules\n\nSix exported feature modules live in `shared_modules/`:\n\n| Module | Domain |\n|--------|--------|\n| `nuc_api` | API client, gateway dispatch, auth forms, entity requests |\n| `nuc_colors` | Theme/color system, SCSS variables |\n| `nuc_dark_mode` | Dark mode preference |\n| `nuc_globals` | Media queries, global styles, shared types |\n| `nuc_languages` | i18n, locale messages, translations API |\n| `nuc_stores` | Pinia/Zustand helpers, cookie/localStorage utils |\n\nApps import modules directly or via the `modules` alias (configured in `web/.config/nuxt/structure.ts`). Registration for the web app happens in `web/src/plugins/modules.ts`.\n\nRead more: [Modules](/en/docs/core-concepts/modules) · [Feature-Sliced Design](/en/docs/core-concepts/feature-sliced-design)\n\n---\n\n## API gateway\n\nAll server API traffic flows through one Nitro catch-all:\n\n```\nweb/src/server/api/[...slug].ts\n  → dispatchSupabaseApiGateway()\n  → shared_modules/nuc_*/supabase/api/handle.ts\n```\n\nModule handlers register in `shared_modules/nuc_api/supabase/api/gateway_dispatch.ts`. Client code calls `/api/...` - never Supabase directly from the browser for privileged operations.\n\n---\n\n## Design system\n\nUI primitives are **Lit web components** from `nucleify-ui` (`nui-button`, `nui-icon`, …). Design tokens and registration live in `portable/nui/`. Every shell consumes the same custom elements; the compiler maps `nui-*` tags in `*.nuc.tsx` across emit targets (Vue, React, Solid, Svelte, and sibling shells).\n\n---\n\n## Monorepo layout\n\n```txt\nnucleify/\n├── web/                    # @nucleify/web - Nuxt 4 landing (canonical)\n│   ├── nuxt.config.ts\n│   ├── .config/nuxt/       # split Nuxt config\n│   └── src/\n│       ├── pages/          # Vue pages (e.g. home/sections/)\n│       ├── plugins/        # modules.ts, nucleify-ui.client.ts\n│       ├── composables/\n│       ├── layouts/\n│       └── server/api/     # Nitro API gateway [...slug].ts\n├── admin/                  # @nucleify/admin - Nuxt 4 admin\n├── docs/                   # @nucleify/docs - Astro 5 docs\n├── compiler/               # @nucleify/compiler - IR portable UI compiler\n├── shared_modules/         # six exported nuc_* modules\n├── portable/nui/           # design tokens, Lit nui-* registration\n├── overrides/              # overrides/{web,admin,docs,shared_modules}/\n├── supabase/\n├── .config/\n├── Makefile\n└── package.json\n```\n\nFull breakdown: [Monorepo Layout](/en/docs/core-concepts/monorepo)\n\n---\n\n## Quick commands\n\n| Command | What it does |\n|---------|--------------|\n| `make run` | Create `.env`, install deps, husky, sync rules, build compiler |\n| `make web` | Start Nuxt dev server (`web/`) |\n| `make web TARGET=next` | Convert Vue app to Next, start dev (generated output) |\n| `make web TARGET=solid` | Convert Vue app to Solid, start dev (generated output) |\n| `make web TARGET=svelte` | Convert Vue app to Svelte, start dev (generated output) |\n| `make web TARGET=astro` | Convert Vue app to Astro + React islands, start dev |\n| `make vue` / `react` / `nuxt` / `next` / `solid` / `svelte` / `astro` | Portable emit demos (`{framework}/demo`) |\n| `make admin` | Start admin Nuxt dev |\n| `make docs` | Start Astro docs dev |\n| `make compiler` | Run `pnpm compiler:check` + `pnpm compiler:build` |\n\nEquivalent pnpm shortcuts: `pnpm dev`, `pnpm admin`, `pnpm docs`.\n\n---\n\n## Next steps\n\n1. [Installation](/en/docs/getting-started/installation) - prerequisites and first setup\n2. [Quick Start](/en/docs/getting-started/quick-start) - run the landing app in minutes\n3. [Monorepo Layout](/en/docs/core-concepts/monorepo) - where everything lives\n4. [Environment](/en/docs/configuration/environment) - configure Supabase and app vars\n",
  "en/getting-started/quick-start": "# Quick Start\n\nRun Nucleify, explore the repo, and make your first change in under ten minutes.\n\n---\n\n## 1. Bootstrap\n\n```bash\ngit clone https://github.com/Nucleify/Nucleify.git\ncd Nucleify\nmake run\n```\n\nFill in `SUPABASE_*` values in the root `.env` if you plan to hit module API routes.\n\n---\n\n## 2. Start the landing app\n\n```bash\nmake web\n```\n\nVisit [http://localhost:3000/en/home](http://localhost:3000/en/home).\n\nThe landing page source lives in `web/src/pages/home/` - a set of section components composed by `web/src/pages/home/index.vue`. Routes are thin wrappers under `web/src/pages/[lang]/`:\n\n```vue\n<!-- web/src/pages/[lang]/home.vue -->\n<script setup lang=\"ts\">\nimport NucHomePage from '../home/index.vue'\n</script>\n<template><NucHomePage /></template>\n```\n\n---\n\n## 3. Understand the request flow\n\n```txt\nBrowser  →  Nuxt page (web/src/pages/)\n         →  shared_modules/nuc_*/utils/   (composables, API client)\n         →  /api/*                         (Nitro gateway)\n         →  nuc_*/supabase/api/handle.ts   (module handlers)\n         →  Supabase (PostgreSQL, Auth, Edge Functions)\n```\n\nSmoke-test the gateway:\n\n```bash\ncurl http://localhost:3000/api\ncurl http://localhost:3000/api/test\n```\n\n---\n\n## 4. Import a shared module\n\nModules resolve via the `modules` alias (`web/.config/nuxt/structure.ts` → `shared_modules/`):\n\n```typescript\nimport { useDarkMode } from 'modules/nuc_dark_mode/utils/use_dark_mode'\nimport { apiRequest } from 'modules/nuc_api/utils/api_request'\n```\n\nFour modules register automatically at app startup in `web/src/plugins/modules.ts`:\n\n- `nuc_globals`\n- `nuc_colors`\n- `nuc_dark_mode`\n- `nuc_languages`\n\n`nuc_api` and `nuc_stores` are imported where needed - no global plugin registration.\n\n---\n\n## 5. Try the compiler\n\nBuild portable emit from any `*.nuc.tsx` under discover roots (`web/`, `admin/`, `shared_modules/`, `portable/`):\n\n```bash\npnpm compiler:build\npnpm compiler:check   # exits 1 if emit is dirty vs authoring\n```\n\nConvert the entire web product to Next, Solid, or Svelte:\n\n```bash\nmake web TARGET=next    # → web-next/\nmake web TARGET=solid   # → web-solid/\nmake web TARGET=svelte  # → web-svelte/\n```\n\nThis runs `pnpm compiler -- convert web --target=…`, builds, installs, and starts the generated shell. Portable Svelte emit demo: `make svelte`. External Nuxt-like apps: `--path` / `--git` + `--out` from the monorepo root (see [Compiler](/en/docs/core-concepts/compiler)).\n\n---\n\n## 6. Run other apps\n\n```bash\nmake admin    # Nuxt admin at admin/src/pages/\nmake docs     # Astro docs at http://localhost:4321 (default Astro port)\n```\n\nDocs content is Markdown under `docs/content/{en,pl}/{category}/{slug}.md`.\n\n---\n\n## 7. Run checks\n\nBefore committing, the Husky pre-commit hook runs the same suite as CI (pre-push is a no-op):\n\n```bash\npnpm btest          # bash suite\npnpm check          # Biome\npnpm typeslint      # TypeScript (web)\npnpm slint          # Stylelint (SCSS)\npnpm build          # Nuxt production build\npnpm tests          # Vitest (web + shared)\npnpm compiler:test  # Compiler unit tests\npnpm compiler:check # Emit fingerprints\n```\n\n---\n\n## Common tasks\n\n### Add an API route to an existing module\n\n1. Add handler functions in `shared_modules/nuc_example/supabase/api/example_handlers.ts`\n2. Export `handleExampleApi` from `handle.ts`\n3. Register the handler in `shared_modules/nuc_api/supabase/api/gateway_dispatch.ts`\n4. Call `/api/example/...` from the client via `nuc_api` request helpers\n\n### Override a file without editing upstream\n\nMirror the path under `overrides/`:\n\n```txt\nweb/src/composables/useAuth.ts\n  → overrides/web/src/composables/useAuth.ts\n```\n\nSee [Overriding](/en/docs/core-concepts/overriding).\n\n### Author a portable component\n\nCreate `Foo.nuc.tsx` next to where it will be consumed. Run `pnpm compiler:build`. Commit the `.nuc.tsx` and generated siblings (`.vue`, React/Solid `.tsx`, Svelte `.svelte`, `.css`). Do not hand-edit emit as source of truth - use `pnpm compiler -- import --from=vue|react|solid|svelte` if you edited emit.\n\n---\n\n## Where to go next\n\n| Topic | Doc |\n|-------|-----|\n| Directory map | [Monorepo Layout](/en/docs/core-concepts/monorepo) |\n| Module anatomy | [Modules](/en/docs/core-concepts/modules) |\n| Compiler cycles | [Compiler](/en/docs/core-concepts/compiler) |\n| Nuxt config | [Web & Admin](/en/docs/configuration/web) |\n| Supabase workflow | [Supabase](/en/docs/configuration/supabase) |\n| Testing | [Vitest](/en/docs/tests/vitest) |\n",
  "en/tests/vitest": "# Vitest\n\nNucleify uses [Vitest](https://vitest.dev) for unit and integration tests across the monorepo. Root config defines two projects - **web** (Nuxt environment) and **shared** (happy-dom) - plus a separate compiler test suite.\n\n---\n\n## Running tests\n\n```bash\npnpm tests              # all root projects (web + shared)\npnpm test:watch         # watch mode\npnpm test:web           # Nuxt project only\npnpm test:shared        # shared_modules only\npnpm compiler:test      # compiler unit tests\n```\n\nCI and the Husky pre-commit hook run `pnpm tests` as part of `.config/bash/hook-checks.sh` alongside bash tests, Biome, TypeScript, Stylelint, Nuxt build, and compiler checks (pre-push is a no-op).\n\n---\n\n## Project configuration\n\nRoot `vitest.config.ts` defines workspace projects:\n\n### `web` project\n\n- **Root:** `web/`\n- **Environment:** `nuxt` (via `@nuxt/test-utils`)\n- **Include:** `vitests/**/*.{test,spec}.{js,ts,jsx,tsx}`\n- **Timeout:** 30s\n- **Alias:** `nucleify` → `web/src/nucleify.ts`\n\n### `shared` project\n\n- **Root:** `shared_modules/`\n- **Environment:** `happy-dom`\n- **Include:** `**/vitests/**/*.{test,spec}.{js,ts}`\n- **Timeout:** 15s\n- **Alias:** `nucleify` → `shared_modules/nucleify.ts`\n- **Define:** `import.meta.client` / `import.meta.server` shims\n\nBoth projects share setup from `.config/vitest_setup.ts` and use threaded pools.\n\n### Compiler project\n\nSeparate config at `.config/vitest.compiler.config.ts`:\n\n```bash\npnpm compiler:test\n```\n\nTests live in `compiler/tests/` (including emit/import goldens for Vue, React, Solid, and Svelte).\n\n---\n\n## Where to put tests\n\n| Location | Pattern | Project |\n|----------|---------|---------|\n| `web/vitests/` | `*.test.ts` | web |\n| `shared_modules/nuc_*/vitests/` | `*.test.ts` | shared |\n| `compiler/tests/` | fixtures + unit | compiler |\n\nCo-locate module tests inside the module (`shared_modules/nuc_colors/vitests/`). Do not put shared module tests under `web/vitests/` unless they require Nuxt runtime.\n\n---\n\n## Writing module tests\n\nExample under `shared_modules/nuc_colors/vitests/`:\n\n```typescript\nimport { describe, expect, it } from 'vitest'\nimport { darkenColor } from '../../utils/darken_color'\n\ndescribe('darkenColor', () => {\n  it('darkens a hex color', () => {\n    expect(darkenColor('#ffffff', 0.1)).toMatch(/^#[0-9a-f]{6}$/i)\n  })\n})\n```\n\nRun only shared module tests while iterating:\n\n```bash\npnpm test:shared\n```\n\n---\n\n## Writing Nuxt tests\n\nPlace files in `web/vitests/`. The Nuxt test environment mounts components with `@nuxt/test-utils`:\n\n```typescript\nimport { describe, expect, it } from 'vitest'\nimport { mountSuspended } from '@nuxt/test-utils/runtime'\nimport MyComponent from '~/components/MyComponent.vue'\n\ndescribe('MyComponent', () => {\n  it('renders', async () => {\n    const wrapper = await mountSuspended(MyComponent)\n    expect(wrapper.text()).toContain('expected')\n  })\n})\n```\n\n---\n\n## Setup file\n\n`.config/vitest_setup.ts` configures global test behavior (mocks, matchers from `@testing-library/jest-dom` where used). Both web and shared projects import it via `setupFiles`.\n\nConsole log suppression is enabled (`onConsoleLog: () => false`) to reduce noise in CI.\n\n---\n\n## Pre-commit hook suite\n\nHusky pre-commit runs (via `.config/bash/hook-checks.sh`), in order:\n\n1. `pnpm btest` - bash test suite\n2. `pnpm check` - Biome\n3. `pnpm typeslint` - TypeScript (`web/tsconfig.json`)\n4. `pnpm slint` - Stylelint on SCSS\n5. `pnpm build` - Nuxt production build\n6. `pnpm tests` - Vitest\n7. `pnpm compiler:test` - compiler unit tests\n8. `pnpm compiler:check` - emit fingerprints\n\nPre-push is a no-op. Fix failures locally before committing.\n\n---\n\n## Coverage & debugging\n\nRun a single file:\n\n```bash\npnpm vitest run shared_modules/nuc_stores/cookie/get_item/index.test.ts\npnpm vitest run --project web web/vitests/some.test.ts\n```\n\nEnable watch during development:\n\n```bash\npnpm test:watch\n```\n\n---\n\n## Related docs\n\n- [Modules](/en/docs/core-concepts/modules) - `vitests/` folder convention\n- [Coding Standards](/en/docs/about/coding-standards) - naming and structure rules\n- [Compiler](/en/docs/core-concepts/compiler) - `pnpm compiler:test`\n",
  "pl/about/code-of-conduct": "# Kodeks postępowania\n\n## Contributor Covenant Code of Conduct - Wersja 2.1\n\nNucleify podąża za [Contributor Covenant Code of Conduct 2.1](https://www.contributor-covenant.org/version/2/1/code_of_conduct/).\n\n---\n\n## Nasze zobowiązanie\n\nJako członkowie, kontrybutorzy i liderzy zobowiązujemy się zapewnić udział w naszej społeczności wolny od nękania dla wszystkich, niezależnie od wieku, rozmiaru ciała, widocznej lub niewidocznej niepełnosprawności, pochodzenia etnicznego, cech płciowych, tożsamości i ekspresji płciowej, poziomu doświadczenia, wykształcenia, statusu społeczno-ekonomicznego, narodowości, wyglądu osobistego, rasy, kasty, koloru skóry, religii lub tożsamości i orientacji seksualnej.\n\nZobowiązujemy się działać i wchodzić w interakcje w sposób przyczyniający się do otwartej, gościnnej, różnorodnej, inkluzywnej i zdrowej społeczności.\n\n---\n\n## Nasze standardy\n\n### Zachowanie pozytywne\n\nPrzykłady zachowań przyczyniających się do pozytywnego środowiska:\n\n- Okazywanie empatii i życzliwości wobec innych\n- Szanowanie odmiennych opinii, punktów widzenia i doświadczeń\n- Udzielanie i z wdziękiem przyjmowanie konstruktywnej informacji zwrotnej\n- Przyjmowanie odpowiedzialności i przepraszanie osób dotkniętych naszymi błędami oraz uczenie się na doświadczeniu\n- Skupianie się na tym, co najlepsze nie tylko dla nas jako jednostek, ale dla całej społeczności\n\n### Zachowanie niedopuszczalne\n\nPrzykłady niedopuszczalnego zachowania:\n\n- Używanie języka lub obrazów o charakterze seksualnym oraz seksualna uwaga lub zaloty jakiegokolwiek rodzaju\n- Trolling, obraźliwe lub deprecjonujące komentarze oraz ataki osobiste lub polityczne\n- Nękanie publiczne lub prywatne\n- Publikowanie prywatnych informacji innych osób, takich jak fizyczny lub adres email, bez ich wyraźnej zgody\n- Inne zachowania, które można uzasadnionie uznać za nieodpowiednie w środowisku zawodowym\n\n---\n\n## Odpowiedzialność za egzekwowanie\n\nLiderzy społeczności są odpowiedzialni za wyjaśnianie i egzekwowanie naszych standardów akceptowalnego zachowania i podejmą odpowiednie i sprawiedliwe działania korygujące w odpowiedzi na każde zachowanie, które uznają za nieodpowiednie, groźne, obraźliwe lub szkodliwe.\n\nLiderzy społeczności mają prawo i obowiązek usuwać, edytować lub odrzucać komentarze, commity, kod, edycje wiki, issues i inne wkłady, które nie są zgodne z tym Kodeksem postępowania, oraz będą komunikować powody decyzji moderacyjnych, gdy to stosowne.\n\n---\n\n## Zakres\n\nTen Kodeks postępowania obowiązuje we wszystkich przestrzeniach społeczności, a także gdy osoba oficjalnie reprezentuje społeczność w przestrzeniach publicznych. Przykłady reprezentowania naszej społeczności obejmują używanie oficjalnego adresu email, publikowanie przez oficjalne konto w mediach społecznościowych lub działanie jako wyznaczony przedstawiciel na wydarzeniu online lub offline.\n\n---\n\n## Egzekwowanie\n\nPrzypadki obraźliwego, nękającego lub innego niedopuszczalnego zachowania można zgłaszać liderom społeczności odpowiedzialnym za egzekwowanie pod adresem:\n\n**nucleify.io@gmail.com**\n\nWszystkie skargi będą szybko i sprawiedliwie rozpatrywane i badane. Wszyscy liderzy społeczności są zobowiązani do poszanowania prywatności i bezpieczeństwa zgłaszającego każdy incydent.\n\n---\n\n## Wytyczne egzekwowania\n\nLiderzy społeczności będą podążać za tymi Wytycznymi wpływu społeczności przy ustalaniu konsekwencji za każde działanie, które uznają za naruszenie tego Kodeksu postępowania:\n\n### 1. Korekta\n\n**Wpływ na społeczność**: Użycie nieodpowiedniego języka lub inne zachowanie uznane za nieprofesjonalne lub niepożądane w społeczności.\n\n**Konsekwencja**: Prywatne, pisemne ostrzeżenie od liderów społeczności, z wyjaśnieniem natury naruszenia i powodu, dla którego zachowanie było nieodpowiednie. Może zostać zażądane publiczne przeprosiny.\n\n### 2. Ostrzeżenie\n\n**Wpływ na społeczność**: Naruszenie przez pojedynczy incydent lub serię działań.\n\n**Konsekwencja**: Ostrzeżenie z konsekwencjami za kontynuowane zachowanie. Brak interakcji z zaangażowanymi osobami, w tym nieproszona interakcja z osobami egzekwującymi Kodeks postępowania, przez określony czas. Obejmuje to unikanie interakcji w przestrzeniach społeczności oraz kanałach zewnętrznych jak media społecznościowe. Naruszenie tych warunków może prowadzić do tymczasowego lub stałego bana.\n\n### 3. Ban tymczasowy\n\n**Wpływ na społeczność**: Poważne naruszenie standardów społeczności, w tym utrzymujące się nieodpowiednie zachowanie.\n\n**Konsekwencja**: Tymczasowy ban na jakąkolwiek interakcję lub publiczną komunikację ze społecznością na określony czas. Żadna publiczna ani prywatna interakcja z zaangażowanymi osobami, w tym nieproszona interakcja z osobami egzekwującymi Kodeks postępowania, nie jest dozwolona w tym okresie. Naruszenie tych warunków może prowadzić do stałego bana.\n\n### 4. Ban stały\n\n**Wpływ na społeczność**: Wykazanie wzorca naruszania standardów społeczności, w tym utrzymujące się nieodpowiednie zachowanie, nękanie jednostki lub agresja wobec lub dyskredytacja klas osób.\n\n**Konsekwencja**: Stały ban na jakąkolwiek publiczną interakcję w społeczności.\n\n---\n\n## Atrybucja\n\nTen Kodeks postępowania jest adaptacją [Contributor Covenant](https://www.contributor-covenant.org), wersja 2.1, dostępna pod adresem [https://www.contributor-covenant.org/version/2/1/code_of_conduct/](https://www.contributor-covenant.org/version/2/1/code_of_conduct/).\n\nWytyczne wpływu społeczności zostały zainspirowane [drabiną egzekwowania kodeksu postępowania Mozilli](https://github.com/mozilla/diversity).\n\nOdpowiedzi na często zadawane pytania dotyczące tego kodeksu postępowania znajdują się w FAQ pod adresem [https://www.contributor-covenant.org/faq](https://www.contributor-covenant.org/faq). Tłumaczenia są dostępne pod adresem [https://www.contributor-covenant.org/translations](https://www.contributor-covenant.org/translations).\n\n---\n\n## Powiązane\n\n- [Standardy kodowania](/pl/docs/about/coding-standards) - wytyczne techniczne dla kontrybucji\n- [Ludzie i podziękowania](/pl/docs/about/people-and-credits) - zespół i podziękowania\n",
  "pl/about/coding-standards": "# Standardy kodowania\n\nKonwencje czytelnego, spójnego kodu w monorepo Nucleify. W razie wątpliwości dopasuj się do sąsiednich plików w pakiecie, który edytujesz.\n\n---\n\n## Struktura monorepo\n\n```txt\nnucleify/\n├── web/               # @nucleify/web - landing Nuxt\n├── admin/             # @nucleify/admin - admin Nuxt\n├── docs/              # @nucleify/docs - docs Astro\n├── compiler/          # @nucleify/compiler - przenośny kompilator UI\n├── shared_modules/    # sześć eksportowanych modułów nuc_*\n├── portable/nui/      # design tokeny\n├── overrides/         # nadpisania plików per pakiet\n├── supabase/          # scalona konfiguracja DB\n└── .config/           # wspólne narzędzia\n```\n\nKanoniczne ścieżki produktu: `web/src/` (nie root `modules/` ani `nuxt/` jako srcDir). Prymitywy UI to `nui-*`, nie drzewo `ad-*`. Auth żyje w `nuc_api`.\n\n---\n\n## Komendy pakietów\n\n| Pakiet | Komenda dev |\n|--------|-------------|\n| `web/` | `make web` lub `pnpm dev` |\n| `admin/` | `make admin` lub `pnpm admin` |\n| `docs/` | `make docs` lub `pnpm docs` |\n| `compiler/` | `make compiler` |\n\nUruchomienie: `make run`. Powłoka produktu: `make web`. Demo emit portable: `make vue` / `react` / `nuxt` / `next` / `solid` / `svelte` (to nie aplikacja produktu).\n\n---\n\n## Struktura modułu współdzielonego\n\n```txt\nshared_modules/nuc_example/\n├── config.json\n├── nuc_example.ts           # registerNucExample (plugin Vue)\n├── index.ts                 # barrel Vue\n├── index.react.ts           # barrel React (gdy potrzebny)\n├── _index.scss\n├── supabase/api/handle.ts\n├── constants/\n├── types/\n├── utils/\n├── components/              # opcjonalnie\n└── vitests/\n```\n\n**Reguły importu:**\n\n- Wewnątrz modułów: tylko importy względne\n- Nigdy nie importuj z `web/`, `admin/` ani `docs/` wewnątrz modułów\n- Nigdy `import from 'nucleify'` wewnątrz modułów (cykl)\n- Aplikacje importują przez alias `modules/…` lub ścieżki `shared_modules/…`\n\n---\n\n## Struktura aplikacji web\n\n```txt\nweb/src/\n├── pages/[lang]/            # cienkie wrappery i18n\n├── pages/home/              # kompozycja landingu\n├── plugins/modules.ts       # registerNuc*\n├── composables/             # tylko app-specific\n├── layouts/\n├── assets/                  # wejście SCSS\n├── nucleify.ts              # re-eksporty\n└── server/api/[...slug].ts  # bramka\n```\n\n- Vue SFC: `<script setup lang=\"ts\">`\n- UI: `nui-*` z `nucleify-ui`\n- Logika domenowa: `shared_modules/`, nie `web/src/`\n\n---\n\n## Nazewnictwo plików i folderów\n\n| Rodzaj | Konwencja | Przykład |\n|--------|-----------|----------|\n| Vue SFC | PascalCase | `NucHomeHero.vue` |\n| Composable | `use_` + snake_case | `use_dark_mode.ts` |\n| Sibling hook React | `.react.ts` | `use_dark_mode.react.ts` |\n| Komponent przenośny | PascalCase + `.nuc.tsx` | `Counter.nuc.tsx` |\n| Utils | snake_case | `api_request.ts` |\n| Typy | pliki snake_case | `interfaces.ts`, `variables.ts` |\n| Testy | `*.test.ts` w `vitests/` | `darken_color.test.ts` |\n| Partiale SCSS | `_name.scss` | `_mixins.scss` |\n\n---\n\n## TypeScript\n\n- Strict typing - unikaj `any`, chyba że config Nuxt wymusza (dokumentuj biome-ignore)\n- Eksportuj typy z `types/` - nie duplikuj interfejsów między plikami\n- Używaj siblingów typów `.react.ts`, gdy props React odbiegają od Vue\n\n---\n\n## Komponenty Vue\n\n```vue\n<script setup lang=\"ts\">\nimport { ref } from 'vue'\nimport type { SomeType } from 'modules/nuc_example/types/interfaces'\n\nconst props = defineProps<{ id: string }>()\nconst open = ref(false)\n</script>\n\n<template>\n  <nui-button @click=\"open = !open\">{{ props.id }}</nui-button>\n</template>\n```\n\n- Preferuj Composition API z `<script setup>`\n- Prymitywy: `nui-*`; UI domenowe: komponenty modułów\n\n---\n\n## Komponenty przenośne\n\nAutoruj w `*.nuc.tsx` zgodnie z `compiler/PORTABLE.md`:\n\n- Bez store, routerów ani Supabase w plikach przenośnych\n- Na zewnątrz tylko props + events\n- Po zmianach: `pnpm compiler:build`; commituj autorstwo + emit\n- Import edycji: `pnpm compiler -- import --from=vue|react|solid|svelte`\n- Nie re-eksportuj `*.nuc.tsx` z publicznych barreli (`index.ts`, `modules.ts`, …)\n- Łamiące zmiany IR podnoszą `IR_VERSION` i migrują fixture’y w tym samym PR\n\n---\n\n## Handlery API\n\n- Wejście: `handle.ts` eksportuje `handle*Api`\n- Rejestracja w `shared_modules/nuc_api/supabase/api/gateway_dispatch.ts`\n- Zwracaj `apiNotHandled()` dla niedopasowanych prefiksów\n- Używaj `withGatewayUser` dla tras uwierzytelnionych\n- Włącz RLS na eksponowanych tabelach\n\n---\n\n## SCSS\n\n- Style modułów: `shared_modules/nuc_*/styles/`\n- Wejście aplikacji importuje pliki `_index.scss` modułów\n- Lint: `pnpm slint`\n\n---\n\n## Testy\n\n- Testy modułów: `shared_modules/nuc_*/vitests/`\n- Testy Nuxt: `web/vitests/`\n- Przed commitem: `pnpm tests`\n- Testuj zachowanie - unikaj asercji szczegółów implementacji\n\n---\n\n## Lint i format\n\n```bash\npnpm check       # Biome (lint + format check)\npnpm write       # Biome auto-fix\npnpm typeslint   # tsc --noEmit -p web/tsconfig.json\npnpm slint       # Stylelint na SCSS\npnpm tests       # Vitest\n```\n\nHusky uruchamia to na pre-commit przez `.config/bash/hook-checks.sh` (pre-push jest no-op).\n\n---\n\n## Git i commity\n\n- Skupione commity - jedna sprawa na zmianę, gdy to możliwe\n- Nie commituj `.env`, demo emit (`vue/demo` itd.) ani `*.ir.json`\n- Trzymaj się istniejącego stylu wiadomości commitów w repo\n\n---\n\n## Reguły Cursor i agenci\n\n- Reguły monorepo: `.cursor/rules/`\n- Reguły pakietu: `{pkg}/.config/rules/`\n- Sync: `pnpm sync-rules`\n- Agenci workflow feature: `web/.cursor/agents/`\n\n---\n\n## Powiązana dokumentacja\n\n- [Moduły](/pl/docs/core-concepts/modules)\n- [Feature-Sliced Design](/pl/docs/core-concepts/feature-sliced-design)\n- [Vitest](/pl/docs/tests/vitest)\n- [Kodeks postępowania](/pl/docs/about/code-of-conduct)\n\nReferencja root: `CODE_STANDARDS.md` w repozytorium (utrzymuj w sync z tą stroną).\n",
  "pl/about/people-and-credits": "# Ludzie i podziękowania\n\nLudzie i projekty, które czynią Nucleify możliwym.\n\n---\n\n## Zespół core\n\n### Twórca i lider\n\n| Imię i nazwisko | Rola | GitHub |\n|-----------------|------|--------|\n| Szymon Wieczorek | Architektura, kompilator, moduły, development full-stack | [@szymcode](https://github.com/szymcode) |\n\n---\n\n## Kontrybutorzy\n\nDziękujemy wszystkim, którzy przyczynili się do Nucleify! (Tylko osoby - boty automatyzacji pomijamy.)\n\n| Imię i nazwisko | GitHub |\n|-----------------|--------|\n| Katarzyna Śmierzchalska | [@KatarzynaS97](https://github.com/KatarzynaS97) |\n| Kamil D. | [@K4mD4m](https://github.com/K4mD4m) |\n| Marcin Fuks | [@J0jeQ](https://github.com/J0jeQ) |\n| Jakub Malik | [@JakubMalik](https://github.com/JakubMalik) |\n| Kacper Bujak | [@kbujak09](https://github.com/kbujak09) |\n| – | [@karol199393](https://github.com/karol199393) |\n| – | [@domizalewska](https://github.com/domizalewska) |\n| Kamil Błoski | [@kbloski](https://github.com/kbloski) |\n| – | [@Kacper658](https://github.com/Kacper658) |\n| Mateusz Szymański | [@dezmerek](https://github.com/dezmerek) |\n| – | [@pysifoo](https://github.com/pysifoo) |\n\nWszyscy kontrybutorzy są wymienieni na stronie [GitHub Contributors](https://github.com/Nucleify/Nucleify/graphs/contributors).\n\n---\n\n## Zbudowane z\n\nNucleify stoi na projektach open source:\n\n### Backend i dane\n\n| Projekt | Opis |\n|---------|------|\n| [Supabase](https://supabase.com) | PostgreSQL, Auth, Storage, Edge Functions |\n| [@supabase/supabase-js](https://github.com/supabase/supabase-js) | Klient JavaScript |\n\n### Frontend\n\n| Projekt | Opis |\n|---------|------|\n| [Vue 3](https://vuejs.org) | Kanoniczny framework UI (źródło Nuxt/Vue) |\n| [Nuxt 4](https://nuxt.com) | Framework full-stack Vue |\n| [React 19](https://react.dev) | Cel UI kompilatora (convert / emit) |\n| [Next.js 15](https://nextjs.org) | Framework full-stack React |\n| [Solid](https://www.solidjs.com) | Cel convert / emit (sygnały) |\n| [Svelte](https://svelte.dev) | Cel convert / emit (runy Svelte 5) |\n| [nucleify-ui](https://www.npmjs.com/package/nucleify-ui) | Biblioteka web components Lit (`nui-*`) |\n| [Lit](https://lit.dev) | Web components dla prymitywów design systemu |\n\n### Kompilator i narzędzia\n\n| Projekt | Opis |\n|---------|------|\n| [TypeScript](https://www.typescriptlang.org) | Type safety w całym stacku |\n| [Vite](https://vitejs.dev) | Narzędzie build (Nuxt / Vitest) |\n| [SCSS](https://sass-lang.com) | Preprocesor CSS |\n| [Biome](https://biomejs.dev) | Formatowanie i linting |\n| [Vitest](https://vitest.dev) | Testy jednostkowe i integracyjne |\n| [pnpm](https://pnpm.io) | Menedżer pakietów monorepo |\n| [Astro](https://astro.build) | Strona dokumentacji (`@nucleify/docs`) |\n\n---\n\n## Wpływy architektoniczne\n\n| Idea | Źródło |\n|------|--------|\n| Feature-Sliced Design | [feature-sliced.design](https://feature-sliced.design) - układ modułów domena-first |\n| Atomic Design | [Brad Frost](https://atomicdesign.bradfrost.com) - hierarchia SCSS w `nuc_colors` |\n| Portable UI / IR | `@nucleify/compiler` - `*.nuc.tsx` → Vue + React + Solid + Svelte |\n\n---\n\n## Specjalne podziękowania\n\n- Społecznościom Supabase, Vue, React, Nuxt, Astro, Svelte i Solid\n- Wszystkim, którzy zgłaszali błędy lub sugerowali funkcje\n- Maintainerom open source wszędzie\n\n---\n\n## Chcesz kontrybuować?\n\nZapraszamy wkłady wszelkiego rodzaju:\n\n- Raporty błędów\n- Sugestie funkcji\n- Ulepszenia dokumentacji\n- Wkład kodowy\n\nZacznij od [Standardów kodowania](/pl/docs/about/coding-standards) i [Kodeksu postępowania](/pl/docs/about/code-of-conduct).\n\n---\n\n## Licencja\n\nNucleify to oprogramowanie open source na licencji [MIT License](https://opensource.org/licenses/MIT).\n",
  "pl/about/philosophy": "# Filozofia\n\n> Zbuduj raz. Przenieś na dowolny framework - bez przepisywania produktu.\n\n**Migracja jest produktem.** Współdzielone moduły to jądro. Kompilator oparty na IR to sposób zmiany shella. Siedem nowoczesnych runtime’ów webowych.\n\n---\n\n## Problem\n\nZespoły wcześnie wiążą się ze stackiem - Vue albo React, Nuxt albo Next - a potem płacą podatek od przepisywania, gdy rynek, rekrutacja albo klient wymagają innego frameworka. Auth, i18n, theming i kształt API są kopiowane między projektami. Toolchainy „tylko komponenty” zostawiają aplikację, trasy i domenę za sobą.\n\nNucleify traktuje **migrację między technologiami** jako trwałą warstwę monorepo - nie boczny eksperyment. Pokrycie to siedem shelli: **Vue · React · Nuxt · Next · Astro · Svelte · Solid**.\n\n---\n\n## Wizja\n\nJedno jądro. Trzy powierzchnie produktu. Siedem shelli. Jeden pipeline migracji.\n\n1. **Współdzielone moduły** - API, SQL, UI i logika domenowa w `shared_modules/`\n2. **Trzy powierzchnie** - `web/`, `admin/` i `docs/` z tego samego jądra\n3. **Migracja jako komenda** - emit przenośny dla UI, konwersja produktu dla całych aplikacji, import z powrotem z brudnego emitu - bez przepisywania biznesu\n4. **Jeden backend Supabase** - gateway, SQL w modułach\n\nCodzienna edycja zostaje na Nuxt (`web/`). Zmiana shella to przebieg kompilatora, nie projekt przepisywania.\n\n---\n\n## Metafora jądra\n\nJak jądro komórki, Nucleify koordynuje produkt. Każdy eksportowany moduł `nuc_*` to samodzielna jednostka - utils frontendu, opcjonalne handlery API, migracje, testy.\n\n- **Samodzielne moduły** - pionowe plastry, nie rozrzucone warstwy\n- **Wyraźne granice** - aplikacje komponują; moduły nie importują aplikacji\n- **Organiczny wzrost** - dodawaj lub usuwaj moduły bez przebudowy monorepo\n- **Siła zbiorowa** - jeden model domenowy na web, admin, docs i każdy shell\n\n---\n\n## Podstawowe zasady\n\n### 1. Dowolny stack → dowolny inny\n\nTo jest pętla rdzeniowa. Przenośne komponenty `*.nuc.tsx` emitują przez własny IR do Vue, React, Solid, Svelte i Astro. Shelle produktu (`web` / `admin`) konwertujesz jedną komendą - także zewnętrzny folder Nuxt-like lub URL git przez `--path` / `--git` (zob. [Kompilator](/pl/docs/core-concepts/compiler)). Zmiany z emitu wracają do źródła. Biznes nie forkuje się per host.\n\n```bash\nmake web TARGET=next\nmake web TARGET=solid\nmake web TARGET=svelte\nmake web TARGET=astro\nmake admin TARGET=next\nmake admin TARGET=solid\nmake admin TARGET=svelte\n```\n\nWybór frameworka staje się **celem builda**, nie forkiem architektury.\n\n### 2. Moduły zamiast monolitów\n\nLogika domenowa żyje w `shared_modules/nuc_*`, nie jest kopiowana między aplikacjami. Zobacz [Feature-Sliced Design](/pl/docs/core-concepts/feature-sliced-design).\n\n### 3. Gateway, nie spaghetti\n\nUprzywilejowany dostęp serwerowy idzie przez `web/src/server/api/[...slug].ts`. Klient nie trzyma service key. Moduły rejestrują handlery; gateway je dispatchuje.\n\n### 4. Konwencja zamiast konfiguracji\n\nPodzielona konfiguracja Nuxt, spójny layout modułów, skróty Makefile, checki Husky - przewidywalne ścieżki zmniejszają zmęczenie decyzjami.\n\n### 5. Overrides do forków, moduły do współdzielenia\n\nRóżnice white-label idą do `overrides/`. Zachowanie między produktami należy do `shared_modules/`.\n\n### 6. Uczciwość kompilatora\n\nPrzenośne autorstwo ma jawne listy dozwolone/zabronione (`compiler/PORTABLE.md`). IR mostkuje frameworki - nie udajemy, że Vue i React są identyczne. Round-trip import i konwersja produktu są pierwszorzędne; jednokierunkowy dump komponentów nie jest celem.\n\n---\n\n## Kanoniczny Nuxt vs wygenerowane shelle\n\n| Codziennie (Nuxt) | Migracja / emit (convert) |\n|---------------------|--------------------------|\n| Edycja Nuxt + Vue w `web/` | Shelle Next, Solid, Svelte, Astro + demo portable |\n| Źródło prawdy | Wygenerowane lustra, gdy klient lub zespół potrzebuje innego shella |\n\nWygenerowane shelle to nie druga baza kodu utrzymywana ręcznie. Napraw jądro, uruchom convert ponownie. Komunikacja produktu zawsze wymienia **wszystkie siedem shelli**, nawet gdy codzienna edycja zostaje na Nuxt.\n\n---\n\n## Design system\n\nPrymitywy UI to **niezależne od frameworka komponenty Lit** (`nui-*` z `nucleify-ui`). Tokeny w `portable/nui/`. Każdy shell owija te same custom elements.\n\n---\n\n## Jakość\n\nMonorepo egzekwuje jakość na pre-commit (pre-push jest no-op):\n\n- Suite bash, Biome, TypeScript (web), Stylelint\n- Produkcyjny build Nuxt\n- Vitest (web + shared) oraz testy / check kompilatora\n\n---\n\n## Czym Nucleify nie jest\n\n- Nie meta-framework ukrywający hosty - siedem shelli pozostaje widocznych\n- Nie warstwa „tylko emit komponentów” - konwersja produktu przenosi całe aplikacje ze współdzielonymi modułami\n- Nie low-code - piszesz prawdziwy TypeScript\n- Nie hosted SaaS - Ty trzymasz Supabase i deployment\n- Nie „tajemnicze moduły” - dziś produkt napędza sześć eksportowanych pakietów `nuc_*`\n\n---\n\n## Powiązane\n\n- [Wprowadzenie](/pl/docs/getting-started/introduction) - przegląd techniczny\n- [Moduły](/pl/docs/core-concepts/modules) - architektura modułów\n- [Kompilator](/pl/docs/core-concepts/compiler) - emit i convert\n- [Standardy kodu](/pl/docs/about/coding-standards) - konwencje dnia codziennego\n",
  "pl/configuration/environment": "# Zmienne środowiskowe\n\nNucleify czyta zmienne środowiskowe z jednego pliku `.env` w **root repozytorium**. `make run` tworzy go z `web/.config/.env.example`. Nuxt ładuje zmienne przez `web/.config/nuxt/load-env.ts` przed ewaluacją configu.\n\n---\n\n## Setup\n\n```bash\nmake run\n# edytuj .env w root repozytorium\n```\n\nNigdy nie commituj `.env`. Szablony są w `web/.config/`:\n\n| Plik | Cel |\n|------|-----|\n| `.env.example` | Lokalny development (kopiowany przez `make run`) |\n| `.env.ci.example` | Referencja CI |\n| `.env.test.example` | Referencja środowiska testowego |\n\n---\n\n## Aplikacja\n\n| Zmienna | Przykład | Opis |\n|---------|----------|------|\n| `APP_NAME` | `Nucleify` | Wyświetlana nazwa aplikacji |\n| `APP_ENV` | `local` | `local` / `production` / `testing` |\n| `APP_DEBUG` | `true` | Flaga debug |\n| `NUXT_PUBLIC_APP_URL` | `http://localhost:3000` | Publiczny URL aplikacji (też w runtime config) |\n\n---\n\n## Supabase\n\n| Zmienna | Wymagane | Opis |\n|---------|----------|------|\n| `SUPABASE_URL` | Tak (dla tras API) | URL projektu |\n| `SUPABASE_KEY` | Klient | Klucz anon/public - bezpieczny w przeglądarce przez runtime config |\n| `SUPABASE_SERVICE_ROLE_KEY` | Serwer | Service role - **nigdy** nie eksponuj klientowi |\n| `SUPABASE_EDGE_BASE` | Opcjonalnie | Bazowy URL Edge Functions (domyślnie z `SUPABASE_URL`) |\n\nBramka Nitro w `web/src/server/api/[...slug].ts` czyta `SUPABASE_URL` i `SUPABASE_SERVICE_ROLE_KEY` z runtime config Nitro. Brak wartości → HTTP 503 dla tras modułów; smoke `/api` i `/api/test` nadal odpowiadają.\n\nMapowanie runtime (`web/.config/nuxt/runtime.ts`):\n\n```typescript\nexport const runtimeConfig = {\n  supabaseServiceRoleKey: process.env.SUPABASE_SERVICE_ROLE_KEY || '',\n  public: {\n    supabaseUrl: process.env.SUPABASE_URL || '',\n    supabaseKey: process.env.SUPABASE_KEY || '',\n    supabaseEdgeBase: process.env.SUPABASE_EDGE_BASE || `${process.env.SUPABASE_URL || ''}/functions/v1`,\n    appUrl: process.env.NUXT_PUBLIC_APP_URL || 'https://nucleify.io',\n    apiUrl: process.env.NUXT_PUBLIC_API_URL || '/api',\n    appEnv: process.env.APP_ENV || 'production',\n  },\n}\n```\n\n---\n\n## Nuxt / Nitro\n\n| Zmienna | Przykład | Opis |\n|---------|----------|------|\n| `SSR` | `true` | Server-side rendering |\n| `NITRO_PRESET` | `cloudflare` | Preset wdrożenia Nitro |\n| `PRERENDER_ROUTES` | `/home,/investor,/404` | Trasy statyczne, przecinkami (docs na docs.nucleify.io) |\n| `PRERENDER_CRAWL_LINKS` | `true` | Podążaj za linkami przy prerender |\n| `PRERENDER_IGNORE` | `/settings` | Trasy do pominięcia |\n| `PRERENDER_LOCALES` | `en,pl,vn` | Locale w prerender |\n| `DEV_TOOLS` | | Przełącznik Nuxt DevTools |\n\n---\n\n## Specyficzne dla Nucleify\n\n| Zmienna | Przykład | Opis |\n|---------|----------|------|\n| `NUC_SUBMODULES_BRANCH` | `main` | Branch dla `prepare:submodules` |\n| `NUC_SUBMODULES_CHECK` | `1` | Pomiń istniejące katalogi przy prepare submodules |\n| `NUC_ALLOWED_ORIGINS` | | Allowlista CORS |\n| `NUC_ALLOWED_ORIGINS_PATTERNS` | | Wzorce allowlisty CORS |\n| `NUC_CONVERT_DOCUMENTS_URL` | | Zewnętrzna usługa konwersji dokumentów |\n\n---\n\n## Integracje (opcjonalne)\n\nPrzykładowe `.env` zawiera placeholdery Calendly i Google Calendar OAuth. Uzupełnij tylko, gdy włączysz te integracje we wdrożeniu.\n\n| Grupa | Zmienne |\n|-------|---------|\n| Calendly | `CALENDLY_CLIENT_ID`, `CALENDLY_CLIENT_SECRET`, `CALENDLY_WEBHOOK_SIGNING_KEY`, … |\n| Google Calendar | `GOOGLE_CALENDAR_CLIENT_ID`, `GOOGLE_CALENDAR_CLIENT_SECRET`, … |\n\n---\n\n## Shelle produktu (Next / Solid / Svelte)\n\nWygenerowane shelle Next czytają zmienne Supabase w obu konwencjach nazewnictwa, gdzie to wspierane:\n\n- `NEXT_PUBLIC_SUPABASE_URL` lub `SUPABASE_URL`\n- `SUPABASE_SERVICE_ROLE_KEY` (tylko serwer)\n\nShelle produktu Solid i Svelte (`web-solid/`, `web-svelte/`, …) używają tych samych nazw `SUPABASE_*` z roota przez Vite `import.meta.env`. Trzymaj jedno root `.env` - Nuxt i wszystkie ścieżki codegen konwersji rozwiązują je z root monorepo.\n\n---\n\n## Lokalny workflow Supabase\n\nPrzy Supabase CLI zlinkowanym do projektu:\n\n```bash\npnpm supabase:migrations:apply:local\npnpm supabase:seeders:apply:local\n# lub:\npnpm supabase:setup:local\n```\n\nSzczegóły merge migracji: [Supabase](/pl/docs/configuration/supabase).\n\n---\n\n## Checklist bezpieczeństwa\n\n1. **Nigdy** nie commituj `SUPABASE_SERVICE_ROLE_KEY`\n2. Eksponuj klientowi tylko `SUPABASE_KEY` (anon) przez `runtimeConfig.public`\n3. Uprzywilejowane operacje DB idą przez handlery bramki `/api/*`\n4. Przejrzyj `NUC_ALLOWED_ORIGINS*` przed deployem produkcyjnym\n\n---\n\n## Powiązana dokumentacja\n\n- [Instalacja](/pl/docs/getting-started/installation) - pierwsze utworzenie `.env`\n- [Web & Admin](/pl/docs/configuration/web) - runtime config i rozdzielona konfiguracja Nuxt\n- [Supabase](/pl/docs/configuration/supabase) - baza i migracje\n",
  "pl/configuration/supabase": "# Supabase\n\nNucleify używa [Supabase](https://supabase.com) do PostgreSQL, Auth, Storage i Edge Functions. Schemat bazy i seedery są **własnością modułów funkcjonalnych** w `shared_modules/nuc_*/supabase/` i scalane na poziomie monorepo pod `supabase/`.\n\nDostęp serwerowy z Nuxt idzie przez bramkę API Nitro - nie przez bezpośrednie wywołania service-role z przeglądarki. To samo dotyczy wygenerowanych shelli (Next, Solid, Svelte): współdzielą tę samą instancję Supabase i ten sam model modułów.\n\n---\n\n## Architektura\n\n```txt\nPrzeglądarka\n  → /api/*  (web/src/server/api/[...slug].ts)\n  → dispatchSupabaseApiGateway()\n  → nuc_*/supabase/api/handle.ts\n  → Supabase (PostgreSQL, Auth, Edge Functions)\n```\n\nRejestr bramki:\n\n```typescript\n// shared_modules/nuc_api/supabase/api/gateway_dispatch.ts\nexport const supabaseApiGatewayHandlers = [\n  handleColorsApi,\n  handleLanguagesApi,\n] as const\n```\n\nDodawaj domeny przez implementację `handle*Api` i dopisanie do tej tablicy.\n\n---\n\n## Środowisko\n\nUstaw w root `.env` (zob. [Zmienne środowiskowe](/pl/docs/configuration/environment)):\n\n```env\nSUPABASE_URL=https://your-project.supabase.co\nSUPABASE_KEY=your-anon-key\nSUPABASE_SERVICE_ROLE_KEY=your-service-role-key\nSUPABASE_EDGE_BASE=\n```\n\n- **`SUPABASE_KEY`** - eksponowany klientowi przez `runtimeConfig.public`\n- **`SUPABASE_SERVICE_ROLE_KEY`** - tylko serwer, używany przez bramkę Nitro\n\n---\n\n## Układ SQL modułu\n\nKażdy moduł może dostarczać artefakty SQL:\n\n```txt\nshared_modules/nuc_example/supabase/\n├── api/\n│   ├── handle.ts\n│   └── example_handlers.ts\n├── migrations/       # zmiany schematu (*.sql)\n├── factories/        # SQL factory dla dev/test\n└── seeders/          # dane seed (*.sql)\n```\n\nPrzykłady w monorepo:\n\n- `nuc_colors/supabase/migrations/`, `seeders/`, `factories/`\n- `nuc_languages/supabase/migrations/`\n\n---\n\n## Merge i skrypty apply\n\nSQL modułów scala się do projektu Supabase monorepo skryptami bash w `.config/bash/`:\n\n| Skrypt | Komenda |\n|--------|---------|\n| Merge całego SQL modułów | `pnpm supabase:merge-sql` |\n| Zastosuj migracje (local) | `pnpm supabase:migrations:apply:local` |\n| Zastosuj migracje (linked remote) | `pnpm supabase:migrations:apply:linked` |\n| Zastosuj factories (local) | `pnpm supabase:factories:apply:local` |\n| Zastosuj seeders (local) | `pnpm supabase:seeders:apply:local` |\n| Pełny setup local | `pnpm supabase:setup:local` |\n| Pełny setup linked | `pnpm supabase:setup:linked` |\n\nImplementacja:\n\n- `.config/bash/merge-module-supabase-sql.sh` - zbiera SQL modułów\n- `.config/bash/apply-module-migrations.sh` - uruchamia migracje\n- `.config/bash/apply-module-sql.sh` - uruchamia factories/seeders\n\n---\n\n## Pisanie handlerów API\n\n### Wejście bramki (`handle.ts`)\n\n```typescript\nimport { apiNotHandled, apiMethodNotAllowed } from 'nuc_api'\nimport type { ApiContext, ApiHandlerResult } from 'nuc_server'\n\nexport async function handleExampleApi(ctx: ApiContext): Promise<ApiHandlerResult> {\n  if (ctx.segments[0] !== 'example') return apiNotHandled()\n  // dispatch do tabeli tras …\n  return apiMethodNotAllowed()\n}\n```\n\nZwróć `apiNotHandled()`, gdy prefiks ścieżki nie pasuje - bramka próbuje kolejnego handlera.\n\n### Trasy z auth\n\nUżywaj helperów z `nuc_api`:\n\n```typescript\nimport { withGatewayUser } from 'nuc_api'\n\nreturn withGatewayUser(ctx, async (gatewayCtx, userId) => {\n  // userId dostępny dla zapytań w zakresie RLS\n})\n```\n\n### Requesty klienta\n\nUżywaj narzędzi requestów `nuc_api` z frontendu:\n\n```typescript\nimport { apiRequest } from 'modules/nuc_api/utils/api_request'\n```\n\nNigdy nie osadzaj klucza service role w kodzie klienta.\n\n---\n\n## Row Level Security\n\nWłącz RLS na tabelach eksponowanych przez PostgREST. Dodaj polityki dla roli `authenticated`. Migracje modułów powinny zawierać polityki obok definicji tabel.\n\nTestuj polityki zarówno na kliencie anon, jak i authenticated przed shipem.\n\n---\n\n## Edge Functions\n\nFunkcje edge modułu żyją pod `shared_modules/nuc_*/supabase/functions/`. Przykład:\n\n```txt\nshared_modules/nuc_colors/supabase/functions/user-colors/index.ts\n```\n\n`SUPABASE_EDGE_BASE` w `.env` domyślnie wskazuje na `{SUPABASE_URL}/functions/v1`.\n\n---\n\n## Lokalny workflow developerski\n\n1. Zainstaluj Supabase CLI i uruchom lokalny stack (lub zlinkuj remote)\n2. Skonfiguruj root `.env` z URL i kluczami projektu\n3. Zaaplikuj scalony SQL:\n\n```bash\npnpm supabase:setup:local\n```\n\n4. Uruchom Nuxt:\n\n```bash\nmake web\n```\n\n5. Zweryfikuj bramkę:\n\n```bash\ncurl http://localhost:3000/api\ncurl http://localhost:3000/api/colors/…   # trasy konkretnego modułu\n```\n\n---\n\n## Katalog monorepo `supabase/`\n\nTop-level `supabase/` trzyma config projektu, scalony output migracji i wspólną konfigurację edge - wypełniany skryptami merge ze źródeł modułów.\n\n---\n\n## Powiązana dokumentacja\n\n- [Moduły](/pl/docs/core-concepts/modules) - struktura modułu i rejestracja bramki\n- [Zmienne środowiskowe](/pl/docs/configuration/environment) - zmienne Supabase\n- [Web & Admin](/pl/docs/configuration/web) - punkt wejścia bramki Nitro\n",
  "pl/configuration/web": "# Web & Admin\n\n`web/` i `admin/` to aplikacje Nuxt 4 (kanoniczne źródło). Konfiguracja jest rozdzielona między `web/.config/nuxt/` (i odpowiednik w `admin/`) i składana przez cienki `nuxt.config.ts` w root każdego pakietu.\n\n---\n\n## Kompozycja konfiguracji\n\n```txt\nweb/\n├── nuxt.config.ts          # importuje i rozprzestrzenia moduły konfiguracji\n└── .config/nuxt/\n    ├── load-env.ts         # ładuje root .env monorepo przed ewaluacją config\n    ├── app.ts              # head, meta, base URL\n    ├── structure.ts        # aliasy, srcDir, pluginy, importy\n    ├── runtime.ts          # runtimeConfig (klucze publiczne + prywatne)\n    ├── modules.ts          # moduły Nuxt (@nuxtjs/i18n itd.)\n    ├── locales.ts          # lista locale i konfiguracja i18n\n    ├── nitro.ts            # preset serwera, handlery\n    ├── vite.ts             # pluginy Vite, SCSS, opcje build\n    ├── route-rules.ts      # SWR, prerender, cache per trasa\n    ├── performance.ts      # fonty, optymalizacja obrazów\n    ├── dev.ts              # ustawienia tylko dla dev\n    └── hooks.ts            # hooki cyklu życia Nuxt\n```\n\n`admin/` podąża za tym samym wzorcem z własnym katalogiem `.config/nuxt/`.\n\n---\n\n## Układ źródeł\n\nObie aplikacje używają `srcDir: 'src'` (nie folderu `nuxt/`):\n\n```txt\nweb/src/\n├── pages/\n│   ├── [lang]/             # cienkie wrappery tras i18n\n│   └── home/               # sekcje landingowe\n├── plugins/\n│   ├── modules.ts          # registerNuc* dla modułów współdzielonych\n│   └── nucleify-ui.client.ts\n├── composables/            # auto-importowane\n├── layouts/\n├── assets/styles/          # wpis SCSS (importuje style shared_modules)\n├── nucleify.ts             # re-eksportuje powierzchnię współdzieloną + helpery app\n└── server/\n    └── api/\n        └── [...slug].ts    # catch-all Nitro → gateway_dispatch\n```\n\nPrymitywy UI to custom elements Lit (`nui-*`) z `nucleify-ui` / `portable/nui/`. Kompozycja landingu jest w `web/src/pages/` - nie ma drzewa komponentów `ad-*`.\n\n---\n\n## Aliasy\n\nZdefiniowane w `web/.config/nuxt/structure.ts`:\n\n| Alias | Rozwiązuje się do |\n|-------|-------------------|\n| `nucleify` | `~/nucleify` (barrel aplikacji) |\n| `modules` | `../shared_modules` |\n| `portable/nui` | `../portable/nui` |\n| `nuc_client` | `~/nuc_client` |\n| `nuc_server` | `~/server/nuc_server` |\n| `#nuc-compiler/runtime` | `../compiler/runtime/index.ts` |\n\nImportuj moduły współdzielone po nazwie pakietu (np. `import { apiRequest } from 'nuc_api'`) - alias `modules` to umożliwia.\n\n---\n\n## Rejestracja modułów\n\nModuły współdzielone rejestrują się jako pluginy Vue w `web/src/plugins/modules.ts`:\n\n```typescript\nimport { defineNuxtPlugin } from 'nuxt/app'\nimport { registerNucColors } from '../../../shared_modules/nuc_colors/nuc_colors'\nimport { registerNucDarkMode } from '../../../shared_modules/nuc_dark_mode/nuc_dark_mode'\nimport { registerNucGlobals } from '../../../shared_modules/nuc_globals/nuc_globals'\nimport { registerNucLanguages } from '../../../shared_modules/nuc_languages/nuc_languages'\n\nexport default defineNuxtPlugin({\n  name: 'modules-registration',\n  enforce: 'pre',\n  setup(nuxtApp) {\n    registerNucGlobals(nuxtApp.vueApp)\n    registerNucColors(nuxtApp.vueApp)\n    registerNucDarkMode(nuxtApp.vueApp)\n    registerNucLanguages(nuxtApp)\n  },\n})\n```\n\n`registerNucLanguages` otrzymuje pełny `nuxtApp`, ponieważ podłącza się do zdarzeń i18n Nuxt.\n\n---\n\n## Runtime config\n\n`web/.config/nuxt/runtime.ts` udostępnia zmienne środowiskowe aplikacji:\n\n**Prywatne** (tylko serwer):\n\n- `supabaseServiceRoleKey`\n- `authEmailResendKey`\n- `authEmailFrom`\n- `contactFormRecipient`\n\n**Publiczne** (klient + serwer):\n\n- `appUrl`, `apiUrl`, `supabaseUrl`, `supabaseKey`, `supabaseEdgeBase`, `appEnv`\n\n```typescript\nconst config = useRuntimeConfig()\nconst apiUrl = config.public.apiUrl  // '/api'\n```\n\nZobacz [Zmienne środowiskowe](/pl/docs/configuration/environment) po pełną referencję zmiennych.\n\n---\n\n## Bramka API\n\nCały ruch API serwera przechodzi przez jeden catch-all Nitro:\n\n```\nweb/src/server/api/[...slug].ts\n  → dispatchSupabaseApiGateway()\n  → shared_modules/nuc_*/supabase/api/handle.ts\n```\n\nKod klienta wywołuje `/api/...` - nigdy Supabase bezpośrednio z przeglądarki dla operacji uprzywilejowanych.\n\n---\n\n## i18n\n\nLocale są skonfigurowane w `web/.config/nuxt/locales.ts`. Wrappery tras pod `src/pages/[lang]/` delegują do stron funkcjonalnych. Domyślne przekierowanie locale kieruje `/` → `/en/home`.\n\nPrefiksy locale do prerenderowania kontroluje `PRERENDER_LOCALES` w `.env`.\n\n---\n\n## System UI\n\n- **Komponenty web Lit** z `nucleify-ui` (`nui-button`, `nui-icon`, …)\n- **Design tokeny** i rejestracja w `portable/nui/`\n- Rejestrowane przez plugin `nucleify-ui.client.ts`\n- Autorstwo przenośne (`*.nuc.tsx`) mapuje `nui-*` na cele emisji\n\n---\n\n## Migracja shelli produktu\n\nWygenerowane aplikacje: `web-next/`, `admin-next/`, `web-solid/`, `admin-solid/`, `web-svelte/`, `admin-svelte/` (lub własna nazwa `--out`):\n\n```bash\nmake web TARGET=next      # konwersja + start dev Next\nmake web TARGET=solid     # konwersja + start dev Solid\nmake web TARGET=svelte    # konwersja + start dev Svelte\nmake admin TARGET=next    # admin → next|solid|svelte analogicznie\nmake admin TARGET=solid\nmake admin TARGET=svelte\n\n# Zewnętrzne drzewo Nuxt-like (z roota monorepo):\npnpm compiler -- convert web --target=next --path=/path/to/app --out=my-next --force\npnpm compiler -- convert web --target=solid --path=/path/to/app --out=my-solid --force\npnpm compiler -- convert web --target=svelte --path=/path/to/app --out=my-svelte --force\n```\n\nRozwijaj w Nuxt (`web/`, `admin/`), konwertuj gdy potrzebujesz innego frameworka. Konwersja Astro `docs/` nie jest jeszcze dostępna. Zobacz [Kompilator](/pl/docs/core-concepts/compiler).\n\n---\n\n## Nadpisania\n\nDostosowania per wdrożenie trafiają do `overrides/web/` lub `overrides/admin/`, odzwierciedlając oryginalną ścieżkę pliku. Zobacz [Nadpisywanie](/pl/docs/core-concepts/overriding).\n\n---\n\n## Komendy dev\n\n| Komenda | Akcja |\n|---------|-------|\n| `make web` | Uruchom serwer dev Nuxt (`web/`) |\n| `make admin` | Uruchom dev admin Nuxt |\n| `pnpm --filter @nucleify/web dev` | Bezpośredni filtr pnpm |\n| `pnpm --filter @nucleify/admin dev` | Bezpośredni filtr admin |\n\nDomyślny port: `3000`. Środowisko ładowane z root `.env` monorepo przez `load-env.ts`.\n\n---\n\n## Powiązana dokumentacja\n\n- [Zmienne środowiskowe](/pl/docs/configuration/environment) - zmienne `.env`\n- [Supabase](/pl/docs/configuration/supabase) - backend i handlery API\n- [Moduły](/pl/docs/core-concepts/modules) - struktura modułów współdzielonych\n",
  "pl/core-concepts/compiler": "# Kompilator\n\nMigracja między frameworkami to **rdzeń** Nucleify - nie doklejka. Pakiet `@nucleify/compiler` prowadzi tę ścieżkę: przenośny kompilator **oparty na IR**, który zamienia `*.nuc.tsx` na Vue SFC, React, Solid, Svelte i Astro (oraz współdzielony CSS), **importuje zmiany z emitów z powrotem** do źródła i **konwertuje całe powłoki produktu Nuxt** (`web/`, `admin/`) - albo zewnętrzne drzewo Nuxt-like - na Next.js, Solid, Svelte lub Astro.\n\nTen zakres wykracza poza samą emisję komponentów: domena, trasy i współdzielone moduły idą razem z shellem. Framework staje się celem builda; produkt zostaje w `shared_modules/`.\n\n**Pokrycie:** Vue · React · Nuxt · Next · Astro · Svelte · Solid. React/Next lub Vue/Nuxt to punkty startowe, nie granica.\n\n---\n\n## Dwa tryby pracy\n\n| Tryb pracy | Co robi | Przykład |\n|------|---------|----------|\n| **Emisja przenośna** | `*.nuc.tsx` → IR → `.vue` + React `.tsx` + Solid `.tsx` + Svelte `.svelte` + `.astro` + `.css` | `pnpm compiler:build` / `make solid` / `make svelte` / `make astro` |\n| **Konwersja produktu** | Aplikacja Nuxt (lub zewnętrzny folder/git) → Next.js, Solid, Svelte lub Astro | `pnpm compiler -- convert web --target=next` |\n\n**Emisja przenośna** służy komponentom prezentacyjnym z round-tripem (`import --from=…`). **Konwersja produktu** generuje `web-next/`, `admin-next/`, `web-solid/`, `admin-solid/`, `web-svelte/`, `admin-svelte/`, `web-astro/` lub `admin-astro/` z drzewa źródeł Vue - te same trasy, współdzielone moduły, inna powłoka frameworka. Konwersja produktu Astro `docs/` **nie** jest jeszcze zaimplementowana.\n\nNie re-eksportuj `*.nuc.tsx` z publicznych barreli (`index.ts`, `modules.ts`, …) - autorstwo zostaje poza entrypointami aplikacji.\n\n---\n\n## Wersja IR\n\nPrzenośny IR jest wersjonowany jako `IR_VERSION` (obecnie **0.1.0**) w `compiler/src/ir/types.ts`.\n\n- Schema, parsery i `compiler/tests/fixtures/ir/*.json` muszą być zsynchronizowane.\n- **Łamiące** zmiany kształtu IR → podnieś wersję i zmigruj fixture’y/testy w **tym samym PR**.\n- Polityka: `compiler/PORTABLE.md` § IR versioning.\n\n---\n\n## Autorstwo przenośne (`*.nuc.tsx`)\n\nTwórz UI niezależne od frameworka z `#nuc-compiler/runtime`:\n\n```tsx\nimport { component, state, handler } from '#nuc-compiler/runtime'\n\nexport default component({\n  name: 'Counter',\n  props: { label: { type: 'string', default: 'Count' } },\n  setup(props) {\n    const count = state(0)\n    const onInc = handler(() => count.set(count.value + 1))\n    return () => (\n      <button type=\"button\" onClick={onInc}>\n        {props.label}: {count.value}\n      </button>\n    )\n  },\n})\n```\n\nUruchomienie `pnpm compiler:build` emituje sąsiednie pliki:\n\n```txt\nportable/components/\n├── Counter.nuc.tsx     # źródło (commitowane)\n├── Counter.vue         # wygenerowany Vue SFC\n├── Counter.tsx         # wygenerowany komponent React\n└── Counter.css         # wyodrębnione style\n```\n\n### Dozwolone w komponentach przenośnych\n\n- Serializowalne props (`string`, `number`, `boolean`, `unknown`)\n- Elementy HTML i custom elements Lit `nui-*`\n- Lokalny stan przez `state`, `derived`, `handler`\n- Zwykły string CSS lub bindy `style={{ … }}`\n- Tylko domyślny slot / `children`\n\n### Zabronione\n\n- API frameworków Vue/React (`defineComponent`, hooki jako sprzężenie hosta)\n- Store'y, routery, i18n, Supabase, Pinia/Zustand w plikach przenośnych\n- Nazwane sloty, portale, dynamiczne komponenty, async setup\n\nPełne reguły: `compiler/PORTABLE.md`.\n\n---\n\n## Referencja CLI\n\n```bash\npnpm compiler:build                              # emituj wszystkie *.nuc.tsx\npnpm compiler:check                              # weryfikuj fingerprinty (exit 1 jeśli emisja nie jest zsynchronizowana)\npnpm compiler:test                               # zestaw testów golden-file\n\npnpm compiler -- import --from=vue path/Foo.vue  # importuj edycje emisji z powrotem do źródła\npnpm compiler -- import --from=react path/Foo.tsx\npnpm compiler -- build --force                   # odrzuć edycje emisji; regeneruj\n\npnpm compiler -- convert web --target=next       # konwersja produktu → web-next/\npnpm compiler -- convert admin --target=next     # konwersja produktu → admin-next/\npnpm compiler -- convert web --target=solid      # konwersja produktu → web-solid/\npnpm compiler -- convert web --target=svelte     # konwersja produktu → web-svelte/\npnpm compiler -- convert web --target=astro      # konwersja produktu → web-astro/\npnpm compiler -- convert web --target=next --path=/path/to/nuxt-app --out=my-next --force\npnpm compiler -- convert web --target=svelte --git=https://github.com/org/app.git --out=fork-svelte --force\npnpm compiler -- scaffold solid                  # tymczasowe demo → solid/demo/\npnpm compiler -- scaffold svelte                 # tymczasowe demo → svelte/demo/\npnpm compiler -- scaffold next                   # tymczasowe demo → next/demo/\npnpm compiler -- build --app=solid               # emisja do solid/demo\npnpm compiler -- build --app=svelte              # emisja do svelte/demo\n```\n\nPomiń kompilator przy bootstrapie / pomiń hooki gdy trzeba:\n\n```bash\nSKIP_COMPILER=1 make run\nHUSKY=0 git commit -m \"…\"   # pomiń suite pre-commit\n```\n\nPre-commit już uruchamia `compiler:check` (i powiązane checki kompilatora) przez Husky.\n\n---\n\n## Cykl: najpierw autorstwo\n\n1. Utwórz lub edytuj `Foo.nuc.tsx`\n2. Uruchom `pnpm compiler:build`\n3. Commituj źródło + wygenerowane sąsiednie pliki\n4. CI uruchamia `pnpm compiler:check`, aby upewnić się, że emisja jest aktualna\n\n## Cykl: najpierw emisja\n\n1. Dopracuj wygenerowany `Foo.vue`, `Foo.tsx` lub `Foo.svelte` bezpośrednio\n2. Zaimportuj zmiany z powrotem: `pnpm compiler -- import --from=vue|react|solid|svelte path/Foo.…`\n3. Źródło prawdy wraca do `Foo.nuc.tsx`\n\nJeśli więcej niż jeden sibling emisji jest niezsynchronizowany, musisz podać `--from=`. Użyj `pnpm compiler -- build --force`, aby odrzucić edycje emisji.\n\n---\n\n## Układ pakietu\n\n```txt\ncompiler/\n├── src/\n│   ├── parse/              # *.nuc.tsx → AST\n│   ├── ir/                 # reprezentacja pośrednia (IR_VERSION)\n│   ├── emit/               # IR → .vue / React .tsx / Solid .tsx / Svelte .svelte / .css\n│   └── sync/               # import zwrotny, konwersja powłok produktu\n├── runtime/                # #nuc-compiler/runtime\n├── templates/              # źródła scaffold dla gitignored demo\n├── tests/                  # testy golden-file\n├── fixtures/\n└── PORTABLE.md             # reguły autorskie\n```\n\nGitignored demo emisji: `{vue,react,nuxt,next,solid,svelte}/demo/` (przez `make vue`, `make next`, `make solid`, `make svelte` itd.).\n\n---\n\n## Konwersja produktu\n\n```bash\nmake web TARGET=next\n# równoważne:\npnpm compiler -- convert web --target=next\ncd web-next && pnpm dev\n\nmake web TARGET=solid\npnpm compiler -- convert web --target=solid\n\nmake web TARGET=svelte\npnpm compiler -- convert web --target=svelte\n\nmake web TARGET=astro\npnpm compiler -- convert web --target=astro\n```\n\nAplikacje produktu Svelte to Vite SPA z runami Svelte 5 (jeszcze nie SvelteKit SSR). Portable emit Svelte używa `$state` / `$derived` / `$props` i eventów DOM jak `onclick`. Konwersja Astro hostuje te same wyspy React pod stronami Astro (`client:load`).\n\nHosty po konwersji ładują **Instrument Sans** i **JetBrains Mono** przez tagi `<link>` w `<head>` (`portable/nui/fonts.ts`). Nie ładuj tych rodzin przez CSS `@import` w zbundlowanym arkuszu - bundlery sklejają CSS, a `@import` w środku pliku jest ignorowany, więc typografia spada na systemowy mono.\n\n### Zewnętrzny folder lub URL git\n\nUżyj tego samego profilu `web|admin` z zewnętrznym drzewem Nuxt-like (wymagane `src/`). Uruchamiaj z **roota monorepo Nucleify**, żeby aliasy `modules` / `portable` działały:\n\n```bash\npnpm compiler -- convert web --target=next --path=/path/to/nuxt-app --out=my-next --force\npnpm compiler -- convert admin --target=solid --git=https://github.com/org/app.git --out=fork-admin-solid --force\npnpm compiler -- convert web --target=svelte --path=/path/to/nuxt-app --out=my-svelte --force\n```\n\nAplikacje po konwersji instalują się przez `pnpm install --ignore-workspace` - wersje w template `package.json` pozostają przypięte; nie wchodzą w graph workspace monorepo.\n\nKonwerter czyta Vue SFC pod `src/`, mapuje strony i composables na hosty React, Solid, Svelte lub Astro i zapisuje output **bez** plików `.vue`. Moduły współdzielone są konsumowane przez barrel frameworka.\n\nTraktuj `web-next/`, `admin-next/`, `web-solid/`, `admin-solid/`, `web-svelte/`, `admin-svelte/`, `web-astro/` i `admin-astro/` (oraz własne katalogi `--out`) jako **generowany output**. Edytuj `web/` lub `admin/`, potem konwertuj ponownie - nie ręcznie łataj drzewa emit.\n\n---\n\n## Alias runtime\n\nNuxt rozwiązuje runtime przez `web/.config/nuxt/structure.ts`:\n\n```typescript\n'#nuc-compiler/runtime': resolve(process.cwd(), '../compiler/runtime/index.ts')\n```\n\nHelpery runtime (`component`, `state`, `derived`, `handler`) to markery compile-time - nie mogą pojawiać się w wyemitowanych bundlach.\n\n---\n\n## Testowanie\n\nTesty kompilatora są w `compiler/tests/` z dedykowaną konfiguracją Vitest (`.config/vitest.compiler.config.ts`). Testy golden porównują output emisji z fixture'ami w `compiler/tests/fixtures/`. Guardy obejmują sync wersji IR oraz skan barreli (bez `*.nuc.tsx` w publicznych entrypointach).\n\n```bash\npnpm compiler:test\npnpm compiler:check\n```\n\nSzybki test ręczny: `make web`, `make vue` / `make solid` / `make svelte` dla demo emisji.\n\nZobacz [Vitest](/pl/docs/tests/vitest) po pełną konfigurację testów.\n\n---\n\n## Powiązana dokumentacja\n\n- [Układ monorepo](/pl/docs/core-concepts/monorepo) - gdzie kompilator pasuje w workspace\n- [Szybki start](/pl/docs/getting-started/quick-start) - zbuduj swój pierwszy komponent przenośny\n- [Web & Admin](/pl/docs/configuration/web) - konfiguracja Nuxt podłączająca alias runtime\n",
  "pl/core-concepts/feature-sliced-design": "# Feature-Sliced Design\n\nFeature-Sliced Design (FSD) organizuje kod **według domeny biznesowej**, a nie według warstw technicznych. W Nucleify każdy pakiet `shared_modules/nuc_*` to jeden slice - narzędzia frontendowe, handlery API, migracje bazy, typy i testy w jednym katalogu.\n\n---\n\n## Dlaczego feature slices?\n\nProjekty warstwowe rozpraszają jedną funkcję po wielu folderach:\n\n```txt\n# ❌ Warstwy first                         # ✅ Feature-sliced (Nucleify)\n\nsrc/                                    shared_modules/\n├── api/                                ├── nuc_api/\n│   ├── colors.ts                       │   ├── supabase/api/gateway_dispatch.ts\n│   └── languages.ts                    │   ├── utils/api_request.ts\n├── types/                              │   └── vitests/\n│   ├── colors.ts                       ├── nuc_colors/\n│   └── languages.ts                    │   ├── supabase/api/handle.ts\n├── styles/                             │   ├── styles/\n│   └── colors.scss                     │   └── vitests/\n└── tests/                              └── nuc_languages/\n    └── colors.test.ts                      └── …\n```\n\nProblemy warstw w skali monorepo:\n\n- Dodanie funkcji dotyka 5+ katalogów\n- Usunięcie funkcji to polowanie na pliki w całym drzewie\n- Równoległa praca na różnych funkcjach powoduje konflikty merge\n- Własność kodu jest niejasna\n\nFSD naprawia to, czyniąc **moduł jednostką zmiany**.\n\n---\n\n## Jak Nucleify stosuje FSD\n\n### Moduły współdzielone = slice domeny\n\nSześć eksportowanych modułów mapuje się na cross-cutting domeny produktu:\n\n| Moduł | Slice |\n|-------|-------|\n| `nuc_api` | Klient HTTP, gateway, formularze auth, stan encji |\n| `nuc_colors` | Theming, tokeny SCSS, API kolorów |\n| `nuc_dark_mode` | Preferencja wyglądu |\n| `nuc_globals` | Breakpointy, wspólne typy, globalny SCSS |\n| `nuc_languages` | Locale, fetch tłumaczeń, plugin i18n |\n| `nuc_stores` | Abstrakcje persystencji klienta |\n\nKażdy slice jest importowany przez `web/` i `admin/` bez duplikacji.\n\n### Aplikacje = warstwy kompozycji\n\nAplikacje produktowe to cienkie powłoki kompozycyjne:\n\n```txt\nweb/src/\n├── pages/[lang]/           # routing + wrappery i18n\n├── pages/home/             # kompozycja landing (sekcje)\n├── composables/            # tylko specyficzne dla app\n├── plugins/                # podpięcie modułów do Nuxt\n└── server/api/             # jedno wejście gateway\n```\n\n**Zasada:** jeśli logika należy do domeny, żyje w `shared_modules/nuc_*`. Jeśli należy do jednej powłoki app (routing, layout, struktura copy marketingowego), zostaje w `web/` lub `admin/`.\n\n---\n\n## Warstwy wewnętrzne modułu\n\nW module foldery mają lekki układ inspirowany FSD:\n\n| Folder | Analog FSD | Zawartość |\n|--------|------------|-----------|\n| `supabase/api/` | Backend / API | Handlery gateway, tabele tras |\n| `utils/` | Shared lib | Composables, hooki, funkcje czyste |\n| `types/` | Shared types | Interfejsy, literały typów |\n| `constants/` | Shared config | Wartości statyczne, definicje pól |\n| `components/` | UI (opcjonalnie) | Widgety wielokrotnego użytku dla domeny |\n| `styles/` | UI tokens | Partiale SCSS |\n| `vitests/` | Testy | Testy jednostkowe obok domeny |\n\nNie ma sztywnego nazewnictwa `entities/features/widgets` - Nucleify preferuje **płaskie moduły domenowe** zamiast głębokiej ceremonii FSD. Liczy się zasada (co-lokacja po funkcji), nie etykiety folderów.\n\n---\n\n## Komunikacja między slice'ami\n\nModuły komunikują się przez **zdefiniowane publiczne eksporty**, nie przez głębokie importy wewnętrzności innego modułu:\n\n```typescript\n// ✅ Publiczny barrel\nimport { apiRequest } from 'modules/nuc_api/utils/api_request'\n\n// ❌ Sięgnij w prywatny helper innego modułu\nimport { internalHelper } from 'modules/nuc_colors/supabase/api/colors_helpers'\n```\n\nDispatch gateway w `nuc_api` to punkt orkiestracji HTTP - moduły rejestrują handlery, ale routing między domenami dzieje się w gateway, nie przez cross-importy w `utils/`.\n\n---\n\n## Portable UI vs logika domeny\n\nKompilator dodaje drugą oś:\n\n| Warstwa | Lokalizacja | Powiązanie z frameworkiem |\n|---------|-------------|---------------------------|\n| Portable UI | `*.nuc.tsx` | Brak - emit Vue + React + Solid + Svelte |\n| Logika domeny | `shared_modules/nuc_*/utils/` | Composables Vue + hooki `.react.ts` |\n| Powłoka app | `web/src/pages/` | Nuxt (kanoniczny) lub Next / Solid / Svelte (skonwertowany) |\n\nTrzymaj store, routery, kontenery i18n i wywołania API **poza** `*.nuc.tsx`. Komponenty portable dostają dane przez props i emitują eventy - slice domeny łączy dane w utils aplikacji lub modułu.\n\n---\n\n## Porównanie z Atomic Design\n\nNucleify używa **Atomic Design** w SCSS (`atoms/`, `molecules/`, `organisms/` pod `nuc_colors/styles/components/`) dla hierarchii wizualnej. FSD i Atomic Design rozwiązują różne problemy:\n\n- **FSD** - gdzie w repo żyje kod funkcji\n- **Atomic Design** - jak komponenty UI się zagnieżdżają wizualnie\n\nWspółistnieją: partial organismu `nuc_colors` nadal jest częścią slice `nuc_colors`.\n\n---\n\n## Dodawanie funkcji po FSD\n\n1. **Zidentyfikuj domenę** - nowy slice czy rozszerzenie istniejącego `nuc_*`?\n2. **Co-lokuj** - handler API, typy, utils, migracje, testy w jednym folderze modułu\n3. **Eksportuj publicznie** - `index.ts` / `index.react.ts`\n4. **Podłącz app** - rejestracja pluginu, handler gateway, kompozycja strony\n5. **Unikaj kopii w app** - jeśli dwie app tego potrzebują, należy do `shared_modules/`\n\n---\n\n## Powiązane docs\n\n- [Moduły](/pl/docs/core-concepts/modules) - referencja modułów\n- [Układ monorepo](/pl/docs/core-concepts/monorepo) - granice app vs shared\n- [Kompilator](/pl/docs/core-concepts/compiler) - warstwa portable UI\n",
  "pl/core-concepts/modules": "# Moduły\n\nNucleify dostarcza **sześć eksportowanych** modułów funkcjonalnych z `@nucleify/shared-modules`. Każdy to samodzielny pakiet domenowy z narzędziami frontendowymi, opcjonalnymi handlerami API Supabase, migracjami, typami i testami - konsumowany przez `web/`, `admin/`, `docs/` i generowane shelle (Next, Solid, Svelte, …), żeby migrować frameworki bez przepisywania biznesu.\n\nNie ma katalogu `modules/` w root. Aplikacje importują przez ścieżki względne lub alias Nuxt `modules` → `shared_modules/`. Flow auth żyje w `nuc_api` (nie ma osobnego `nuc_users` / `nuc_auth`).\n\n---\n\n## Moduły\n\n| Moduł | Domena | Kluczowe ścieżki |\n|-------|--------|------------------|\n| `nuc_api` | Klient API, dispatch gateway, formularze auth, requesty encji, toasty | `supabase/api/gateway_dispatch.ts`, `utils/api_request.ts` |\n| `nuc_colors` | System motywów/kolorów, zmienne SCSS, utils kolorów | `styles/`, `supabase/api/handle.ts` |\n| `nuc_dark_mode` | Preferencja trybu ciemnego (load, persist, apply) | `utils/use_dark_mode.ts`, `nuc_dark_mode.ts` |\n| `nuc_globals` | Media queries, helpery obrazów, globalne style, wspólne typy | `media/`, `styles/`, `nuc_globals.ts` |\n| `nuc_languages` | i18n, komunikaty locale, API tłumaczeń | `plugins/nuc_translations.ts`, `supabase/api/handle.ts` |\n| `nuc_stores` | Helpery Pinia/Zustand, utils cookie/localStorage/session | `pinia/`, `zustand/`, `cookie/` |\n\nTe sześć jest w `shared_modules/index.ts` i w `exports` w `package.json`. Inne foldery pod `shared_modules/` bez publicznego barrela nie są jeszcze częścią wspieranego API.\n\n---\n\n## Anatomia modułu\n\nKażdy katalog `nuc_*` ma spójny układ:\n\n```txt\nshared_modules/nuc_example/\n├── config.json              # name, version, category, enabled\n├── nuc_example.ts           # plugin Vue (registerNucExample)\n├── index.ts                 # barrel export Vue\n├── index.react.ts           # barrel export React (gdy potrzebny)\n├── _index.scss              # opcjonalne globalne style modułu\n├── README.md\n├── constants/\n├── types/\n│   ├── interfaces.ts\n│   ├── interfaces.react.ts  # gdy typy React się różnią\n│   └── variables.ts\n├── utils/                   # composables, hooki, funkcje czyste\n├── components/              # opcjonalne UI wielokrotnego użytku\n├── supabase/\n│   ├── api/\n│   │   ├── handle.ts        # wejście gateway (handleExampleApi)\n│   │   └── *_handlers.ts    # tabele tras\n│   ├── migrations/\n│   ├── factories/\n│   └── seeders/\n└── vitests/\n```\n\n---\n\n## Rejestracja w Nuxt\n\n`web/src/plugins/modules.ts` rejestruje cztery moduły przy starcie aplikacji:\n\n```typescript\nimport { registerNucColors } from '../../../shared_modules/nuc_colors/nuc_colors'\nimport { registerNucDarkMode } from '../../../shared_modules/nuc_dark_mode/nuc_dark_mode'\nimport { registerNucGlobals } from '../../../shared_modules/nuc_globals/nuc_globals'\nimport { registerNucLanguages } from '../../../shared_modules/nuc_languages/nuc_languages'\n\nexport default defineNuxtPlugin({\n  name: 'modules-registration',\n  enforce: 'pre',\n  setup(nuxtApp) {\n    registerNucGlobals(nuxtApp.vueApp)\n    registerNucColors(nuxtApp.vueApp)\n    registerNucDarkMode(nuxtApp.vueApp)\n    registerNucLanguages(nuxtApp)\n  },\n})\n```\n\n`nuc_api` i `nuc_stores` są importowane na żądanie - bez globalnego pluginu.\n\nTłumaczenia ładują się też przez ścieżkę pluginu Nuxt w konfiguracji:\n\n```typescript\n// web/.config/nuxt/structure.ts\nplugins: [\n  resolve(process.cwd(), '../shared_modules/nuc_languages/plugins/nuc_translations.ts'),\n],\n```\n\n---\n\n## Zasady importów\n\n**Wewnątrz modułu** - tylko importy względne. Nigdy z `web/`, `admin/` ani `docs/`.\n\n**Z aplikacji** - alias lub ścieżka względna:\n\n```typescript\n// przez alias (Nuxt)\nimport { useDarkMode } from 'modules/nuc_dark_mode/utils/use_dark_mode'\n\n// jawna względna (też OK)\nimport { apiRequest } from '../../../shared_modules/nuc_api/utils/api_request'\n```\n\n**Publiczne API** - eksport przez `index.ts` i root barrel `shared_modules/index.ts`. Nie importuj `from 'nucleify'` w modułach (zależność cykliczna).\n\n---\n\n## Integracja z bramką API\n\nHandlery modułów eksportują async `handle*Api(ctx)`. Zarejestruj w rejestrze gateway:\n\n```typescript\n// shared_modules/nuc_api/supabase/api/gateway_dispatch.ts\nexport const supabaseApiGatewayHandlers = [\n  handleColorsApi,\n  handleLanguagesApi,\n] as const\n```\n\nPunkt wejścia Nitro:\n\n```txt\nweb/src/server/api/[...slug].ts\n  → parseApiSlug()\n  → dispatchSupabaseApiGateway(ctx)\n  → pierwszy handler gdzie result.handled === true\n```\n\n### Wzorzec handlera\n\n```typescript\nimport { apiMethodNotAllowed, apiNotHandled, withGatewayUser } from 'nuc_api'\nimport type { ApiContext, ApiHandlerResult } from 'nuc_server'\n\nexport async function handleExampleApi(ctx: ApiContext): Promise<ApiHandlerResult> {\n  if (ctx.segments[0] !== 'example') return apiNotHandled()\n  return withGatewayUser(ctx, async (gatewayCtx, userId) => {\n    // dispatch tablicy tras …\n    return apiMethodNotAllowed()\n  })\n}\n```\n\nKod klienta woła `/api/example/...` przez helpery request `nuc_api` - nie service keys Supabase w przeglądarce.\n\n---\n\n## Supabase per moduł\n\nKażdy moduł może mieć własne artefakty SQL:\n\n| Katalog | Cel |\n|---------|-----|\n| `supabase/migrations/` | Zmiany schematu |\n| `supabase/factories/` | SQL factory test/dev |\n| `supabase/seeders/` | Dane seed |\n\nLokalnie:\n\n```bash\npnpm supabase:migrations:apply:local\npnpm supabase:seeders:apply:local\n# lub razem:\npnpm supabase:setup:local\n```\n\nSkrypty scalają SQL modułów przez `.config/bash/merge-module-supabase-sql.sh`.\n\n---\n\n## Warianty React\n\nModuły wspierające konwersję produktu eksponują odpowiedniki `.react.ts`:\n\n- `index.react.ts` - barrel React\n- `utils/use_*.react.ts` - hooki React odzwierciedlające composables Vue\n- `types/interfaces.react.ts` - typy React gdy potrzebne\n\nKompilator i convert produktu używają ich przy emisji powłok Next, Solid i Svelte.\n\n---\n\n## Tworzenie nowego modułu\n\n1. Skopiuj strukturę z istniejącego modułu `nuc_*`\n2. Dodaj metadane `config.json`\n3. Zaimplementuj `nuc_example.ts` z `registerNucExample`\n4. Eksportuj publiczne API z `index.ts`\n5. Dodaj do `shared_modules/index.ts` jeśli potrzebne globalnie\n6. Zarejestruj plugin w `web/src/plugins/modules.ts` jeśli wymaga setupu app-wide\n7. Dodaj handler gateway w `gateway_dispatch.ts` jeśli eksponuje trasy API\n8. Dodaj `vitests/` i uruchom `pnpm test:shared`\n\nZob. [Feature-Sliced Design](/pl/docs/core-concepts/feature-sliced-design) dla uzasadnienia architektonicznego.\n\n---\n\n## Powiązane docs\n\n- [Feature-Sliced Design](/pl/docs/core-concepts/feature-sliced-design)\n- [Supabase](/pl/docs/configuration/supabase)\n- [Nadpisywanie](/pl/docs/core-concepts/overriding) - patch modułów bez edycji upstream\n",
  "pl/core-concepts/monorepo": "# Układ monorepo\n\nNucleify to workspace pnpm zbudowany pod **migrację między frameworkami** jako pierwszorzędną zdolność produktu. Każdy pakiet ma wyraźną granicę, współdzielone narzędzia są w `.config/`, a aplikacje produktowe (`web/`, `admin/`, `docs/`) konsumują logikę funkcjonalną z `shared_modules/` - nigdy odwrotnie. Kompilator prowadzi emit, import i konwersję produktu; generowane shelle (Next, Solid, Svelte, Astro, …) to output, nie drugie źródło prawdy.\n\n---\n\n## Mapa najwyższego poziomu\n\n```txt\nnucleify/\n├── web/                    # @nucleify/web - landing Nuxt 4 (kanoniczny)\n├── admin/                  # @nucleify/admin - panel admin Nuxt 4\n├── docs/                   # @nucleify/docs - dokumentacja Astro 5\n├── compiler/               # @nucleify/compiler - przenośny kompilator UI IR\n├── shared_modules/         # @nucleify/shared-modules - sześć eksportowanych modułów nuc_*\n├── portable/nui/           # design tokeny, rejestracja Lit nui-*\n├── overrides/              # overrides/{web,admin,docs,shared_modules}/\n├── supabase/               # konfiguracja DB, migracje, edge functions\n├── .config/                # Biome, Vitest, skrypty bash, helpery CI\n├── .cursor/                # agenci Cursor i reguły monorepo\n├── Makefile                # make run, make web, make admin, …\n└── package.json            # skrypty root workspace\n```\n\n---\n\n## Aplikacje produktowe\n\n### `web/` - `@nucleify/web`\n\nKanoniczna aplikacja landingowa Nuxt 4.\n\n```txt\nweb/\n├── nuxt.config.ts          # składa rozdzieloną konfigurację z .config/nuxt/\n├── .config/\n│   ├── .env.example        # szablon kopiowany do root .env przez make run\n│   └── nuxt/               # app, dev, i18n, nitro, runtime, structure, vite, …\n└── src/\n    ├── pages/\n    │   ├── [lang]/         # cienkie wrappery routingu (i18n)\n    │   └── home/           # sekcje landingowe\n    ├── plugins/\n    │   ├── modules.ts      # registerNuc* dla modułów współdzielonych\n    │   └── nucleify-ui.client.ts\n    ├── composables/\n    ├── layouts/\n    ├── assets/             # wpis SCSS (importuje style shared_modules)\n    ├── nucleify.ts         # re-eksportuje powierzchnię współdzieloną + helpery app\n    └── server/\n        └── api/\n            └── [...slug].ts  # catch-all Nitro → gateway_dispatch\n```\n\nKluczowe fakty:\n\n- `srcDir` to `src` (nie `nuxt/`)\n- Alias `modules` → `../shared_modules`\n- Alias `#nuc-compiler/runtime` → `../compiler/runtime/index.ts`\n\n### `admin/` - `@nucleify/admin`\n\nTe same konwencje Nuxt co `web/`, skupione na stronach dashboardu pod `admin/src/pages/`.\n\n---\n\n## `docs/` - `@nucleify/docs`\n\nStatyczna strona dokumentacji Astro 5.\n\n```txt\ndocs/\n├── content/\n│   ├── en/{category}/{slug}.md\n│   └── pl/{category}/{slug}.md\n├── public/                 # favicon, logo\n└── src/\n    ├── pages/\n    │   └── [lang]/docs/[category]/[slug].astro\n    ├── layouts/DocsLayout.astro\n    ├── components/         # DocsSidebar, DocsToc, LangSwitcher\n    └── lib/                # ścieżki doc, renderer markdown, nawigacja\n```\n\nKategorie są zdefiniowane w `docs/src/lib/constants/docs.ts`. Host produkcyjny: [docs.nucleify.io](https://docs.nucleify.io). Trasy mają postać `/pl/docs/{category}/{slug}`.\n\n---\n\n## `compiler/` - `@nucleify/compiler`\n\nPrzenośny kompilator UI oparty na IR. Samodzielny - nie importuje z `web/`, `admin/` ani `docs/`.\n\n```txt\ncompiler/\n├── src/\n│   ├── parse/              # *.nuc.tsx → AST\n│   ├── ir/                 # reprezentacja pośrednia\n│   ├── emit/               # IR → .vue / React .tsx / Solid .tsx / Svelte .svelte / .css\n│   └── sync/               # import zwrotny z emisji, konwersja powłok produktu\n├── runtime/                # #nuc-compiler/runtime (component, state, handler, …)\n├── templates/              # źródła scaffold dla gitignored demo\n├── tests/\n├── fixtures/\n└── PORTABLE.md             # reguły autorskie dla *.nuc.tsx\n```\n\nGitignored demo emisji: `{vue,react,nuxt,next,solid,svelte}/demo/` (przez `make vue`, `make next`, `make solid`, `make svelte` itd.).\n\n---\n\n## `shared_modules/` - `@nucleify/shared-modules`\n\nSześć eksportowanych modułów funkcjonalnych (nie submoduły git):\n\n| Moduł | Ścieżka |\n|-------|---------|\n| Klient API i bramka | `shared_modules/nuc_api/` |\n| Kolory i motyw | `shared_modules/nuc_colors/` |\n| Tryb ciemny | `shared_modules/nuc_dark_mode/` |\n| Globalne i media | `shared_modules/nuc_globals/` |\n| i18n i tłumaczenia | `shared_modules/nuc_languages/` |\n| Storage i helpery stanu | `shared_modules/nuc_stores/` |\n\nBarrel export: `shared_modules/index.ts` + `exports` w package. Każdy moduł jest samodzielny z opcjonalnym `supabase/`, `utils/`, `types/` i `vitests/`. Auth żyje w `nuc_api`.\n\n---\n\n## `portable/nui/`\n\nDesign tokeny i rejestracja custom elements Lit dla `nucleify-ui` (tagi `nui-*`). Referencjonowany przez Nuxt przez alias `portable/nui` w `web/.config/nuxt/structure.ts`.\n\n---\n\n## `overrides/`\n\nWarstwy nadpisań per pakiet. Odwzoruj dowolną ścieżkę pliku:\n\n```txt\noverrides/\n├── web/src/…\n├── admin/src/…\n├── docs/src/…\n└── shared_modules/nuc_*/…\n```\n\nNadpisania zastępują oryginalny plik w całości - bez merge. Tylko Nuxt; nie jest częścią importu kompilatora. Zobacz [Nadpisywanie](/pl/docs/core-concepts/overriding).\n\n---\n\n## `supabase/`\n\nKonfiguracja projektu Supabase na poziomie monorepo. SQL modułów jest w każdym `shared_modules/nuc_*/supabase/` i scalany przez `.config/bash/merge-module-supabase-sql.sh`.\n\n---\n\n## `.config/`\n\nWspółdzielone narzędzia monorepo:\n\n- Biome (`pnpm check`, `pnpm write`)\n- Root config Vitest (`vitest.config.ts`) - projekty `web` i `shared`\n- Vitest kompilatora (`.config/vitest.compiler.config.ts`)\n- Skrypty bash: merge/apply Supabase, hook checks, prepare submodule\n- Hooki Husky delegują do `.config/bash/hook-checks.sh`\n\n---\n\n## Kierunek zależności\n\n```txt\nweb / admin / docs\n         ↓ importuje\n    shared_modules / portable / compiler/runtime\n         ↓\n    supabase (przez handlery API)\n```\n\n**Reguły:**\n\n- Aplikacje importują z `shared_modules/`; moduły nigdy nie importują z aplikacji\n- Logika kompilatora pozostaje w `compiler/src/`\n- Nadpisania przesłaniają pliki app lub modułu w czasie buildu (tylko Nuxt)\n\n---\n\n## Referencja Makefile\n\n| Komenda | Akcja |\n|---------|-------|\n| `make run` | `.env` + setup + kompilator |\n| `make setup` | install, husky, prepare, sync-rules, kompilator |\n| `make web` | dev produktu Nuxt (`TARGET=nuxt` domyślnie) |\n| `make web TARGET=next` | konwersja + aplikacja Next (`web-next/`) |\n| `make web TARGET=solid` | konwersja + aplikacja Solid (`web-solid/`) |\n| `make web TARGET=svelte` | konwersja + aplikacja Svelte (`web-svelte/`) |\n| `make web TARGET=astro` | konwersja + host Astro + wyspy React (`web-astro/`) |\n| `make admin` / `make admin TARGET=next|solid|svelte|astro` | odpowiedniki admin |\n| `make docs` | witryna docs Astro (`docs/`) |\n| `make compiler` | check + build |\n| `make vue` / `make react` / `make nuxt` / `make next` / `make solid` / `make svelte` / `make astro` | gitignored demo portable (`{framework}/demo`) |\n\n---\n\n## Powiązana dokumentacja\n\n- [Moduły](/pl/docs/core-concepts/modules) - wewnętrzna struktura modułu\n- [Kompilator](/pl/docs/core-concepts/compiler) - kanoniczny Nuxt vs konwersja produktu\n- [Web & Admin](/pl/docs/configuration/web) - szczegóły konfiguracji Nuxt\n",
  "pl/core-concepts/overriding": "# Nadpisywanie\n\nNadpisania pozwalają zastąpić dowolny plik w `web/`, `admin/`, `docs/` lub `shared_modules/` bez edycji oryginału. Przy buildzie Nuxt rozwiązuje ścieżkę override zamiast źródła.\n\nNadpisania są **tylko dla Nuxt**. Nie dotyczą cyklu import kompilatora, produkcyjnych buildów Astro poza Nuxt ani generowanych shelli (`web-next/`, `web-solid/`, `web-svelte/`, …) - chyba że skonfigurujesz to osobno.\n\n---\n\n## Jak to działa\n\n1. Odzwierciedl oryginalną ścieżkę pliku pod `overrides/{package}/`\n2. Nuxt dev/build skanuje `overrides/` przy starcie\n3. Gdy jest dopasowanie, override **całkowicie zastępuje** oryginał - bez merge, bez częściowego patcha\n\n```txt\nOryginał:  web/src/composables/useAuth.ts\nOverride:  overrides/web/src/composables/useAuth.ts\n```\n\n---\n\n## Układ katalogów\n\n```txt\noverrides/\n├── web/\n│   └── src/…               # odzwierciedla web/src/…\n├── admin/\n│   └── src/…\n├── docs/\n│   └── src/…\n└── shared_modules/\n    └── nuc_colors/…\n```\n\nKażdy podkatalog ma `README.md` z przykładami dla pakietu.\n\n---\n\n## Przykłady\n\n### Nadpisanie sekcji landing\n\n```txt\nOryginał:  web/src/pages/home/index.vue\nOverride:  overrides/web/src/pages/home/index.vue\n```\n\nGdy forkujesz branding lub layout dla white-label, zachowując drzewo upstream `web/`.\n\n### Nadpisanie composable\n\n```txt\nOryginał:  web/src/composables/useAuth.ts\nOverride:  overrides/web/src/composables/useAuth.ts\n```\n\nGdy flow auth różni się per wdrożenie, reszta app zostaje ta sama.\n\n### Nadpisanie handlera API modułu\n\n```txt\nOryginał:  shared_modules/nuc_colors/supabase/api/handle.ts\nOverride:  overrides/shared_modules/nuc_colors/supabase/api/handle.ts\n```\n\nGdy backend musi się różnić bez forkowania całego modułu `nuc_colors`.\n\n### Nadpisanie layoutu docs\n\n```txt\nOryginał:  docs/src/layouts/DocsLayout.astro\nOverride:  overrides/docs/src/layouts/DocsLayout.astro\n```\n\nUwaga: rozwiązywanie override w Astro zależy od konfiguracji builda docs - zweryfikuj w dev po dodaniu pliku.\n\n---\n\n## Debugowanie nadpisań\n\nGdy zachowanie różni się od tego, co widzisz w źródle:\n\n1. Sprawdź `overrides/{package}/` pod kątem ścieżki pasującej do czytanego pliku\n2. Tymczasowo przenieś lub usuń override, żeby potwierdzić, że to aktywna wersja\n3. Pamiętaj: override zasłania **całe pliki** - jedna linia zmiany nadal wymaga skopiowania pełnego pliku\n\n---\n\n## Czym nadpisania nie są\n\n| Potrzeba | Override? | Alternatywa |\n|----------|-----------|-------------|\n| Emit komponentu portable | Nie | Edytuj `*.nuc.tsx`, uruchom `pnpm compiler:build` |\n| Import emit z powrotem do źródła autorstwa | Nie | `pnpm compiler -- import --from=vue\\|react\\|solid\\|svelte` |\n| Generowana powłoka (Next / Solid / Svelte) | Nie* | Edytuj `web/`, konwertuj przez `make web TARGET=next\\|solid\\|svelte` |\n| Konfiguracja per środowisko | Nie | Root `.env`, `web/.config/nuxt/runtime.ts` |\n| Schemat bazy | Nie | Migracje modułów w `shared_modules/nuc_*/supabase/` |\n\n\\*Chyba że dodasz osobne narzędzie override dla wygenerowanych shelli - poza domyślnym skanerem Nuxt.\n\n---\n\n## Dobre praktyki\n\n1. **Mało nadpisań** - wiele override utrudnia upgrade\n2. **Dokumentuj dlaczego** - komentarz na górze pliku override z powodem forka\n3. **Preferuj moduły** - jeśli wiele app potrzebuje zmiany, rozszerz `shared_modules/`\n4. **Synchronizuj z upstream** - przy merge upstream Nucleify diffuj override z oryginałami\n5. **Bez sekretów** - override to pliki źródłowe; klucze w `.env`\n\n---\n\n## Powiązane docs\n\n- [Układ monorepo](/pl/docs/core-concepts/monorepo) - `overrides/` w kontekście\n- [Moduły](/pl/docs/core-concepts/modules) - kiedy rozszerzyć moduł vs nadpisać\n- [Kompilator](/pl/docs/core-concepts/compiler) - override poza cyklem import\n",
  "pl/getting-started/installation": "# Instalacja\n\nUruchom monorepo Nucleify na swoim komputerze.\n\n---\n\n## Wymagania\n\n| Narzędzie | Wersja | Uwagi |\n|-----------|--------|-------|\n| **Node.js** | ≥ 20 | Wymagane przez root `package.json` |\n| **pnpm** | 10.x | Menedżer workspace (`packageManager: pnpm@10.33.0`) |\n| **Git** | dowolna nowsza | Klonowanie repozytorium |\n| **Make** | dowolny | Skróty workspace z root `Makefile` |\n| **Supabase CLI** | opcjonalnie | Tylko przy lokalnym stacku Supabase |\n\n---\n\n## Klonowanie repozytorium\n\n```bash\ngit clone https://github.com/Nucleify/Nucleify.git\ncd Nucleify\n```\n\n---\n\n## Pierwsza konfiguracja\n\nZ katalogu głównego repozytorium uruchom:\n\n```bash\nmake run\n```\n\nTa komenda:\n\n1. **Tworzy `.env`** - kopiuje `web/.config/.env.example` do root repozytorium, jeśli `.env` nie istnieje\n2. **Instaluje zależności** - `pnpm install` we wszystkich pakietach workspace\n3. **Przygotowuje Husky** - hooki git do lintu i testów\n4. **Przygotowuje web** - `pnpm --filter @nucleify/web prepare`\n5. **Synchronizuje reguły Cursor** - `pnpm sync-rules`\n6. **Buduje kompilator** - `pnpm compiler:check` + `pnpm compiler:build` (emituje sąsiednie pliki Vue / React / Solid / Svelte; pomiń przez `SKIP_COMPILER=1 make run`)\n\nJeśli masz już plik `.env`, użyj `make setup` - te same kroki bez nadpisywania konfiguracji środowiska.\n\n---\n\n## Zmienne środowiskowe\n\nPo `make run` edytuj root `.env` i uzupełnij minimum:\n\n```env\nSUPABASE_URL=https://your-project.supabase.co\nSUPABASE_KEY=your-anon-key\nSUPABASE_SERVICE_ROLE_KEY=your-service-role-key\n```\n\nBramka API w `web/src/server/api/[...slug].ts` wymaga `SUPABASE_URL` i `SUPABASE_SERVICE_ROLE_KEY` dla tras modułów. Bez nich endpointy smoke (`/api`, `/api/test`) nadal działają, ale handlery domenowe zwracają 503.\n\nZobacz [Zmienne środowiskowe](/pl/docs/configuration/environment) po pełną referencję.\n\n---\n\n## Weryfikacja instalacji\n\nUruchom aplikację landingową:\n\n```bash\nmake web\n```\n\nOtwórz [http://localhost:3000](http://localhost:3000). Domyślne przekierowanie locale kieruje na `/en/home`.\n\nInne pakiety:\n\n```bash\nmake admin    # panel admin (Nuxt)\nmake docs     # strona dokumentacji (Astro)\nmake compiler # tylko check + build kompilatora\n```\n\n---\n\n## Pakiety workspace\n\nMonorepo używa workspace pnpm. Filtruj komendy, gdy potrzebujesz konkretnego pakietu:\n\n```bash\npnpm --filter @nucleify/web dev\npnpm --filter @nucleify/admin dev\npnpm --filter @nucleify/docs dev\n```\n\nSkróty root odpowiadają Makefile:\n\n| Skrypt | Pakiet |\n|--------|--------|\n| `pnpm dev` | `@nucleify/web` |\n| `pnpm admin` | `@nucleify/admin` |\n| `pnpm docs` | `@nucleify/docs` |\n| `pnpm compiler` | CLI `@nucleify/compiler` |\n\n---\n\n## Opcjonalnie: lokalny Supabase\n\nPrzy rozwoju na lokalnej instancji Supabase:\n\n```bash\n# Zastosuj scalone migracje modułów, fabryki i seedery\npnpm supabase:setup:local\n```\n\nSQL ze wszystkich modułów jest scalany przez `.config/bash/merge-module-supabase-sql.sh`. Szczegóły: [Supabase](/pl/docs/configuration/supabase).\n\n---\n\n## Rozwiązywanie problemów\n\n### Kompilator nie przechodzi przy setupie\n\nPomiń codegen kompilatora podczas bootstrapu:\n\n```bash\nSKIP_COMPILER=1 make run\nmake compiler   # uruchom ręcznie, gdy deps są stabilne\n```\n\n### Port już zajęty\n\nNuxt domyślnie używa portu 3000. Ustaw inny port w shellu lub zatrzymaj konfliktujący proces.\n\n### Błędy brakującego Supabase w trasach API\n\nUpewnij się, że `.env` jest w **root repozytorium** (nie w `web/`). Nuxt ładuje go przez `web/.config/nuxt/load-env.ts`, który czyta root `.env` monorepo.\n\n### Niezgodność wersji pnpm\n\nZainstaluj wersję przypiętą w `package.json`:\n\n```bash\ncorepack enable\ncorepack prepare pnpm@10.33.0 --activate\n```\n\n---\n\n## Następne kroki\n\n- [Szybki start](/pl/docs/getting-started/quick-start) - przegląd repozytorium i typowe workflow\n- [Konfiguracja Web & Admin](/pl/docs/configuration/web) - rozdzielona konfiguracja Nuxt i aliasy\n- [Układ monorepo](/pl/docs/core-concepts/monorepo) - referencja katalogów\n",
  "pl/getting-started/introduction": "# Wprowadzenie\n\n## Zbuduj raz. Przenieś na dowolny framework.\n\n**Nucleify** to modularne monorepo full-stack zbudowane wokół **migracji między frameworkami**. Trzymaj produkt we współdzielonych modułach, rozwijaj codziennie w Nuxt (`web/`) i przenieś web lub admin na inny shell, gdy rekrutacja, kupujący albo klient tego wymagają - bez przepisywania biznesu. Kompilator oparty na IR prowadzi ten ruch: emit przenośny, konwersja produktu i import z powrotem z emitu.\n\n**Shelle:** Vue · React · Nuxt · Next · Astro · Svelte · Solid - to nie jest produkt „tylko React/Next” ani „tylko Vue/Nuxt”.\n\n> Zostaw produkt. Migruj shell.\n\n---\n\n## Czym jest Nucleify?\n\nNucleify to **workspace pnpm**, który łączy wszystko, czego potrzebuje nowoczesny produkt:\n\n| Pakiet | Ścieżka | Rola |\n|--------|---------|------|\n| `@nucleify/web` | `web/` | Aplikacja landingowa Nuxt 4 (kanoniczna) |\n| `@nucleify/admin` | `admin/` | Panel administracyjny Nuxt 4 |\n| `@nucleify/docs` | `docs/` | Strona dokumentacji Astro 5 |\n| `@nucleify/compiler` | `compiler/` | Przenośny kompilator UI oparty na IR |\n| `@nucleify/shared-modules` | `shared_modules/` | Sześć eksportowanych modułów funkcjonalnych |\n\nKatalogi wspierające:\n\n- `portable/nui/` - design tokeny i rejestracja Lit `nui-*`\n- `overrides/` - nadpisania plików per pakiet (`overrides/{web,admin,docs,shared_modules}/`)\n- `supabase/` - konfiguracja DB, migracje, edge functions\n- `.config/` - Biome, Vitest, skrypty bash\n\n---\n\n## Kanoniczny Nuxt i wygenerowane shelle\n\n| Rodzaj | Stack | Komenda | Wynik |\n|------|-------|---------|-------|\n| **Kanoniczny** (domyślny) | Nuxt 4 + Vue 3.5 | `make web` | `web/` |\n| **Skonwertowany** (generowany) | Next / Solid / Svelte / Astro | `make web TARGET=next` · `solid` · `svelte` · `astro` | wygenerowane drzewo (zob. [Kompilator](/pl/docs/core-concepts/compiler)) |\n| **Demo emit** | Vue · React · Nuxt · Next · Solid · Svelte | `make vue` · `react` · `nuxt` · `next` · `solid` · `svelte` | `{framework}/demo` |\n\n**Kanoniczny Nuxt** to codzienna praca - strony, composables i współdzielone moduły w Vue. **Konwersja produktu** i demo emisji rozprowadzają to samo jądro na kolejne frameworki (Next, Solid, Svelte, hosty Astro oraz demo React/Vue/Nuxt). Witryna docs zostaje w śledzonym `docs/`; `web-astro/` to emit produktu, nie ta witryna.\n\nWszystkie ścieżki współdzielą `shared_modules/`, Supabase i design tokeny. Nie utrzymujesz siedmiu niezależnych baz kodu.\n\n---\n\n## Kompilator\n\nKompilator (`@nucleify/compiler`) to rdzeń migracji. Nie ogranicza się do snipetów prezentacyjnych - działa na dwóch poziomach:\n\n### 1. Przenośne komponenty (`*.nuc.tsx`)\n\nTwórz UI niezależne od frameworka z `#nuc-compiler/runtime`. Kompilator emituje sąsiednie pliki `.vue`, React `.tsx`, Solid `.tsx`, Svelte `.svelte` oraz `.css`:\n\n```tsx\nimport { component, state, handler } from '#nuc-compiler/runtime'\n\nexport default component({\n  name: 'Counter',\n  props: { label: { type: 'string', default: 'Count' } },\n  setup(props) {\n    const count = state(0)\n    const onInc = handler(() => count.set(count.value + 1))\n    return () => (\n      <button type=\"button\" onClick={onInc}>\n        {props.label}: {count.value}\n      </button>\n    )\n  },\n})\n```\n\nZobacz [Kompilator](/pl/docs/core-concepts/compiler) i `compiler/PORTABLE.md` po pełne reguły autorskie.\n\n### 2. Konwersja produktu\n\nKonwertuj całą aplikację Nuxt na Next, Solid, Svelte lub Astro:\n\n```bash\nmake web TARGET=next    # → web-next/\nmake web TARGET=solid   # → web-solid/\nmake web TARGET=svelte  # → web-svelte/\nmake web TARGET=astro   # → web-astro/\n```\n\nTe same trasy, współdzielone moduły, inny host frameworka. Output generuje kompilator - nie wchodzi w kanoniczny układ monorepo.\n\n---\n\n## Współdzielone moduły\n\nSześć eksportowanych modułów funkcjonalnych w `shared_modules/`:\n\n| Moduł | Domena |\n|-------|--------|\n| `nuc_api` | Klient API, dispatch bramki, formularze auth, żądania encji |\n| `nuc_colors` | System motywów/kolorów, zmienne SCSS |\n| `nuc_dark_mode` | Preferencja trybu ciemnego |\n| `nuc_globals` | Media queries, style globalne, współdzielone typy |\n| `nuc_languages` | i18n, komunikaty locale, API tłumaczeń |\n| `nuc_stores` | Pomocniki Pinia/Zustand, utils cookie/localStorage |\n\nAplikacje importują moduły bezpośrednio lub przez alias `modules` (skonfigurowany w `web/.config/nuxt/structure.ts`). Rejestracja dla aplikacji web odbywa się w `web/src/plugins/modules.ts`.\n\nWięcej: [Moduły](/pl/docs/core-concepts/modules) · [Feature-Sliced Design](/pl/docs/core-concepts/feature-sliced-design)\n\n---\n\n## Bramka API\n\nCały ruch API serwera przechodzi przez jeden catch-all Nitro:\n\n```\nweb/src/server/api/[...slug].ts\n  → dispatchSupabaseApiGateway()\n  → shared_modules/nuc_*/supabase/api/handle.ts\n```\n\nHandlery modułów rejestrują się w `shared_modules/nuc_api/supabase/api/gateway_dispatch.ts`. Kod klienta wywołuje `/api/...` - nigdy Supabase bezpośrednio z przeglądarki dla operacji uprzywilejowanych.\n\n---\n\n## System designu\n\nPrymitywy UI to **komponenty web Lit** z `nucleify-ui` (`nui-button`, `nui-icon`, …). Design tokeny i rejestracja są w `portable/nui/`. Każdy shell konsumuje te same custom elements; kompilator mapuje tagi `nui-*` w `*.nuc.tsx` na cele emisji (Vue, React, Solid, Svelte i pokrewne shelle).\n\n---\n\n## Układ monorepo\n\n```txt\nnucleify/\n├── web/                    # @nucleify/web - landing Nuxt 4 (kanoniczny)\n│   ├── nuxt.config.ts\n│   ├── .config/nuxt/       # rozdzielona konfiguracja Nuxt\n│   └── src/\n│       ├── pages/          # strony Vue (np. home/sections/)\n│       ├── plugins/        # modules.ts, nucleify-ui.client.ts\n│       ├── composables/\n│       ├── layouts/\n│       └── server/api/     # bramka API Nitro [...slug].ts\n├── admin/                  # @nucleify/admin - admin Nuxt 4\n├── docs/                   # @nucleify/docs - dokumentacja Astro 5\n├── compiler/               # @nucleify/compiler - przenośny kompilator UI IR\n├── shared_modules/         # sześć eksportowanych modułów nuc_*\n├── portable/nui/           # design tokeny, rejestracja Lit nui-*\n├── overrides/              # overrides/{web,admin,docs,shared_modules}/\n├── supabase/\n├── .config/\n├── Makefile\n└── package.json\n```\n\nPełny opis: [Układ monorepo](/pl/docs/core-concepts/monorepo)\n\n---\n\n## Szybkie komendy\n\n| Komenda | Co robi |\n|---------|---------|\n| `make run` | Tworzy `.env`, instaluje deps, husky, sync rules, buduje kompilator |\n| `make web` | Uruchamia serwer dev Nuxt (`web/`) |\n| `make web TARGET=next` | Konwertuje aplikację Vue do Next, uruchamia dev |\n| `make web TARGET=solid` | Konwertuje aplikację Vue do Solid, uruchamia dev |\n| `make web TARGET=svelte` | Konwertuje aplikację Vue do Svelte, uruchamia dev |\n| `make web TARGET=astro` | Konwertuje aplikację Vue do Astro + wyspy React |\n| `make vue` / `react` / `nuxt` / `next` / `solid` / `svelte` / `astro` | Demo emit portable (`{framework}/demo`) |\n| `make admin` | Uruchamia dev admin Nuxt |\n| `make docs` | Uruchamia dev dokumentacji Astro |\n| `make compiler` | Uruchamia `pnpm compiler:check` + `pnpm compiler:build` |\n\nOdpowiedniki pnpm: `pnpm dev`, `pnpm admin`, `pnpm docs`.\n\n---\n\n## Następne kroki\n\n1. [Instalacja](/pl/docs/getting-started/installation) - wymagania i pierwsza konfiguracja\n2. [Szybki start](/pl/docs/getting-started/quick-start) - uruchom landing w kilka minut\n3. [Układ monorepo](/pl/docs/core-concepts/monorepo) - gdzie co się znajduje\n4. [Zmienne środowiskowe](/pl/docs/configuration/environment) - konfiguracja Supabase i zmiennych aplikacji\n",
  "pl/getting-started/quick-start": "# Szybki start\n\nUruchom Nucleify, poznaj repozytorium i wprowadź pierwszą zmianę w mniej niż dziesięć minut.\n\n---\n\n## 1. Bootstrap\n\n```bash\ngit clone https://github.com/Nucleify/Nucleify.git\ncd Nucleify\nmake run\n```\n\nUzupełnij wartości `SUPABASE_*` w root `.env`, jeśli planujesz wywoływać trasy API modułów.\n\n---\n\n## 2. Uruchom aplikację landingową\n\n```bash\nmake web\n```\n\nOtwórz [http://localhost:3000/en/home](http://localhost:3000/en/home).\n\nŹródło landingu jest w `web/src/pages/home/` - sekcje złożone przez `web/src/pages/home/index.vue`. Trasy to cienkie wrappery pod `web/src/pages/[lang]/`:\n\n```vue\n<!-- web/src/pages/[lang]/home.vue -->\n<script setup lang=\"ts\">\nimport NucHomePage from '../home/index.vue'\n</script>\n<template><NucHomePage /></template>\n```\n\n---\n\n## 3. Zrozum przepływ żądania\n\n```txt\nPrzeglądarka  →  strona Nuxt (web/src/pages/)\n              →  shared_modules/nuc_*/utils/   (composables, klient API)\n              →  /api/*                         (bramka Nitro)\n              →  nuc_*/supabase/api/handle.ts   (handlery modułów)\n              →  Supabase (PostgreSQL, Auth, Edge Functions)\n```\n\nSzybki test bramki:\n\n```bash\ncurl http://localhost:3000/api\ncurl http://localhost:3000/api/test\n```\n\n---\n\n## 4. Zaimportuj moduł współdzielony\n\nModuły rozwiązują się przez alias `modules` (`web/.config/nuxt/structure.ts` → `shared_modules/`):\n\n```typescript\nimport { useDarkMode } from 'modules/nuc_dark_mode/utils/use_dark_mode'\nimport { apiRequest } from 'modules/nuc_api/utils/api_request'\n```\n\nCztery moduły rejestrują się automatycznie przy starcie aplikacji w `web/src/plugins/modules.ts`:\n\n- `nuc_globals`\n- `nuc_colors`\n- `nuc_dark_mode`\n- `nuc_languages`\n\n`nuc_api` i `nuc_stores` importujesz tam, gdzie są potrzebne - bez globalnej rejestracji pluginu.\n\n---\n\n## 5. Wypróbuj kompilator\n\nZbuduj emisję przenośną z dowolnych `*.nuc.tsx` pod korzeniami odkrywania (`web/`, `admin/`, `shared_modules/`, `portable/`):\n\n```bash\npnpm compiler:build\npnpm compiler:check   # exit 1, jeśli emit jest brudny względem autorstwa\n```\n\nSkonwertuj cały produkt web na Next, Solid lub Svelte:\n\n```bash\nmake web TARGET=next    # → web-next/\nmake web TARGET=solid   # → web-solid/\nmake web TARGET=svelte  # → web-svelte/\n```\n\nTo uruchamia `pnpm compiler -- convert web --target=…`, buduje, instaluje i startuje wygenerowany shell. Demo emit portable Svelte: `make svelte`. Zewnętrzne aplikacje Nuxt-like: `--path` / `--git` + `--out` z roota monorepo (zob. [Kompilator](/pl/docs/core-concepts/compiler)).\n\n---\n\n## 6. Uruchom inne aplikacje\n\n```bash\nmake admin    # admin Nuxt w admin/src/pages/\nmake docs     # docs Astro na http://localhost:4321 (domyślny port Astro)\n```\n\nTreść docs to Markdown w `docs/content/{en,pl}/{category}/{slug}.md`.\n\n---\n\n## 7. Uruchom sprawdzenia\n\nPrzed commitem hook Husky pre-commit uruchamia ten sam zestaw co CI (pre-push jest no-op):\n\n```bash\npnpm btest          # suite bash\npnpm check          # Biome\npnpm typeslint      # TypeScript (web)\npnpm slint          # Stylelint (SCSS)\npnpm build          # produkcyjny build Nuxt\npnpm tests          # Vitest (web + shared)\npnpm compiler:test  # testy jednostkowe kompilatora\npnpm compiler:check # odciski emit\n```\n\n---\n\n## Typowe zadania\n\n### Dodaj trasę API do istniejącego modułu\n\n1. Dodaj handlery w `shared_modules/nuc_example/supabase/api/example_handlers.ts`\n2. Wyeksportuj `handleExampleApi` z `handle.ts`\n3. Zarejestruj handler w `shared_modules/nuc_api/supabase/api/gateway_dispatch.ts`\n4. Wywołuj `/api/example/...` z klienta przez helpery requestów `nuc_api`\n\n### Nadpisz plik bez edycji upstream\n\nOdwzoruj ścieżkę pod `overrides/`:\n\n```txt\nweb/src/composables/useAuth.ts\n  → overrides/web/src/composables/useAuth.ts\n```\n\nZobacz [Nadpisywanie](/pl/docs/core-concepts/overriding).\n\n### Autorsuj komponent przenośny\n\nUtwórz `Foo.nuc.tsx` obok miejsca użycia. Uruchom `pnpm compiler:build`. Commituj `.nuc.tsx` i wygenerowane sąsiednie pliki (`.vue`, React/Solid `.tsx`, Svelte `.svelte`, `.css`). Nie edytuj ręcznie emitu jako źródła prawdy - użyj `pnpm compiler -- import --from=vue|react|solid|svelte`, jeśli edytowałeś emit.\n\n---\n\n## Co dalej\n\n| Temat | Doc |\n|-------|-----|\n| Mapa katalogów | [Układ monorepo](/pl/docs/core-concepts/monorepo) |\n| Anatomia modułu | [Moduły](/pl/docs/core-concepts/modules) |\n| Cykle kompilatora | [Kompilator](/pl/docs/core-concepts/compiler) |\n| Konfiguracja Nuxt | [Web & Admin](/pl/docs/configuration/web) |\n| Workflow Supabase | [Supabase](/pl/docs/configuration/supabase) |\n| Testy | [Vitest](/pl/docs/tests/vitest) |\n",
  "pl/tests/vitest": "# Vitest\n\nNucleify używa [Vitest](https://vitest.dev) do testów jednostkowych i integracyjnych w monorepo. Root config definiuje dwa projekty - **web** (środowisko Nuxt) i **shared** (happy-dom) - plus osobny suite kompilatora.\n\n---\n\n## Uruchamianie testów\n\n```bash\npnpm tests              # wszystkie projekty root (web + shared)\npnpm test:watch         # tryb watch\npnpm test:web           # tylko projekt Nuxt\npnpm test:shared        # tylko shared_modules\npnpm compiler:test      # testy jednostkowe kompilatora\n```\n\nCI i hook Husky pre-commit uruchamiają `pnpm tests` jako część `.config/bash/hook-checks.sh` wraz z testami bash, Biome, TypeScript, Stylelint, buildem Nuxt i checkami kompilatora (pre-push jest no-op).\n\n---\n\n## Konfiguracja projektów\n\nRoot `vitest.config.ts` definiuje projekty workspace:\n\n### Projekt `web`\n\n- **Root:** `web/`\n- **Środowisko:** `nuxt` (przez `@nuxt/test-utils`)\n- **Include:** `vitests/**/*.{test,spec}.{js,ts,jsx,tsx}`\n- **Timeout:** 30s\n- **Alias:** `nucleify` → `web/src/nucleify.ts`\n\n### Projekt `shared`\n\n- **Root:** `shared_modules/`\n- **Środowisko:** `happy-dom`\n- **Include:** `**/vitests/**/*.{test,spec}.{js,ts}`\n- **Timeout:** 15s\n- **Alias:** `nucleify` → `shared_modules/nucleify.ts`\n- **Define:** shimy `import.meta.client` / `import.meta.server`\n\nOba projekty dzielą setup z `.config/vitest_setup.ts` i używają threaded pools.\n\n### Projekt kompilatora\n\nOsobny config w `.config/vitest.compiler.config.ts`:\n\n```bash\npnpm compiler:test\n```\n\nTesty są w `compiler/tests/` (w tym goldeny emit/import dla Vue, React, Solid i Svelte).\n\n---\n\n## Gdzie kłaść testy\n\n| Lokalizacja | Wzorzec | Projekt |\n|-------------|---------|---------|\n| `web/vitests/` | `*.test.ts` | web |\n| `shared_modules/nuc_*/vitests/` | `*.test.ts` | shared |\n| `compiler/tests/` | fixtures + unit | compiler |\n\nTrzymaj testy modułu wewnątrz modułu (`shared_modules/nuc_colors/vitests/`). Nie kładź testów shared modules pod `web/vitests/`, chyba że wymagają runtime Nuxt.\n\n---\n\n## Pisanie testów modułu\n\nPrzykład pod `shared_modules/nuc_colors/vitests/`:\n\n```typescript\nimport { describe, expect, it } from 'vitest'\nimport { darkenColor } from '../../utils/darken_color'\n\ndescribe('darkenColor', () => {\n  it('darkens a hex color', () => {\n    expect(darkenColor('#ffffff', 0.1)).toMatch(/^#[0-9a-f]{6}$/i)\n  })\n})\n```\n\nUruchom tylko testy shared podczas iteracji:\n\n```bash\npnpm test:shared\n```\n\n---\n\n## Pisanie testów Nuxt\n\nPliki w `web/vitests/`. Środowisko Nuxt montuje komponenty przez `@nuxt/test-utils`:\n\n```typescript\nimport { describe, expect, it } from 'vitest'\nimport { mountSuspended } from '@nuxt/test-utils/runtime'\nimport MyComponent from '~/components/MyComponent.vue'\n\ndescribe('MyComponent', () => {\n  it('renders', async () => {\n    const wrapper = await mountSuspended(MyComponent)\n    expect(wrapper.text()).toContain('expected')\n  })\n})\n```\n\n---\n\n## Plik setup\n\n`.config/vitest_setup.ts` konfiguruje globalne zachowanie testów (mocki, matchery z `@testing-library/jest-dom` gdzie używane). Oba projekty importują go przez `setupFiles`.\n\nTłumienie logów konsoli jest włączone (`onConsoleLog: () => false`), żeby zmniejszyć szum w CI.\n\n---\n\n## Suite pre-commit\n\nHusky pre-commit uruchamia (przez `.config/bash/hook-checks.sh`), w kolejności:\n\n1. `pnpm btest` - suite bash\n2. `pnpm check` - Biome\n3. `pnpm typeslint` - TypeScript (`web/tsconfig.json`)\n4. `pnpm slint` - Stylelint na SCSS\n5. `pnpm build` - produkcyjny build Nuxt\n6. `pnpm tests` - Vitest\n7. `pnpm compiler:test` - testy jednostkowe kompilatora\n8. `pnpm compiler:check` - odciski emit\n\nPre-push jest no-op. Napraw błędy lokalnie przed commitem.\n\n---\n\n## Coverage i debug\n\nJeden plik:\n\n```bash\npnpm vitest run shared_modules/nuc_stores/cookie/get_item/index.test.ts\npnpm vitest run --project web web/vitests/some.test.ts\n```\n\nWatch w development:\n\n```bash\npnpm test:watch\n```\n\n---\n\n## Powiązana dokumentacja\n\n- [Moduły](/pl/docs/core-concepts/modules) - konwencja folderu `vitests/`\n- [Standardy kodowania](/pl/docs/about/coding-standards) - nazewnictwo i struktura\n- [Kompilator](/pl/docs/core-concepts/compiler) - `pnpm compiler:test`\n",
}

export function getBundledMarkdown(
  lang: string,
  category: string,
  slug: string
): string | null {
  return MARKDOWN_BUNDLE[`${lang}/${category}/${slug}`] ?? null
}
